INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C1','soc',6,2,'u3',1,'인구 분포에 영향을 주는 요인 — 기온·강수량·지형 등 자연환경과 산업·교통·문화 등 인문환경이 인구 분포에 많은 영향을 줌 · 옛날에는 기후가 온화한 지역·평야·해안처럼 자연환경이 유리한 곳에, 오늘날에는 산업이 발달해 일자리가 풍부하고 교통이 편리하며 교육·문화 시설이 갖춰진 곳에 모여 삶',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C2','soc',6,2,'u3',1,'세계의 인구 분포 특징 — 세계 인구는 고르게 분포하지 않고 특정 지역에 모여 있음 · 세계 인구의 약 90 %가 육지가 많은 북반구에, 기후가 온화한 중위도에 많고 냉대·한대 기후의 고위도에 적음 · 동아시아와 남부 아시아(온화한 평야·농업)·서부 유럽(산업·일자리·교통)에 많고, 사하라 사막(강수량 매우 적음)·알래스카(기온 매우 낮음)·열대 우림에 적음 · 100명 마을이면 아시아 59명·오세아니아 1명 · 세계 인구는 약 25억 명(1950)에서 약 81억 명(2023)으로 늘고 아프리카 비율이 크게 늘었음(비율이 줄어도 수가 준 것은 아님)',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C3','soc',6,2,'u3',2,'세계 여러 나라의 인구수 — 나라마다 다르며 대체로 아시아의 나라들은 많고 오세아니아의 나라들은 적음(10억 명 이상은 인도·중국) · 면적이 넓다고 반드시 인구수가 많은 것은 아님 · 인도(강수량 많고 비옥한 토양·농업·높은 출생률), 미국(온화한 기후·다양한 산업·이민), 리비아(국토 대부분 사막이라 면적에 비해 적음), 투발루(작은 섬나라, 기후변화로 잠길 위험) · 인구 성장률은 인구가 증가하는 비율로 아프리카는 높고 유럽은 낮거나 감소 · 인구수는 출생·사망·인구의 이동·환경 변화에 따라 달라짐',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C4','soc',6,2,'u3',3,'세계 여러 나라의 인구 밀도 — 일정한 면적(1 km²) 안에 사는 인구수로 인구가 모여 있는 정도를 나타냄, 면적에 비해 인구수가 많을수록 높음 · 방글라데시·르완다·인도는 높고 몽골·오스트레일리아·캐나다는 낮음, 아시아·유럽에 높은 나라가 많고 고위도에 낮은 나라가 많음 · 방글라데시(약 1,317명/km², 국토 대부분 평야·온화한 기후·벼농사) vs 캐나다(약 4명/km², 냉대 기후라 농사지을 땅이 적음) · 우리나라(약 515명/km²)는 면적이 비슷한 나라보다 매우 높은 편 · 인구가 늘면 밀도도 높아지는 등 변화할 수 있음',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C5','soc',6,2,'u3',4,'인구 구조와 인구 피라미드 — 인구 구조는 연령·성 등을 기준으로 한 인구의 짜임새(유소년층 0~14세·청장년층 15~64세·노년층 65세 이상) · 인구 피라미드는 연령별·성별 인구를 나타낸 그래프(가로축 왼쪽 남자·오른쪽 여자 비율, 세로축 나이) · 세계 인구 구조는 1960년보다 2020년에 유소년층 비율이 줄고 노년층 비율이 늘었으며 청장년층 비율이 가장 높음 · 출생률·사망률이 높고 평균 수명이 짧으면 유소년층이 많고(나이지리아), 낮고 길면 노년층이 많음(일본)',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C6','soc',6,2,'u3',4,'인구 구조와 우리 생활 — 인구 구조로 미래 인구 변화를 예상할 수 있고 경제·문화 등 생활과 밀접함 · 유소년층이 많은 나라는 유치원·학교 같은 어린이 시설, 노년층이 많은 나라는 요양원·노인 복지 센터가 더 필요함 · 청장년층 비율이 높은 인도네시아는 젊은 소비자가 많아 기업이 주목하는 「젊은 시장」 · 석유 자원이 풍부한 사우디아라비아·아랍 에미리트 등은 외국인 근로자를 받아들여 청장년층이 두드러지게 많음 · 아이를 더 낳거나 덜 낳도록 권하는 포스터도 인구 구조와 관련',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C7','soc',6,2,'u3',5,'지구촌과 지구촌을 위협하는 문제 — 지구촌은 과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습(소식·정보·문화 교류가 쉬워진 좋은 점, 한 나라의 문제가 다른 나라에 영향을 주고 갈등이 생길 수 있는 문제점) · 지구촌은 자원과 에너지 고갈(광산 개발), 생태계 파괴(열대 우림 벌채 — 농사·목축·산업 등 인간 활동이 원인, 동식물의 터전과 탄소 흡수가 사라짐), 기후변화(화석 연료 과다 사용 — 녹는 빙하), 난민(전쟁·재난으로 살던 곳을 떠남) 문제를 겪음 · 지구촌 전등 끄기 캠페인처럼 함께 노력함',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C8','soc',6,2,'u3',6,'지구촌 문제 조사하기 — 문제 생각하기 → 조사 방법 정하기 → 문제 상황·원인 조사하기 → 내용 정리하기 · 자료는 누리집 통계·책·신문 기사·카드 뉴스·다큐멘터리, 출처가 명확하고 믿을 만한지 확인 · 붙임쪽지에 지역·문제 상황·문제 원인을 요약해 세계지도의 해당 나라에 붙이면 지구촌 곳곳의 문제를 한눈에 파악 · 탄소를 적게 내는 나라가 가뭄을 겪고(동아프리카), 해수면 상승으로 섬이 잠기는(투발루) 것처럼 지구촌 문제는 한 지역에 그치지 않는 우리 모두의 문제 · 옷 한 벌에도 많은 물이 들어 내 작은 행동이 지구에 영향을 줌',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C9','soc',6,2,'u3',7,'지속가능한 미래와 개인·기업·국가의 노력 — 지속가능한 미래는 오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어짐(인간 위주가 아니라 지구촌 모두를 생각하는 자세) · 개인: 녹색 제품 소비(생산 때 자원·에너지를 적게 써 오염 물질 최소화), 일회용품 줄이기, 분리배출·재활용, 에너지 절약 · 기업: 탄소를 줄이는 제품·친환경 소재·자원을 적게 쓴 제품(라벨 없앤 생수병), 책임 있는 경영 · 국가: 법과 제도·정책, 국제 협약 준수(기후변화 협약), 난민 보호 · 여러 주체의 노력이 모두 모여야 함',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C10','soc',6,2,'u3',7,'국제기구와 비정부 기구의 노력 — 국제기구: 국제 연합(국제 평화와 안전·협력), 국제 연합 아동 기금(어려운 어린이에게 의료·식량·교육), 국제 연합 난민 기구(난민 보호·물품·의료·교육) · 비정부 기구는 개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체: 국경 없는 의사회(차별 없는 의료), 세계 자연 기금(생물 다양성·기후변화 대응), 그린피스(환경 연구·해양 생태계 보호)',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C11','soc',6,2,'u3',8,'세계시민과 실천 — 세계시민은 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람으로, 지구촌 문제를 우리 모두의 문제로 여기고 관심을 두며 해결 방법을 고민함 · 할 일을 정할 때 일상에서 실천 가능한지·효과가 있는지 생각하고 더하기(+) 노력(장바구니·다회용품)과 빼기(−) 노력(플라스틱 덜 쓰기·안 쓰는 전등 끄기)을 구분 · 실천 인증 릴레이: 인증 사진 → 구체적 기록 → 다음 친구에게 알리기 · 개인의 노력이 기업과 사회의 변화를 만들 수 있음 · 주제를 정할 때 서로 다른 관심을 존중 · 에코 제품 디자이너처럼 직업으로도 이바지',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C12','soc',6,2,'u3',9,'그림책 스토리보드 만들기 — 스토리보드는 장면을 구성하며 이야기의 흐름을 작성한 것으로 장면별 줄거리와 스케치 형식의 그림(그림 순서·그림·그림 설명·글·대사 칸)이 들어감 · 계획: 주제·줄거리, 독자를 정하고 그 수준에 맞게(어린 독자면 쉬운 낱말·짧은 문장), 세계 인구의 특징과 지속가능한 지구촌이 골고루 드러나게, 이야기 흐름이 자연스럽게 · 역할을 나누어 만들고 발표회에서 내용과 수준이 적절한지, 계획대로 만들었는지 살펴봄',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X01','soc',6,'u3',ARRAY['SO6-2-u3-C1']::text[],'인구 분포에 영향을 주는 자연환경 요인(기온·강수량·지형)과 인문환경 요인(산업·교통·문화)을 바꾸어 나눈다','자연이 만든 것 · 사람이 만든 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X02','soc',6,'u3',ARRAY['SO6-2-u3-C1','SO6-2-u3-C2']::text[],'세계 인구가 고르게 퍼져 있다고, 또는 땅이 넓은 곳일수록 사람이 많다고 여긴다','특정한 지역에 모여 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X03','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구가 많은 지역과 적은 지역, 그 까닭을 바꾸어 짝짓는다(알래스카·사하라에 많다고, 서부 유럽은 기후 탓에 적다고 하는 등)','점이 빽빽한 곳과 드문 곳의 환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X04','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구가 많은 반구와 위도를 거꾸로 안다(남반구·고위도에 많다고)','북반구 약 90 % · 온화한 중위도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X05','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구 비율과 인구수를 같은 것으로 여기거나(비율이 줄면 수도 줄었다고) 세계 인구의 변화를 거꾸로 읽는다','비율 ≠ 인구수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X06','soc',6,'u3',ARRAY['SO6-2-u3-C3','SO6-2-u3-C4']::text[],'나라의 면적이 넓으면 인구수도 많다고 여긴다','넓어도 살기 어려우면 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X07','soc',6,'u3',ARRAY['SO6-2-u3-C3']::text[],'대륙·나라별 인구수의 많고 적음과 그 까닭을 바꾸어 안다(오세아니아에 인구가 많다고, 리비아가 사막 때문에 인구가 많다고 하는 등)','아시아는 많고 오세아니아는 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X08','soc',6,'u3',ARRAY['SO6-2-u3-C3']::text[],'인구 성장률의 뜻이나 인구수를 바꾸는 요인(출생·사망·이동·환경 변화)을 잘못 안다','늘어나는 비율 · 들어오고 나가고 태어나고 사망하고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X09','soc',6,'u3',ARRAY['SO6-2-u3-C4']::text[],'인구 밀도를 인구수만으로, 또는 면적만으로 판단한다','1 km² 안의 인구수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X10','soc',6,'u3',ARRAY['SO6-2-u3-C4']::text[],'인구 밀도가 높은 나라와 낮은 나라, 그 까닭(평야·벼농사 / 냉대 기후)을 바꾸어 안다','방글라데시 높음 · 캐나다 낮음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X11','soc',6,'u3',ARRAY['SO6-2-u3-C5']::text[],'인구 구조의 뜻이나 인구 피라미드의 축(가로 — 남녀 비율, 세로 — 나이)·연령층을 잘못 읽는다','아래층 유소년 · 위층 노년') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X12','soc',6,'u3',ARRAY['SO6-2-u3-C5']::text[],'출생률·사망률·평균 수명과 인구 구조의 관계를 거꾸로 안다(출생률이 낮은 나라에 유소년층이 많다고 하는 등)','낮은 출생률 → 노년층 비율 높음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X13','soc',6,'u3',ARRAY['SO6-2-u3-C6']::text[],'인구 구조와 생활(필요한 시설·젊은 시장·외국인 근로자)을 맞지 않게 잇는다','많은 연령층에 맞는 시설과 시장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X14','soc',6,'u3',ARRAY['SO6-2-u3-C7']::text[],'지구촌의 뜻을 오해하거나 지구촌 시대의 좋은 점과 문제점을 바꾸어 안다','하나의 마을처럼 가까워진 지구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X15','soc',6,'u3',ARRAY['SO6-2-u3-C7','SO6-2-u3-C8']::text[],'지구촌 문제(자원·에너지 고갈, 생태계 파괴, 기후변화, 난민)와 그 장면·원인을 바꾸어 짝짓는다','광산 · 열대 우림 · 빙하 · 보트') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X16','soc',6,'u3',ARRAY['SO6-2-u3-C7','SO6-2-u3-C8','SO6-2-u3-C11']::text[],'지구촌 문제를 그 나라만의 일로 여겨 나와 관계없다고 생각한다','우리 모두의 문제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X17','soc',6,'u3',ARRAY['SO6-2-u3-C8']::text[],'지구촌 문제를 조사할 때 출처를 확인하지 않거나, 지역·문제 상황·원인 가운데 일부를 빠뜨린다','믿을 만한 자료 · 지역·상황·원인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X18','soc',6,'u3',ARRAY['SO6-2-u3-C9']::text[],'지속가능한 미래를 지금 세대의 편리함만 생각하는 것으로, 또는 인간 위주로 생각하는 것으로 오해한다','미래 세대에 물려주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X19','soc',6,'u3',ARRAY['SO6-2-u3-C9']::text[],'개인·기업·국가가 하는 노력을 서로 바꾸어 짝짓는다','생활 속 실천 · 제품 · 법과 협약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X20','soc',6,'u3',ARRAY['SO6-2-u3-C10']::text[],'국제기구와 비정부 기구를 헷갈리거나 각 단체가 하는 일을 바꾸어 안다','나라들이 만든 기구 · 민간이 만든 단체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X21','soc',6,'u3',ARRAY['SO6-2-u3-C11']::text[],'세계시민의 자세와 실천 방법을 잘못 안다(나 하나로는 소용없다고, 실천하기 어려운 계획을 세우거나 더하기·빼기 노력을 바꾸는 등)','작은 일부터 · 책임감 · 실천 가능하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X22','soc',6,'u3',ARRAY['SO6-2-u3-C12']::text[],'그림책 스토리보드를 만들 때 독자의 수준·이야기의 흐름·단원 주제를 고려하지 않는다','누가 읽나 · 흐름 · 두 주제 골고루') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X23','soc',6,'u3',ARRAY['SO6-2-u3-C2','SO6-2-u3-C3','SO6-2-u3-C4']::text[],'인구 공부를 나라별 인구수·수치를 외우는 것으로 여겨 자료에서 특징과 까닭을 읽어 내는 것을 놓친다','외우기보다 자료를 읽고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#1','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C1',1,'mc','auto','인구 분포에 영향을 주는 자연환경 요인끼리 묶인 것은 어느 것인가요?',ARRAY['SO6-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C1","difficulty":1,"kind":"mc","stem":"인구 분포에 영향을 주는 자연환경 요인끼리 묶인 것은 어느 것인가요?","options":[{"t":"기온·강수량·지형","correct":true},{"t":"산업·교통·문화","mis":"SO6-2-u3-X01"},{"t":"기온·산업·교통","mis":"SO6-2-u3-X01"},{"t":"지형·문화·교통","mis":"SO6-2-u3-X01"}],"explanation":["자연이 만든 환경이에요.","기온·강수량·지형이에요.","산업·교통·문화는 인문환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#2','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'mc','auto','100명 마을 자료에서 사람이 가장 많이 사는 대륙은 어디인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"100명 마을 자료에서 사람이 가장 많이 사는 대륙은 어디인가요?","options":[{"t":"아시아","correct":true},{"t":"오세아니아","mis":"SO6-2-u3-X07"},{"t":"유럽","mis":"SO6-2-u3-X07"},{"t":"아프리카","mis":"SO6-2-u3-X07"}],"explanation":["가장 큰 수를 찾아요.","아시아에 59명이 살아요.","아시아가 가장 많아요."],"asset":{"type":"passage","lines":["세계가 100명이 사는 마을이라면 — 아시아 59명","아프리카 · 유럽 · 아메리카 대륙에 나머지가 산다.","오세아니아 1명 — 가장 적다."],"title":"100명 마을 자료(국제 연합 자료를 줄인 것)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#3','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'sa','auto','세계 인구의 약 90 %가 사는 반구는 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"sa","stem":"세계 인구의 약 90 %가 사는 반구는 어디인가요? 세 글자로 쓰세요.","answer":["북반구"],"explanation":["육지가 많은 쪽이에요.","적도 위쪽이에요.","북반구예요."],"mis":"SO6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#4','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'ox','auto','세계의 인구는 지구 곳곳에 고르게 분포해요.',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"ox","stem":"세계의 인구는 지구 곳곳에 고르게 분포해요.","answer":"X","reason_options":[{"t":"특정한 지역에 모여 있어 많은 곳과 적은 곳이 있기 때문에","correct":true},{"t":"모든 대륙에 똑같은 수의 사람이 살기 때문에","mis":"SO6-2-u3-X02"}],"mis":"SO6-2-u3-X02","explanation":["점이 빽빽한 곳이 있어요.","드문 곳도 있어요.","고르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#5','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'match','auto','지역과 인구가 많거나 적은 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"match","stem":"지역과 인구가 많거나 적은 까닭을 알맞게 이으세요.","pairs":[{"l":"동아시아와 남부 아시아","r":"온화한 평야에서 농업 발달"},{"l":"서부 유럽","r":"산업 발달·풍부한 일자리"},{"l":"사하라 사막","r":"강수량이 매우 적음"},{"l":"알래스카","r":"기온이 매우 낮음"}],"mis":"SO6-2-u3-X03","explanation":["평야와 산업이 있으면 많아요.","물이 없으면 적어요.","너무 추워도 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#6','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'mc','auto','돋보기로 본 네 지역 가운데 인구가 적은 까닭이 「기온이 매우 낮아 생활하기 어렵다」인 곳은 어디인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"돋보기로 본 네 지역 가운데 인구가 적은 까닭이 「기온이 매우 낮아 생활하기 어렵다」인 곳은 어디인가요?","options":[{"t":"㉱ 알래스카","correct":true},{"t":"㉰ 사하라 사막","mis":"SO6-2-u3-X03"},{"t":"㉯ 서부 유럽","mis":"SO6-2-u3-X03"},{"t":"㉮ 동아시아와 남부 아시아","mis":"SO6-2-u3-X03"}],"explanation":["고위도의 추운 곳이에요.","식물이 자라기 어려워요.","알래스카예요."],"asset":{"type":"passage","lines":["㉮ 동아시아와 남부 아시아 — 점이 빽빽하다.","㉯ 서부 유럽 — 점이 빽빽하다.","㉰ 사하라 사막 — 점이 드물다.","㉱ 알래스카 — 점이 드물다."],"title":"돋보기로 본 네 지역"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#7','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'mc','auto','인구가 많이 분포하는 위도와 그 까닭을 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X02']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"인구가 많이 분포하는 위도와 그 까닭을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"중위도 — 온대 기후처럼 온화한 기후가 나타나서","correct":true},{"t":"고위도 — 냉대·한대 기후가 나타나서","mis":"SO6-2-u3-X04"},{"t":"저위도 — 기온이 매우 높아서","mis":"SO6-2-u3-X04"},{"t":"세 위도에 똑같이 분포해서","mis":"SO6-2-u3-X02"}],"explanation":["온화한 기후가 열쇠예요.","생활하고 농사짓기 좋아요.","중위도에 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#8','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C1',2,'mc','auto','오늘날 사람들이 많이 모여 사는 곳의 특징으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"mc","stem":"오늘날 사람들이 많이 모여 사는 곳의 특징으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산업이 발달해 일자리가 풍부하고 교통이 편리한 곳","correct":true},{"t":"강수량이 매우 적은 사막","mis":"SO6-2-u3-X03"},{"t":"기온이 매우 낮은 극지방","mis":"SO6-2-u3-X03"},{"t":"열대 우림이 우거진 곳","mis":"SO6-2-u3-X03"}],"explanation":["오늘날엔 인문환경이 중요해요.","일자리와 교통을 찾아요.","그런 곳에 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#9','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'ox','auto','세계 인구는 1950년 약 25억 명에서 2023년 약 81억 명으로 크게 늘었어요.',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"ox","stem":"세계 인구는 1950년 약 25억 명에서 2023년 약 81억 명으로 크게 늘었어요.","answer":"O","reason_options":[{"t":"대륙별 세계 인구의 변화 자료에서 세계 인구가 늘었음을 읽을 수 있기 때문에","correct":true},{"t":"세계 인구는 1950년보다 줄어들었기 때문에","mis":"SO6-2-u3-X05"}],"mis":"SO6-2-u3-X05","explanation":["25억에서 81억이에요.","세 배 넘게 늘었어요.","인구가 크게 늘었어요."],"asset":{"type":"passage","lines":["세계 인구 — 1950년 약 25억 명 → 2023년 약 81억 명","세계 인구에서 차지하는 비율이 늘어난 대륙 — 아프리카(크게)·아시아 등","세계 인구에서 차지하는 비율이 줄어든 대륙 — 유럽·북아메리카"],"title":"대륙별 세계 인구의 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_basic#10','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',3,'mc','auto','세계 인구에서 유럽이 차지하는 비율이 줄었어요. 이것을 바르게 해석한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"세계 인구에서 유럽이 차지하는 비율이 줄었어요. 이것을 바르게 해석한 것은 어느 것인가요?","options":[{"t":"세계 인구 가운데 유럽이 차지하는 몫이 작아진 것이지, 유럽 인구수가 반드시 줄었다는 뜻은 아니다","correct":true},{"t":"유럽의 인구수가 반드시 줄었다","mis":"SO6-2-u3-X05"},{"t":"유럽의 면적이 좁아졌다","mis":"SO6-2-u3-X05"},{"t":"세계 인구가 줄었다","mis":"SO6-2-u3-X05"}],"explanation":["비율과 인구수는 달라요.","전체가 크게 늘었어요.","몫이 작아진 거예요."],"asset":{"type":"passage","lines":["세계 인구 — 1950년 약 25억 명 → 2023년 약 81억 명","세계 인구에서 차지하는 비율이 늘어난 대륙 — 아프리카(크게)·아시아 등","세계 인구에서 차지하는 비율이 줄어든 대륙 — 유럽·북아메리카"],"title":"대륙별 세계 인구의 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#1','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C1',2,'sa','auto','산업·교통·문화처럼 사람이 만든 환경을 무엇이라고 하나요? (□□환경)','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"sa","stem":"산업·교통·문화처럼 사람이 만든 환경을 무엇이라고 하나요? (□□환경)","answer":["인문"],"explanation":["사람이 만든 환경이에요.","산업·교통·문화예요.","인문환경이에요."],"mis":"SO6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#2','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',2,'mc','auto','세계의 인구 분포 지도에서 점이 많을수록 무엇을 나타내나요?',ARRAY['SO6-2-u3-X03','SO6-2-u3-X06']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"세계의 인구 분포 지도에서 점이 많을수록 무엇을 나타내나요?","options":[{"t":"인구가 많이 분포한다","correct":true},{"t":"땅이 높다","mis":"SO6-2-u3-X03"},{"t":"비가 많이 온다","mis":"SO6-2-u3-X03"},{"t":"나라가 넓다","mis":"SO6-2-u3-X06"}],"explanation":["인구를 점으로 나타냈어요.","점이 빽빽하면 많아요.","인구가 많이 분포해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#3','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','돋보기로 본 네 지역에서 ㉯ 서부 유럽에 인구가 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"돋보기로 본 네 지역에서 ㉯ 서부 유럽에 인구가 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기후가 온화하고 산업이 발달해 일자리가 풍부하며 교통이 편리하기 때문에","correct":true},{"t":"강수량이 매우 적기 때문에","mis":"SO6-2-u3-X03"},{"t":"기온이 매우 낮기 때문에","mis":"SO6-2-u3-X03"},{"t":"열대 우림이 우거졌기 때문에","mis":"SO6-2-u3-X03"}],"explanation":["㉯는 점이 빽빽해요.","산업과 교통이 갖춰졌어요.","일자리를 찾아 모여요."],"asset":{"type":"passage","lines":["㉮ 동아시아와 남부 아시아 — 점이 빽빽하다.","㉯ 서부 유럽 — 점이 빽빽하다.","㉰ 사하라 사막 — 점이 드물다.","㉱ 알래스카 — 점이 드물다."],"title":"돋보기로 본 네 지역"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#4','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C1',3,'mc','auto','옛날과 오늘날 사람들이 모여 산 곳을 가장 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-2-u3-X01','SO6-2-u3-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C1","difficulty":3,"kind":"mc","stem":"옛날과 오늘날 사람들이 모여 산 곳을 가장 바르게 견준 것은 어느 것인가요?","options":[{"t":"옛날 — 자연환경이 유리한 평야·해안 / 오늘날 — 일자리·교통·교육 시설이 갖춰진 곳","correct":true},{"t":"옛날 — 일자리가 많은 도시 / 오늘날 — 사막과 극지방","mis":"SO6-2-u3-X01"},{"t":"옛날과 오늘날 모두 자연환경만 본다","mis":"SO6-2-u3-X01"},{"t":"옛날과 오늘날 모두 아무 곳에나 고르게 산다","mis":"SO6-2-u3-X02"}],"explanation":["옛날엔 자연환경이 중요했어요.","오늘날엔 인문환경도 중요해요.","모이는 까닭이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#5','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'ox','auto','같은 대륙이나 같은 나라 안에서도 지역마다 사람들이 모여 사는 정도가 달라요.',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"ox","stem":"같은 대륙이나 같은 나라 안에서도 지역마다 사람들이 모여 사는 정도가 달라요.","answer":"O","reason_options":[{"t":"지역마다 기후·지형·산업 같은 환경이 다르기 때문에","correct":true},{"t":"한 나라 안에서는 모두 똑같이 모여 살기 때문에","mis":"SO6-2-u3-X02"}],"mis":"SO6-2-u3-X02","explanation":["한 나라 안도 달라요.","환경이 지역마다 달라요.","모여 사는 정도도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#6','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'error','auto','세계의 인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X07','SO6-2-u3-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"error","stem":"세계의 인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「세계 인구는 대부분 남반구의 추운 고위도에 살아.」","correct":true,"mis_target":"SO6-2-u3-X04"},{"t":"시온 — 「아시아에 사람이 가장 많아.」","mis":"SO6-2-u3-X07"},{"t":"도겸 — 「사하라 사막에는 물이 부족해 사람이 적어.」","mis":"SO6-2-u3-X03"}],"explanation":["세계 인구의 약 90 %는 북반구에 살아요.","고위도는 추워 적어요.","하율이 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#7','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'mc','auto','대륙별 세계 인구의 변화 자료에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"대륙별 세계 인구의 변화 자료에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"세계 인구가 크게 늘었고 아프리카가 차지하는 비율이 크게 늘었다","correct":true},{"t":"모든 대륙의 비율이 똑같이 늘었다","mis":"SO6-2-u3-X05"},{"t":"세계 인구는 그대로이다","mis":"SO6-2-u3-X05"},{"t":"유럽의 비율이 가장 크게 늘었다","mis":"SO6-2-u3-X05"}],"explanation":["25억에서 81억으로 늘었어요.","아프리카 몫이 커졌어요.","유럽 몫은 줄었어요."],"asset":{"type":"passage","lines":["세계 인구 — 1950년 약 25억 명 → 2023년 약 81억 명","세계 인구에서 차지하는 비율이 늘어난 대륙 — 아프리카(크게)·아시아 등","세계 인구에서 차지하는 비율이 줄어든 대륙 — 유럽·북아메리카"],"title":"대륙별 세계 인구의 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#8','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',4,'mc','auto','세계의 인구 분포를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X02','SO6-2-u3-X04','SO6-2-u3-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"mc","stem":"세계의 인구 분포를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"고르게 분포하지 않고 북반구, 온화한 중위도, 평야·해안, 일자리가 풍부한 지역에 많이 분포한다","correct":true},{"t":"모든 대륙에 똑같이 나뉘어 살고 자연환경만 영향을 준다","mis":"SO6-2-u3-X02"},{"t":"대부분 남반구에 살고 추운 고위도에 가장 많다","mis":"SO6-2-u3-X04"},{"t":"땅이 넓은 곳일수록 사람이 많다","mis":"SO6-2-u3-X06"}],"explanation":["인구는 모여 있어요.","북반구·중위도·평야예요.","일자리가 많은 곳도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#9','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C1',4,'mc','auto','「사하라 사막과 알래스카는 인구가 적다」는 사실을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03','SO6-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C1","difficulty":4,"kind":"mc","stem":"「사하라 사막과 알래스카는 인구가 적다」는 사실을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"두 곳 모두 자연환경이 생활에 불리하다 — 사막은 물이 매우 적고 알래스카는 기온이 매우 낮다","correct":true},{"t":"두 곳 모두 산업이 너무 발달했다","mis":"SO6-2-u3-X03"},{"t":"두 곳 모두 기후가 온화하다","mis":"SO6-2-u3-X03"},{"t":"두 곳 모두 땅이 좁다","mis":"SO6-2-u3-X06"}],"explanation":["사막은 물이 없어요.","알래스카는 매우 추워요.","자연환경이 불리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L01_challenge#10','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',4,'essay','teacher','돋보기로 본 네 지역과 까닭 카드를 보고 인구가 많은 곳 한 곳과 적은 곳 한 곳을 골라 까닭을 쓰고, 세계 인구 분포의 특징을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"essay","stem":"돋보기로 본 네 지역과 까닭 카드를 보고 인구가 많은 곳 한 곳과 적은 곳 한 곳을 골라 까닭을 쓰고, 세계 인구 분포의 특징을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 동아시아와 남부 아시아는 기후가 온화한 평야 지역이라 농업이 발달해 인구가 많다. 사하라 사막은 강수량이 매우 적어 물을 구하기 어려워 인구가 적다. 세계의 인구는 고르게 분포하지 않고 생활하기 좋은 환경을 갖춘 곳에 모여 있다.","scoring_points":["인구가 많은 곳과 까닭을 썼는가","인구가 적은 곳과 까닭을 썼는가","세계 인구 분포의 특징을 썼는가"]},"explanation":["많은 곳의 환경을 써요.","적은 곳의 환경을 써요.","고르지 않다는 점을 써요."],"asset":{"type":"passage","lines":["ⓐ 기후가 온화한 평야 지역으로 농업이 발달했다.","ⓑ 산업이 발달해 일자리가 풍부하고 교통이 편리하다.","ⓒ 강수량이 매우 적어 물을 구하기 어렵다.","ⓓ 기온이 매우 낮아 식물이 자라기 어렵다."],"title":"까닭 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#1','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'mc','auto','네 나라 인구 카드 가운데 인구수가 가장 많은 나라는 어디인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X07']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"mc","stem":"네 나라 인구 카드 가운데 인구수가 가장 많은 나라는 어디인가요?","options":[{"t":"인도","correct":true},{"t":"미국","mis":"SO6-2-u3-X23"},{"t":"리비아","mis":"SO6-2-u3-X07"},{"t":"투발루","mis":"SO6-2-u3-X07"}],"explanation":["수를 견주어요.","인도는 14억이 넘어요.","인도가 가장 많아요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#2','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'mc','auto','대체로 인구수가 많은 나라가 모여 있는 대륙은 어디인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X02']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"mc","stem":"대체로 인구수가 많은 나라가 모여 있는 대륙은 어디인가요?","options":[{"t":"아시아","correct":true},{"t":"오세아니아","mis":"SO6-2-u3-X07"},{"t":"남극","mis":"SO6-2-u3-X07"},{"t":"없다 — 모든 대륙이 같다","mis":"SO6-2-u3-X02"}],"explanation":["1억 명 넘는 나라가 많아요.","인도와 중국도 있어요.","아시아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#3','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'sa','auto','일정한 지역 안에 사는 인구가 증가하는 비율을 무엇이라고 하나요? (인구 □□□)','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"sa","stem":"일정한 지역 안에 사는 인구가 증가하는 비율을 무엇이라고 하나요? (인구 □□□)","answer":["성장률"],"explanation":["늘어나는 비율이에요.","아프리카가 높아요.","인구 성장률이에요."],"mis":"SO6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#4','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'ox','auto','나라의 면적이 넓으면 반드시 인구수도 많아요.',ARRAY['SO6-2-u3-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"ox","stem":"나라의 면적이 넓으면 반드시 인구수도 많아요.","answer":"X","reason_options":[{"t":"사람들이 살기 어려운 곳에 있는 나라는 넓어도 인구가 적기 때문에","correct":true},{"t":"면적과 인구수는 언제나 같이 늘기 때문에","mis":"SO6-2-u3-X06"}],"mis":"SO6-2-u3-X06","explanation":["넓어도 사막이면 적어요.","리비아가 그래요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#5','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','리비아가 국토의 면적에 비해 인구수가 적은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"리비아가 국토의 면적에 비해 인구수가 적은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"국토 대부분이 건조한 사막이기 때문에","correct":true},{"t":"산업이 매우 발달했기 때문에","mis":"SO6-2-u3-X07"},{"t":"작은 섬나라이기 때문에","mis":"SO6-2-u3-X07"},{"t":"강수량이 많고 토양이 비옥하기 때문에","mis":"SO6-2-u3-X07"}],"explanation":["리비아는 사막이 많아요.","물을 구하기 어려워요.","그래서 면적에 비해 적어요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#6','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','미국에 인구가 많은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"미국에 인구가 많은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후가 온화하고 다양한 산업이 발달해 일자리를 찾아 이민 오는 사람이 많기 때문에","correct":true},{"t":"국토 대부분이 사막이기 때문에","mis":"SO6-2-u3-X07"},{"t":"작은 섬나라이기 때문에","mis":"SO6-2-u3-X07"},{"t":"기온이 매우 낮기 때문에","mis":"SO6-2-u3-X03"}],"explanation":["다양한 산업이 있어요.","일자리가 많아요.","이민 오는 사람이 많아요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#7','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','인구 물통의 꼭지 가운데 「다른 나라에서 사람이 옮겨 오거나 떠난다」는 무엇에 해당하나요?',ARRAY['SO6-2-u3-X08']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"인구 물통의 꼭지 가운데 「다른 나라에서 사람이 옮겨 오거나 떠난다」는 무엇에 해당하나요?","options":[{"t":"인구의 이동","correct":true},{"t":"출생","mis":"SO6-2-u3-X08"},{"t":"사망","mis":"SO6-2-u3-X08"},{"t":"환경의 변화","mis":"SO6-2-u3-X08"}],"explanation":["사람이 오가요.","옮겨 오면 늘어요.","인구의 이동이에요."],"asset":{"type":"passage","lines":["꼭지 ㉠ — 아기가 태어난다.","꼭지 ㉡ — 사람이 사망한다.","꼭지 ㉢ — 다른 나라에서 사람이 옮겨 오거나 떠난다.","꼭지 ㉣ — 가뭄·해수면 상승 같은 환경이 바뀐다."],"title":"인구 물통의 네 꼭지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#8','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','대체로 인구 성장률이 높은 대륙과 낮거나 감소하는 대륙을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X08']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"대체로 인구 성장률이 높은 대륙과 낮거나 감소하는 대륙을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"높음 — 아프리카 / 낮거나 감소 — 유럽","correct":true},{"t":"높음 — 유럽 / 낮거나 감소 — 아프리카","mis":"SO6-2-u3-X08"},{"t":"높음 — 오세아니아 / 낮음 — 아시아","mis":"SO6-2-u3-X08"},{"t":"모든 대륙이 똑같다","mis":"SO6-2-u3-X08"}],"explanation":["아프리카는 빠르게 늘어요.","유럽은 느리거나 줄어요.","대륙마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#9','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'ox','auto','투발루 주민들은 기후변화로 나라가 바다에 잠길 위험 때문에 다른 나라로 이주할 계획을 세우고 있어요.',ARRAY['SO6-2-u3-X08']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"ox","stem":"투발루 주민들은 기후변화로 나라가 바다에 잠길 위험 때문에 다른 나라로 이주할 계획을 세우고 있어요.","answer":"O","reason_options":[{"t":"해수면이 높아지는 환경의 변화가 인구의 이동을 일으키기 때문에","correct":true},{"t":"투발루는 사막이라 물이 없기 때문에","mis":"SO6-2-u3-X08"}],"mis":"SO6-2-u3-X08","explanation":["투발루는 작은 섬나라예요.","바다에 잠길 위험이 있어요.","환경 변화로 이동해요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_basic#10','soc',6,2,'u3','L02','g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',3,'mc','auto','나라별 인구 성장률 자료처럼 아프리카 나라들의 높은 인구 성장률이 계속되면 어떻게 될까요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06','SO6-2-u3-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"나라별 인구 성장률 자료처럼 아프리카 나라들의 높은 인구 성장률이 계속되면 어떻게 될까요?","options":[{"t":"아프리카 나라들의 인구수가 지금보다 늘어난다","correct":true},{"t":"아프리카 나라들의 인구수가 줄어든다","mis":"SO6-2-u3-X08"},{"t":"아프리카 나라들의 면적이 넓어진다","mis":"SO6-2-u3-X06"},{"t":"세계 인구가 줄어든다","mis":"SO6-2-u3-X05"}],"explanation":["성장률은 늘어나는 비율이에요.","높으면 계속 늘어요.","인구수가 늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#1','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',2,'match','auto','네 나라 인구 카드를 보고 나라와 인구의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"match","stem":"네 나라 인구 카드를 보고 나라와 인구의 특징을 알맞게 이으세요.","pairs":[{"l":"인도","r":"세계에서 인구수가 가장 많다"},{"l":"미국","r":"이민 오는 사람이 많다"},{"l":"리비아","r":"면적에 비해 인구가 적다"},{"l":"투발루","r":"작은 섬나라라 인구가 매우 적다"}],"mis":"SO6-2-u3-X07","explanation":["인도는 농업과 높은 출생률이에요.","미국은 산업과 이민이에요.","리비아는 사막, 투발루는 섬이에요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#2','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',2,'sa','auto','인구수가 10억 명 이상인 나라는 인도와 어느 나라인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"sa","stem":"인구수가 10억 명 이상인 나라는 인도와 어느 나라인가요? 두 글자로 쓰세요.","answer":["중국"],"explanation":["아시아의 나라예요.","인도와 함께 10억이 넘어요.","중국이에요."],"mis":"SO6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#3','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','인구 물통의 네 꼭지로 알 수 있는 것을 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X08']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"인구 물통의 네 꼭지로 알 수 있는 것을 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"나라의 인구수는 출생과 사망, 인구의 이동, 환경의 변화 등에 따라 달라진다","correct":true},{"t":"나라의 인구수는 면적에 따라서만 정해진다","mis":"SO6-2-u3-X06"},{"t":"나라의 인구수는 한 번 정해지면 바뀌지 않는다","mis":"SO6-2-u3-X08"},{"t":"나라의 인구수는 출생으로만 달라진다","mis":"SO6-2-u3-X08"}],"explanation":["네 꼭지가 있어요.","태어나고 사망하고 오가고 바뀌어요.","모두 인구수를 바꿔요."],"asset":{"type":"passage","lines":["꼭지 ㉠ — 아기가 태어난다.","꼭지 ㉡ — 사람이 사망한다.","꼭지 ㉢ — 다른 나라에서 사람이 옮겨 오거나 떠난다.","꼭지 ㉣ — 가뭄·해수면 상승 같은 환경이 바뀐다."],"title":"인구 물통의 네 꼭지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#4','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','인도에 인구가 많고 앞으로도 늘어날 것으로 보는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"인도에 인구가 많고 앞으로도 늘어날 것으로 보는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"강수량이 많고 토양이 비옥해 농업이 발달했고 출생률이 높기 때문에","correct":true},{"t":"국토 대부분이 사막이기 때문에","mis":"SO6-2-u3-X07"},{"t":"기후변화로 바다에 잠길 위험이 있기 때문에","mis":"SO6-2-u3-X07"},{"t":"사람들이 모두 다른 나라로 떠나기 때문에","mis":"SO6-2-u3-X08"}],"explanation":["농업이 발달했어요.","출생률이 높아요.","그래서 계속 늘어요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#5','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'ox','auto','사람들은 일자리를 얻거나 전쟁을 피하는 등 여러 목적으로 다른 나라로 이동하며, 이것도 나라의 인구수를 바꿔요.',ARRAY['SO6-2-u3-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"ox","stem":"사람들은 일자리를 얻거나 전쟁을 피하는 등 여러 목적으로 다른 나라로 이동하며, 이것도 나라의 인구수를 바꿔요.","answer":"O","reason_options":[{"t":"인구의 이동은 나라의 인구수를 늘리거나 줄이는 요인이기 때문에","correct":true},{"t":"사람이 나라를 옮겨도 인구수는 그대로이기 때문에","mis":"SO6-2-u3-X08"}],"mis":"SO6-2-u3-X08","explanation":["들어오면 늘어요.","떠나면 줄어요.","이동도 요인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#6','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'error','auto','세계 여러 나라의 인구수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X07']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"error","stem":"세계 여러 나라의 인구수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「땅이 넓은 나라는 모두 인구수가 많아.」","correct":true,"mis_target":"SO6-2-u3-X06"},{"t":"준성 — 「오세아니아 나라들은 대체로 인구수가 적어.」","mis":"SO6-2-u3-X07"},{"t":"다현 — 「나라마다 인구수가 달라.」","mis":"SO6-2-u3-X07"}],"explanation":["넓어도 살기 어려우면 적어요.","리비아가 그 예예요.","예린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#7','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','네 나라 인구 카드의 수치를 공부하는 바른 태도는 어느 것인가요?',ARRAY['SO6-2-u3-X23']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"네 나라 인구 카드의 수치를 공부하는 바른 태도는 어느 것인가요?","options":[{"t":"수치를 견주어 많고 적은 까닭을 그 나라의 환경과 이어 생각한다","correct":true},{"t":"네 나라의 인구수를 빠짐없이 외운다","mis":"SO6-2-u3-X23"},{"t":"수치가 큰 나라만 기억한다","mis":"SO6-2-u3-X23"},{"t":"수치는 보지 않고 나라 이름만 외운다","mis":"SO6-2-u3-X23"}],"explanation":["외우는 게 목표가 아니에요.","까닭과 이어 봐요.","견주어 읽어요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#8','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',4,'mc','auto','투발루의 이야기에서 알 수 있는 것을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X06','SO6-2-u3-X08']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C3","difficulty":4,"kind":"mc","stem":"투발루의 이야기에서 알 수 있는 것을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"기후변화 같은 환경의 변화가 사람들을 이동하게 해 나라의 인구수에도 영향을 준다","correct":true},{"t":"투발루는 사막이라 인구가 적다","mis":"SO6-2-u3-X07"},{"t":"투발루는 땅이 넓어 인구가 늘어난다","mis":"SO6-2-u3-X06"},{"t":"환경의 변화는 인구수와 관계없다","mis":"SO6-2-u3-X08"}],"explanation":["바다에 잠길 위험이 있어요.","주민이 이주하려 해요.","환경이 인구를 바꿔요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#9','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',4,'mc','auto','「인구가 많은 나라는 땅이 넓은 나라다」라는 말을 고쳐 줄 때 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C3","difficulty":4,"kind":"mc","stem":"「인구가 많은 나라는 땅이 넓은 나라다」라는 말을 고쳐 줄 때 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"리비아처럼 넓어도 사막인 나라는 인구가 적고, 인구수는 자연환경과 인문환경의 영향을 받는다","correct":true},{"t":"투발루는 넓은데도 인구가 많다","mis":"SO6-2-u3-X07"},{"t":"넓은 나라는 모두 인구가 많다","mis":"SO6-2-u3-X06"},{"t":"인구수는 면적으로만 정해진다","mis":"SO6-2-u3-X06"}],"explanation":["넓이만 보면 안 돼요.","환경을 함께 봐요.","리비아가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L02_challenge#10','soc',6,2,'u3','L02','g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',4,'essay','teacher','네 나라 인구 카드에서 인구가 많은 나라 한 곳과 적은 나라 한 곳을 골라 까닭을 쓰고, 나라의 인구수를 바꾸는 요인 세 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":4,"kind":"essay","stem":"네 나라 인구 카드에서 인구가 많은 나라 한 곳과 적은 나라 한 곳을 골라 까닭을 쓰고, 나라의 인구수를 바꾸는 요인 세 가지를 쓰세요.","answer_guide":{"answer":"예: 미국은 기후가 온화하고 다양한 산업이 발달해 일자리를 찾아 이민 오는 사람이 많아 인구가 많다. 리비아는 국토 대부분이 사막이라 면적에 비해 인구가 적다. 나라의 인구수는 출생, 사망, 인구의 이동, 환경의 변화 등에 따라 달라진다.","scoring_points":["인구가 많은 나라와 까닭을 썼는가","인구가 적은 나라와 까닭을 썼는가","인구수를 바꾸는 요인을 세 가지 썼는가"]},"explanation":["많은 까닭을 써요.","적은 까닭을 써요.","네 꼭지를 떠올려요."],"asset":{"type":"passage","lines":["인도 — 약 14억 3,807만 명 · 강수량이 많고 토양이 비옥해 농업 발달","미국 — 약 3억 4,348만 명 · 다양한 산업, 이민 오는 사람이 많음","리비아 — 약 731만 명 · 국토 대부분이 사막","투발루 — 9,816명 · 남태평양의 작은 섬나라"],"title":"네 나라 인구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#1','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'mc','auto','인구 밀도의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X08']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"인구 밀도의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"일정한 면적(1 km²) 안에 사는 인구수","correct":true},{"t":"한 나라에 사는 사람 수를 모두 더한 것","mis":"SO6-2-u3-X09"},{"t":"한 나라의 땅 넓이","mis":"SO6-2-u3-X09"},{"t":"인구가 늘어나는 비율","mis":"SO6-2-u3-X08"}],"explanation":["빽빽한 정도예요.","1 km² 안을 봐요.","인구 밀도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#2','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'mc','auto','인구 밀도가 높은 나라끼리 묶인 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"인구 밀도가 높은 나라끼리 묶인 것은 어느 것인가요?","options":[{"t":"방글라데시·르완다·인도","correct":true},{"t":"몽골·오스트레일리아·캐나다","mis":"SO6-2-u3-X10"},{"t":"캐나다·방글라데시·몽골","mis":"SO6-2-u3-X10"},{"t":"오스트레일리아·인도·몽골","mis":"SO6-2-u3-X10"}],"explanation":["면적에 비해 사람이 많아요.","방글라데시·르완다·인도예요.","몽골·캐나다는 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#3','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'sa','auto','인구 밀도 자료에서 인구 밀도가 약 4명/km²로 매우 낮은 북아메리카의 나라를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"sa","stem":"인구 밀도 자료에서 인구 밀도가 약 4명/km²로 매우 낮은 북아메리카의 나라를 쓰세요.","answer":["캐나다"],"explanation":["냉대 기후가 넓어요.","농사지을 땅이 적어요.","캐나다예요."],"mis":"SO6-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#4','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'ox','auto','면적에 비해 인구수가 많을수록 인구 밀도가 높아요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"ox","stem":"면적에 비해 인구수가 많을수록 인구 밀도가 높아요.","answer":"O","reason_options":[{"t":"같은 면적 안에 더 많은 사람이 살기 때문에","correct":true},{"t":"면적이 넓을수록 인구 밀도가 높기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["사람이 많고 땅이 좁으면 빽빽해요.","1 km² 안 사람이 많아요.","밀도가 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#5','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'mc','auto','방글라데시의 인구 밀도가 매우 높은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10','SO6-2-u3-X09']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"방글라데시의 인구 밀도가 매우 높은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"국토 대부분이 평야이고 기후가 온화해 벼농사가 발달했기 때문에","correct":true},{"t":"냉대 기후가 넓게 나타나기 때문에","mis":"SO6-2-u3-X10"},{"t":"국토 대부분이 사막이기 때문에","mis":"SO6-2-u3-X10"},{"t":"땅이 매우 넓기 때문에","mis":"SO6-2-u3-X09"}],"explanation":["평야가 넓어요.","벼농사가 발달했어요.","그래서 사람이 많이 모여요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#6','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'mc','auto','캐나다의 인구 밀도가 매우 낮은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10','SO6-2-u3-X09']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"캐나다의 인구 밀도가 매우 낮은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"냉대 기후가 넓게 나타나 국토 면적에 비해 농사지을 땅이 적기 때문에","correct":true},{"t":"국토 대부분이 평야라 사람이 흩어져 살기 때문에","mis":"SO6-2-u3-X10"},{"t":"산업이 매우 발달했기 때문에","mis":"SO6-2-u3-X10"},{"t":"국토가 매우 좁기 때문에","mis":"SO6-2-u3-X09"}],"explanation":["캐나다는 추운 곳이 많아요.","농사지을 땅이 적어요.","그래서 밀도가 낮아요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#7','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'mc','auto','인구 밀도 자료에서 우리나라와 면적이 비슷한 나라들을 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10','SO6-2-u3-X09']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"인구 밀도 자료에서 우리나라와 면적이 비슷한 나라들을 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"우리나라의 인구 밀도는 매우 높은 편이다","correct":true},{"t":"우리나라의 인구 밀도가 가장 낮다","mis":"SO6-2-u3-X10"},{"t":"네 나라의 인구 밀도가 같다","mis":"SO6-2-u3-X09"},{"t":"면적이 비슷하면 인구 밀도도 같다","mis":"SO6-2-u3-X09"}],"explanation":["우리나라는 약 515명이에요.","다른 나라보다 커요.","매우 높은 편이에요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#8','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'mc','auto','인구 밀도가 낮은 나라가 많이 모여 있는 곳은 어디인가요?',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"인구 밀도가 낮은 나라가 많이 모여 있는 곳은 어디인가요?","options":[{"t":"고위도 지역","correct":true},{"t":"아시아의 평야 지역","mis":"SO6-2-u3-X10"},{"t":"유럽의 도시 지역","mis":"SO6-2-u3-X10"},{"t":"중위도 해안 지역","mis":"SO6-2-u3-X10"}],"explanation":["추운 곳이에요.","사람이 살기 어려워요.","고위도에 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#9','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'ox','auto','인구가 증가하는 나라는 시간이 지나면 인구 밀도가 점차 높아질 거예요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"ox","stem":"인구가 증가하는 나라는 시간이 지나면 인구 밀도가 점차 높아질 거예요.","answer":"O","reason_options":[{"t":"면적은 그대로인데 인구수가 늘어나기 때문에","correct":true},{"t":"인구가 늘면 면적도 함께 넓어지기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["면적은 그대로예요.","사람이 늘어요.","밀도가 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_basic#10','soc',6,2,'u3','L03','g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',3,'mc','auto','두 나라의 인구 밀도를 견주려고 해요. 인구수만 견주면 부족한 까닭은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"두 나라의 인구 밀도를 견주려고 해요. 인구수만 견주면 부족한 까닭은 어느 것인가요?","options":[{"t":"면적이 다르면 같은 인구수라도 모여 사는 정도가 다르기 때문에","correct":true},{"t":"인구수는 해마다 같기 때문에","mis":"SO6-2-u3-X09"},{"t":"면적은 인구 밀도와 관계없기 때문에","mis":"SO6-2-u3-X09"},{"t":"인구 밀도는 출생률만으로 정해지기 때문에","mis":"SO6-2-u3-X08"}],"explanation":["넓이가 다를 수 있어요.","같은 수도 넓으면 흩어져요.","면적을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#1','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',2,'match','auto','나라와 인구 밀도의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"match","stem":"나라와 인구 밀도의 특징을 알맞게 이으세요.","pairs":[{"l":"방글라데시","r":"평야·벼농사로 매우 높음"},{"l":"캐나다","r":"냉대 기후로 매우 낮음"},{"l":"우리나라","r":"면적이 비슷한 나라보다 높음"}],"mis":"SO6-2-u3-X10","explanation":["방글라데시는 평야예요.","캐나다는 추워요.","우리나라는 매우 높은 편이에요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#2','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',2,'sa','auto','인구 밀도를 구하려면 인구수와 함께 무엇을 알아야 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"sa","stem":"인구 밀도를 구하려면 인구수와 함께 무엇을 알아야 하나요? 두 글자로 쓰세요.","answer":["면적"],"explanation":["땅의 넓이예요.","1 km² 단위로 나눠요.","면적이에요."],"mis":"SO6-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#3','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','같은 인구가 사는 두 나라 가운데 ㉮는 면적이 좁고 ㉯는 면적이 넓어요. 알맞은 설명은 어느 것인가요?',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"같은 인구가 사는 두 나라 가운데 ㉮는 면적이 좁고 ㉯는 면적이 넓어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"㉮의 인구 밀도가 더 높다","correct":true},{"t":"㉯의 인구 밀도가 더 높다","mis":"SO6-2-u3-X09"},{"t":"두 나라의 인구 밀도는 같다","mis":"SO6-2-u3-X09"},{"t":"인구가 같으면 견줄 수 없다","mis":"SO6-2-u3-X09"}],"explanation":["인구는 같아요.","㉮의 땅이 좁아요.","㉮가 더 빽빽해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#4','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','세계 여러 나라의 인구 밀도를 살펴보고 알 수 있는 사실로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X10','SO6-2-u3-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"세계 여러 나라의 인구 밀도를 살펴보고 알 수 있는 사실로 알맞은 것은 어느 것인가요?","options":[{"t":"아시아와 유럽에 인구 밀도가 높은 나라가 많고 고위도에 낮은 나라가 많다","correct":true},{"t":"모든 나라의 인구 밀도가 비슷하다","mis":"SO6-2-u3-X09"},{"t":"고위도에 인구 밀도가 높은 나라가 많다","mis":"SO6-2-u3-X10"},{"t":"땅이 넓은 나라일수록 인구 밀도가 높다","mis":"SO6-2-u3-X06"}],"explanation":["아시아·유럽은 높아요.","고위도는 낮아요.","나라마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#5','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'ox','auto','방글라데시와 캐나다의 인구 밀도가 다른 것은 두 나라의 자연환경이 다르기 때문이기도 해요.',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"ox","stem":"방글라데시와 캐나다의 인구 밀도가 다른 것은 두 나라의 자연환경이 다르기 때문이기도 해요.","answer":"O","reason_options":[{"t":"평야와 온화한 기후, 냉대 기후처럼 농사지을 수 있는 땅의 양이 다르기 때문에","correct":true},{"t":"인구 밀도는 자연환경과 아무 관계가 없기 때문에","mis":"SO6-2-u3-X10"}],"mis":"SO6-2-u3-X10","explanation":["방글라데시는 평야예요.","캐나다는 추워요.","환경이 밀도를 바꿔요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#6','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'error','auto','인구 밀도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"error","stem":"인구 밀도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규민 — 「캐나다는 땅이 넓으니까 인구 밀도도 높을 거야.」","correct":true,"mis_target":"SO6-2-u3-X09"},{"t":"소연 — 「면적에 비해 인구가 많으면 인구 밀도가 높아.」","mis":"SO6-2-u3-X09"},{"t":"태하 — 「우리나라는 인구 밀도가 높은 편이야.」","mis":"SO6-2-u3-X10"}],"explanation":["넓은 땅에 사람이 적어요.","캐나다는 약 4명이에요.","규민이 잘못 말했어요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#7','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','인구 밀도가 앞으로 어떻게 바뀔지 예상하려면 가장 필요한 자료는 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X23']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"인구 밀도가 앞으로 어떻게 바뀔지 예상하려면 가장 필요한 자료는 어느 것인가요?","options":[{"t":"나라별 인구수의 변화를 보여 주는 자료","correct":true},{"t":"나라별 국기 자료","mis":"SO6-2-u3-X09"},{"t":"나라별 산의 높이 자료","mis":"SO6-2-u3-X09"},{"t":"나라별 수도 이름 자료","mis":"SO6-2-u3-X23"}],"explanation":["밀도는 인구수와 면적이에요.","면적은 그대로예요.","인구수의 변화를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#8','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',4,'mc','auto','인구 밀도 자료를 공부하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X09']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"mc","stem":"인구 밀도 자료를 공부하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라별 수치를 견주어 높고 낮은 까닭을 지형·기후·산업과 이어 생각한다","correct":true},{"t":"나라별 인구 밀도 숫자를 모두 외운다","mis":"SO6-2-u3-X23"},{"t":"수치가 가장 큰 나라 이름만 외운다","mis":"SO6-2-u3-X23"},{"t":"인구 밀도는 면적만 보면 알 수 있다고 여긴다","mis":"SO6-2-u3-X09"}],"explanation":["외우는 게 목표가 아니에요.","까닭과 이어요.","자료를 견줘 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#9','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',4,'mc','auto','인구 밀도에 대한 설명을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X10']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"mc","stem":"인구 밀도에 대한 설명을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"면적에 비해 인구수가 많을수록 높고, 나라마다 다르며, 인구가 변하면 함께 변할 수 있다","correct":true},{"t":"면적이 넓을수록 높고 한 번 정해지면 변하지 않는다","mis":"SO6-2-u3-X09"},{"t":"인구수만으로 정해지고 나라마다 같다","mis":"SO6-2-u3-X09"},{"t":"기후와 지형은 인구 밀도와 관계없다","mis":"SO6-2-u3-X10"}],"explanation":["면적에 비해 사람이 많으면 높아요.","나라마다 달라요.","변할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L03_challenge#10','soc',6,2,'u3','L03','g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',4,'essay','teacher','인구 밀도 자료를 보고 방글라데시와 캐나다의 인구 밀도를 견주어 쓰고, 두 나라의 인구 밀도가 다른 까닭을 자연환경과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"essay","stem":"인구 밀도 자료를 보고 방글라데시와 캐나다의 인구 밀도를 견주어 쓰고, 두 나라의 인구 밀도가 다른 까닭을 자연환경과 이어 쓰세요.","answer_guide":{"answer":"예: 방글라데시의 인구 밀도는 약 1,317명/km²로 매우 높고 캐나다는 약 4명/km²로 매우 낮다. 방글라데시는 국토 대부분이 평야이고 기후가 온화해 벼농사가 발달해 많은 사람이 모여 산다. 캐나다는 냉대 기후가 넓게 나타나 농사지을 땅이 국토 면적에 비해 적어 인구 밀도가 낮다.","scoring_points":["두 나라의 인구 밀도를 견주었는가","방글라데시의 까닭을 썼는가","캐나다의 까닭을 썼는가"]},"explanation":["높고 낮음을 견줘요.","평야·벼농사예요.","냉대 기후예요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 국토 대부분 평야, 온화한 기후, 벼농사","캐나다 — 약 4명/km² · 냉대 기후가 넓어 농사지을 땅이 적음","우리나라 — 약 515명/km²","면적이 비슷한 나라 — 헝가리 약 107명 · 과테말라 약 169명 · 아이슬란드 약 4명"],"title":"인구 밀도 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#1','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'mc','auto','인구 구조의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"mc","stem":"인구 구조의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"연령·성 등을 기준으로 한 인구의 짜임새","correct":true},{"t":"1 km² 안에 사는 인구수","mis":"SO6-2-u3-X11"},{"t":"인구가 늘어나는 비율","mis":"SO6-2-u3-X11"},{"t":"한 나라의 땅 넓이","mis":"SO6-2-u3-X11"}],"explanation":["짜임새를 뜻해요.","나이와 성별로 나눠요.","인구 구조예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#2','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'mc','auto','노년층에 해당하는 나이는 어느 것인가요?',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"mc","stem":"노년층에 해당하는 나이는 어느 것인가요?","options":[{"t":"65세 이상","correct":true},{"t":"0~14세","mis":"SO6-2-u3-X11"},{"t":"15~64세","mis":"SO6-2-u3-X11"},{"t":"20~30세","mis":"SO6-2-u3-X11"}],"explanation":["가장 위층이에요.","65세부터예요.","노년층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#3','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'sa','auto','국가나 지역의 연령별·성별 인구를 나타낸 그래프를 무엇이라고 하나요? (인구 □□□)','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"sa","stem":"국가나 지역의 연령별·성별 인구를 나타낸 그래프를 무엇이라고 하나요? (인구 □□□)","answer":["피라미드"],"explanation":["층층이 쌓인 모양이에요.","가로는 남녀, 세로는 나이예요.","인구 피라미드예요."],"mis":"SO6-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#4','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'ox','auto','인구 피라미드의 세로축은 나이를 나타내요.',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"ox","stem":"인구 피라미드의 세로축은 나이를 나타내요.","answer":"O","reason_options":[{"t":"아래에서 위로 갈수록 나이가 많아지도록 그리기 때문에","correct":true},{"t":"세로축은 나라의 면적을 나타내기 때문에","mis":"SO6-2-u3-X11"}],"mis":"SO6-2-u3-X11","explanation":["세로축은 나이예요.","가로축은 남녀 비율이에요.","아래는 어린이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#5','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',2,'mc','auto','인구 구조 자료에서 나이지리아 인구 구조의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"인구 구조 자료에서 나이지리아 인구 구조의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"유소년층 비율이 높고 노년층 비율이 낮다","correct":true},{"t":"유소년층 비율이 낮고 노년층 비율이 높다","mis":"SO6-2-u3-X12"},{"t":"세 연령층 비율이 똑같다","mis":"SO6-2-u3-X11"},{"t":"노년층 비율이 가장 높다","mis":"SO6-2-u3-X12"}],"explanation":["출생률이 높아요.","평균 수명이 짧아요.","어린이가 많아요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#6','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C6',2,'mc','auto','노년층 비율이 높은 일본에 더 많이 필요할 시설은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"노년층 비율이 높은 일본에 더 많이 필요할 시설은 어느 것인가요?","options":[{"t":"요양원과 노인 복지 센터","correct":true},{"t":"유치원과 초등학교","mis":"SO6-2-u3-X13"},{"t":"놀이터와 어린이집","mis":"SO6-2-u3-X13"},{"t":"청소년 수련관","mis":"SO6-2-u3-X13"}],"explanation":["노인이 많아요.","노인을 위한 시설이 필요해요.","요양원·복지 센터예요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#7','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',2,'mc','auto','인구 구조 자료에서 세계 인구 구조가 1960년에 비해 2020년에 달라진 점은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"인구 구조 자료에서 세계 인구 구조가 1960년에 비해 2020년에 달라진 점은 어느 것인가요?","options":[{"t":"유소년층 비율이 줄고 노년층 비율이 늘었다","correct":true},{"t":"유소년층 비율이 늘고 노년층 비율이 줄었다","mis":"SO6-2-u3-X12"},{"t":"세 연령층 비율이 그대로이다","mis":"SO6-2-u3-X11"},{"t":"청장년층이 모두 사라졌다","mis":"SO6-2-u3-X11"}],"explanation":["어린이 비율이 줄었어요.","노인 비율이 늘었어요.","청장년층이 가장 많아요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#8','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',2,'mc','auto','출생률과 사망률이 낮고 평균 수명이 긴 나라의 인구 구조는 일반적으로 어떠한가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"출생률과 사망률이 낮고 평균 수명이 긴 나라의 인구 구조는 일반적으로 어떠한가요?","options":[{"t":"유소년층 비율이 낮고 노년층 비율이 높다","correct":true},{"t":"유소년층 비율이 높고 노년층 비율이 낮다","mis":"SO6-2-u3-X12"},{"t":"청장년층이 하나도 없다","mis":"SO6-2-u3-X11"},{"t":"세 연령층 비율이 똑같다","mis":"SO6-2-u3-X12"}],"explanation":["아기가 적게 태어나요.","오래 살아요.","노년층이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#9','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C6',2,'ox','auto','인구 구조를 살펴보면 미래의 인구 변화를 예상할 수 있어요.',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"ox","stem":"인구 구조를 살펴보면 미래의 인구 변화를 예상할 수 있어요.","answer":"O","reason_options":[{"t":"지금의 연령층 비율이 앞으로의 인구 모습을 보여 주기 때문에","correct":true},{"t":"인구 구조는 미래와 아무 관계가 없기 때문에","mis":"SO6-2-u3-X13"}],"mis":"SO6-2-u3-X13","explanation":["지금 어린이가 자라요.","지금 청장년이 노인이 돼요.","미래를 예상할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_basic#10','soc',6,2,'u3','L04','g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C6',3,'mc','auto','사우디아라비아·아랍 에미리트에 청장년층 인구가 두드러지게 많은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X13','SO6-2-u3-X09']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"사우디아라비아·아랍 에미리트에 청장년층 인구가 두드러지게 많은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"경제성장 과정에서 여러 나라의 근로자를 받아들였기 때문에","correct":true},{"t":"출생률이 매우 낮기 때문에","mis":"SO6-2-u3-X12"},{"t":"노인들이 모두 이주해 왔기 때문에","mis":"SO6-2-u3-X13"},{"t":"땅이 매우 좁기 때문에","mis":"SO6-2-u3-X09"}],"explanation":["석유 자원이 풍부해요.","일할 사람을 받아들였어요.","청장년층이 많아요."],"asset":{"type":"passage","lines":["인도네시아 — 경제성장이 이어지고, 인구의 절반 넘게가 1980~1990년대생이다.","기업들이 젊은 소비자가 좋아하는 화장품·스마트폰에 투자를 늘렸다.","사우디아라비아·아랍 에미리트 — 석유 자원이 풍부하다.","경제성장 과정에서 여러 나라의 근로자를 받아들였다."],"title":"인구 구조와 생활 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#1','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',2,'match','auto','인구 피라미드의 부분과 나타내는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"match","stem":"인구 피라미드의 부분과 나타내는 것을 알맞게 이으세요.","pairs":[{"l":"가로축 왼쪽","r":"남자 인구 비율"},{"l":"가로축 오른쪽","r":"여자 인구 비율"},{"l":"세로축","r":"나이(연령)"},{"l":"맨 아래층","r":"유소년층"}],"mis":"SO6-2-u3-X11","explanation":["가로는 남녀예요.","세로는 나이예요.","아래층이 어린이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#2','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',2,'sa','auto','0~14세 인구를 무엇이라고 하나요? (□□□층)','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"sa","stem":"0~14세 인구를 무엇이라고 하나요? (□□□층)","answer":["유소년"],"explanation":["어린이 나이예요.","가장 아래층이에요.","유소년층이에요."],"mis":"SO6-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#3','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',3,'mc','auto','인도네시아가 「젊은 시장」으로 주목받는 까닭을 인구 구조와 이어 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"인도네시아가 「젊은 시장」으로 주목받는 까닭을 인구 구조와 이어 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"청장년층 비율이 높아 유행에 민감하고 소비가 활발한 젊은 인구가 많기 때문에","correct":true},{"t":"노년층 비율이 가장 높기 때문에","mis":"SO6-2-u3-X13"},{"t":"인구가 매우 적기 때문에","mis":"SO6-2-u3-X13"},{"t":"유소년층만 살기 때문에","mis":"SO6-2-u3-X13"}],"explanation":["1980~1990년대생이 많아요.","청장년층이 많아요.","기업이 투자해요."],"asset":{"type":"passage","lines":["인도네시아 — 경제성장이 이어지고, 인구의 절반 넘게가 1980~1990년대생이다.","기업들이 젊은 소비자가 좋아하는 화장품·스마트폰에 투자를 늘렸다.","사우디아라비아·아랍 에미리트 — 석유 자원이 풍부하다.","경제성장 과정에서 여러 나라의 근로자를 받아들였다."],"title":"인구 구조와 생활 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#4','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',3,'mc','auto','나이지리아와 일본을 견주어 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"mc","stem":"나이지리아와 일본을 견주어 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"나이지리아는 출생률·사망률이 높아 유소년층이, 일본은 낮아 노년층이 많다","correct":true},{"t":"나이지리아는 노년층이, 일본은 유소년층이 많다","mis":"SO6-2-u3-X12"},{"t":"두 나라 모두 노년층이 가장 많다","mis":"SO6-2-u3-X12"},{"t":"두 나라의 인구 구조는 같다","mis":"SO6-2-u3-X11"}],"explanation":["나이지리아는 많이 태어나요.","일본은 오래 살아요.","구조가 달라요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#5','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',3,'mc','auto','아이를 더 낳도록 권하는 포스터를 만든 나라의 인구 구조로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"아이를 더 낳도록 권하는 포스터를 만든 나라의 인구 구조로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"유소년층 비율이 낮아졌을 것이다","correct":true},{"t":"유소년층 비율이 매우 높을 것이다","mis":"SO6-2-u3-X13"},{"t":"노년층이 하나도 없을 것이다","mis":"SO6-2-u3-X13"},{"t":"인구 구조와 관계없는 포스터이다","mis":"SO6-2-u3-X13"}],"explanation":["아이가 적어 걱정이에요.","더 낳자고 권해요.","유소년층이 줄었을 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#6','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',3,'ox','auto','세계 인구 구조에서 가장 비율이 높은 연령층은 청장년층이에요.',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"ox","stem":"세계 인구 구조에서 가장 비율이 높은 연령층은 청장년층이에요.","answer":"O","reason_options":[{"t":"1960년과 2020년 모두 청장년층의 비율이 가장 높게 나타나기 때문에","correct":true},{"t":"노년층의 비율이 언제나 가장 높기 때문에","mis":"SO6-2-u3-X11"}],"mis":"SO6-2-u3-X11","explanation":["15~64세예요.","가장 넓은 층이에요.","청장년층이 가장 많아요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#7','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',3,'error','auto','인구 구조와 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"error","stem":"인구 구조와 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「유소년층이 많은 나라에는 요양원이 가장 많이 필요해.」","correct":true,"mis_target":"SO6-2-u3-X13"},{"t":"나윤 — 「노년층이 많은 나라에는 노인 복지 시설이 필요해.」","mis":"SO6-2-u3-X13"},{"t":"가람 — 「인구 구조는 경제와 문화에도 영향을 줘.」","mis":"SO6-2-u3-X13"}],"explanation":["유소년층이 많으면 학교가 필요해요.","요양원은 노인을 위한 곳이에요.","은호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#8','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',4,'mc','auto','외국인 근로자가 더 이상 필요하지 않아 자기 나라로 돌아간다면 사우디아라비아·아랍 에미리트의 인구 구조는 어떻게 될까요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C6","difficulty":4,"kind":"mc","stem":"외국인 근로자가 더 이상 필요하지 않아 자기 나라로 돌아간다면 사우디아라비아·아랍 에미리트의 인구 구조는 어떻게 될까요?","options":[{"t":"청장년층 인구 비율이 줄어든다","correct":true},{"t":"청장년층 인구 비율이 크게 늘어난다","mis":"SO6-2-u3-X13"},{"t":"유소년층만 남는다","mis":"SO6-2-u3-X13"},{"t":"인구 구조는 달라지지 않는다","mis":"SO6-2-u3-X13"}],"explanation":["근로자는 청장년층이에요.","그들이 떠나요.","청장년층 비율이 줄어요."],"asset":{"type":"passage","lines":["인도네시아 — 경제성장이 이어지고, 인구의 절반 넘게가 1980~1990년대생이다.","기업들이 젊은 소비자가 좋아하는 화장품·스마트폰에 투자를 늘렸다.","사우디아라비아·아랍 에미리트 — 석유 자원이 풍부하다.","경제성장 과정에서 여러 나라의 근로자를 받아들였다."],"title":"인구 구조와 생활 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#9','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',4,'mc','auto','세계 인구 구조의 변화가 계속된다면 앞으로 예상할 수 있는 것은 어느 것인가요?',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C5","difficulty":4,"kind":"mc","stem":"세계 인구 구조의 변화가 계속된다면 앞으로 예상할 수 있는 것은 어느 것인가요?","options":[{"t":"유소년층 비율은 더 줄고 노년층 비율은 더 늘어날 것이다","correct":true},{"t":"유소년층 비율이 더 늘어날 것이다","mis":"SO6-2-u3-X12"},{"t":"노년층이 모두 사라질 것이다","mis":"SO6-2-u3-X12"},{"t":"세 연령층 비율이 같아질 것이다","mis":"SO6-2-u3-X12"}],"explanation":["1960년보다 어린이 비율이 줄었어요.","노인 비율이 늘었어요.","그 흐름이 이어져요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L04_challenge#10','soc',6,2,'u3','L04','g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',4,'essay','teacher','인구 구조 자료를 보고 나이지리아와 일본의 인구 구조를 출생률·사망률·평균 수명과 이어 견주어 쓰고, 두 나라에 각각 더 필요한 시설을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C5","difficulty":4,"kind":"essay","stem":"인구 구조 자료를 보고 나이지리아와 일본의 인구 구조를 출생률·사망률·평균 수명과 이어 견주어 쓰고, 두 나라에 각각 더 필요한 시설을 쓰세요.","answer_guide":{"answer":"예: 나이지리아는 출생률과 사망률이 높고 평균 수명이 짧아 유소년층 비율이 높고 노년층 비율이 낮다. 일본은 출생률과 사망률이 낮고 평균 수명이 길어 유소년층 비율이 낮고 노년층 비율이 높다. 그래서 나이지리아에는 유치원과 학교 같은 어린이 시설이, 일본에는 요양원과 노인 복지 센터 같은 노인 시설이 더 필요하다.","scoring_points":["나이지리아의 인구 구조와 까닭을 썼는가","일본의 인구 구조와 까닭을 썼는가","두 나라에 필요한 시설을 썼는가"]},"explanation":["출생률·사망률을 봐요.","연령층 비율을 견줘요.","필요한 시설을 이어요."],"asset":{"type":"passage","lines":["나이지리아 — 유소년층 비율 높음 · 노년층 낮음 · 출생률·사망률 높음 · 평균 수명 짧음","일본 — 유소년층 비율 낮음 · 노년층 높음 · 출생률·사망률 낮음 · 평균 수명 긺","세계 인구 구조(1960 → 2020) — 유소년층 비율 줄고 노년층 비율 늘어남","세계 인구 구조 — 청장년층 비율이 가장 높음"],"title":"인구 구조 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#1','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'mc','auto','과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습을 무엇이라고 하나요?',ARRAY['SO6-2-u3-X14','SO6-2-u3-X20']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습을 무엇이라고 하나요?","options":[{"t":"지구촌","correct":true},{"t":"도시","mis":"SO6-2-u3-X14"},{"t":"촌락","mis":"SO6-2-u3-X14"},{"t":"국제기구","mis":"SO6-2-u3-X20"}],"explanation":["하나의 마을 같아요.","교통·통신이 발달했어요.","지구촌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#2','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'mc','auto','석유나 석탄 같은 화석 연료를 지나치게 사용해 심해지는 지구촌 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"석유나 석탄 같은 화석 연료를 지나치게 사용해 심해지는 지구촌 문제는 어느 것인가요?","options":[{"t":"기후변화","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"인구 밀도","mis":"SO6-2-u3-X15"},{"t":"인구 구조","mis":"SO6-2-u3-X15"}],"explanation":["탄소가 많이 나와요.","지구가 더워져요.","기후변화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#3','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'sa','auto','전쟁·재난 등으로 살던 곳을 떠나 다른 곳으로 피한 사람을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"sa","stem":"전쟁·재난 등으로 살던 곳을 떠나 다른 곳으로 피한 사람을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["난민"],"explanation":["살던 곳을 떠났어요.","보트를 타기도 해요.","난민이에요."],"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#4','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'ox','auto','지구촌 시대에는 한 나라의 문제가 다른 나라에 영향을 미칠 수 있어요.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"ox","stem":"지구촌 시대에는 한 나라의 문제가 다른 나라에 영향을 미칠 수 있어요.","answer":"O","reason_options":[{"t":"나라들이 가까워져 서로 깊이 연결되어 있기 때문에","correct":true},{"t":"나라마다 따로 떨어져 아무 관계가 없기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["지구가 가까워졌어요.","서로 이어져 있어요.","영향을 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#5','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'match','auto','네 장면과 그 장면이 보여 주는 지구촌 문제를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"match","stem":"네 장면과 그 장면이 보여 주는 지구촌 문제를 알맞게 이으세요.","pairs":[{"l":"①","r":"자원과 에너지 고갈"},{"l":"②","r":"생태계 파괴"},{"l":"③","r":"기후변화"},{"l":"④","r":"난민"}],"mis":"SO6-2-u3-X15","explanation":["①은 깎인 광산이에요.","②는 베어진 숲, ③은 녹는 빙하예요.","④는 보트의 사람들이에요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 구리 광산","② 나무가 베어져 손상된 열대 우림","③ 녹아 무너지고 있는 빙하","④ 바다 위 작은 보트에서 구조를 요청하는 사람들"],"title":"네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#6','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'mc','auto','열대 우림 기사에서 열대 우림이 줄어든 가장 큰 원인으로 꼽힌 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"열대 우림 기사에서 열대 우림이 줄어든 가장 큰 원인으로 꼽힌 것은 어느 것인가요?","options":[{"t":"농사·목축·산업 같은 인간의 활동","correct":true},{"t":"화산 폭발","mis":"SO6-2-u3-X15"},{"t":"지진","mis":"SO6-2-u3-X15"},{"t":"운석 충돌","mis":"SO6-2-u3-X15"}],"explanation":["사람이 숲을 베었어요.","농사와 목축을 했어요.","인간 활동이 원인이에요."],"asset":{"type":"passage","lines":["열대 우림은 지구 생명체의 절반 이상이 사는 곳이다.","탄소를 많이 흡수해 지구 온난화의 속도를 늦춘다.","농사·목축·에너지 사용·산업 같은 인간 활동으로 크게 줄었다."],"title":"열대 우림 기사(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#7','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'mc','auto','지구촌 시대의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"지구촌 시대의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 나라 사람들과 문화를 쉽게 교류할 수 있다","correct":true},{"t":"한 나라의 문제가 다른 나라에 퍼진다","mis":"SO6-2-u3-X14"},{"t":"사람들 사이에 갈등이 생길 수 있다","mis":"SO6-2-u3-X14"},{"t":"먼 곳의 소식을 알 수 없게 된다","mis":"SO6-2-u3-X14"}],"explanation":["소식이 빨라졌어요.","정보를 쉽게 얻어요.","문화를 교류해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#8','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'mc','auto','세계 여러 나라 사람들이 「지구촌 전등 끄기 캠페인」에 참여하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"세계 여러 나라 사람들이 「지구촌 전등 끄기 캠페인」에 참여하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"에너지를 절약하고 지구 환경의 중요성을 알리려고","correct":true},{"t":"전기 요금을 올리려고","mis":"SO6-2-u3-X16"},{"t":"밤에 잠을 일찍 자려고","mis":"SO6-2-u3-X16"},{"t":"전등을 새로 사려고","mis":"SO6-2-u3-X16"}],"explanation":["한 시간 불을 꺼요.","에너지를 아껴요.","환경을 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#9','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'ox','auto','「고갈」은 돈이나 물자 등이 다하여 없어진다는 뜻이에요.',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"ox","stem":"「고갈」은 돈이나 물자 등이 다하여 없어진다는 뜻이에요.","answer":"O","reason_options":[{"t":"자원과 에너지가 다 써서 없어지는 문제를 자원 고갈이라고 하기 때문에","correct":true},{"t":"고갈은 자원이 점점 늘어난다는 뜻이기 때문에","mis":"SO6-2-u3-X15"}],"mis":"SO6-2-u3-X15","explanation":["다하여 없어져요.","자원을 너무 써요.","고갈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_basic#10','soc',6,2,'u3','L05','g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',3,'mc','auto','열대 우림 기사처럼 열대 우림이 계속 훼손된다면 지구촌에 어떤 영향을 미칠까요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X15']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"열대 우림 기사처럼 열대 우림이 계속 훼손된다면 지구촌에 어떤 영향을 미칠까요?","options":[{"t":"동식물이 살 곳을 잃고, 탄소를 흡수하던 숲이 사라져 기후변화가 커질 수 있다","correct":true},{"t":"열대 우림이 줄어도 지구에는 아무 영향이 없다","mis":"SO6-2-u3-X16"},{"t":"탄소가 더 많이 흡수된다","mis":"SO6-2-u3-X15"},{"t":"동식물이 더 많이 늘어난다","mis":"SO6-2-u3-X15"}],"explanation":["생명체 절반 이상이 살아요.","탄소를 흡수해요.","사라지면 기후변화가 커져요."],"asset":{"type":"passage","lines":["열대 우림은 지구 생명체의 절반 이상이 사는 곳이다.","탄소를 많이 흡수해 지구 온난화의 속도를 늦춘다.","농사·목축·에너지 사용·산업 같은 인간 활동으로 크게 줄었다."],"title":"열대 우림 기사(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#1','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',2,'match','auto','지구촌 문제와 그 원인을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"match","stem":"지구촌 문제와 그 원인을 알맞게 이으세요.","pairs":[{"l":"기후변화","r":"화석 연료를 지나치게 씀"},{"l":"생태계 파괴","r":"무분별한 숲 개발"},{"l":"자원 고갈","r":"산업 발달로 자원을 많이 씀"},{"l":"난민","r":"전쟁과 재난"}],"mis":"SO6-2-u3-X15","explanation":["기후변화는 탄소 때문이에요.","숲을 베면 생태계가 파괴돼요.","전쟁은 난민을 낳아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#2','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',2,'sa','auto','산업이 발달하며 자원과 에너지가 다하여 없어지는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"sa","stem":"산업이 발달하며 자원과 에너지가 다하여 없어지는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["고갈"],"explanation":["다 써서 없어져요.","자원과 에너지 문제예요.","고갈이에요."],"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#3','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'mc','auto','네 장면 가운데 ③ 녹아 무너지는 빙하와 가장 관련 깊은 원인은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"네 장면 가운데 ③ 녹아 무너지는 빙하와 가장 관련 깊은 원인은 어느 것인가요?","options":[{"t":"화석 연료를 지나치게 써 지구의 온도가 오른 것","correct":true},{"t":"광산을 개발한 것","mis":"SO6-2-u3-X15"},{"t":"전쟁이 일어난 것","mis":"SO6-2-u3-X15"},{"t":"사람이 많이 이사한 것","mis":"SO6-2-u3-X15"}],"explanation":["빙하는 더우면 녹아요.","지구가 더워졌어요.","기후변화의 장면이에요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 구리 광산","② 나무가 베어져 손상된 열대 우림","③ 녹아 무너지고 있는 빙하","④ 바다 위 작은 보트에서 구조를 요청하는 사람들"],"title":"네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#4','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'mc','auto','지구촌 시대의 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"지구촌 시대의 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들 사이의 교류가 많아지며 갈등이 생길 수 있다","correct":true},{"t":"먼 곳 소식을 빠르게 들을 수 있다","mis":"SO6-2-u3-X14"},{"t":"다양한 정보를 얻을 수 있다","mis":"SO6-2-u3-X14"},{"t":"여러 나라 문화를 즐길 수 있다","mis":"SO6-2-u3-X14"}],"explanation":["좋은 점과 문제점을 가려요.","교류가 많으면 갈등도 생겨요.","문제점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#5','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'ox','auto','열대 우림 파괴는 열대 우림이 있는 나라만의 문제이고 다른 나라와는 관계없어요.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"ox","stem":"열대 우림 파괴는 열대 우림이 있는 나라만의 문제이고 다른 나라와는 관계없어요.","answer":"X","reason_options":[{"t":"열대 우림은 탄소를 흡수해 지구 전체의 기후에 영향을 주기 때문에","correct":true},{"t":"열대 우림은 사람과 아무 관계가 없기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["숲은 탄소를 흡수해요.","지구 전체와 이어져요.","그래서 X예요."],"asset":{"type":"passage","lines":["열대 우림은 지구 생명체의 절반 이상이 사는 곳이다.","탄소를 많이 흡수해 지구 온난화의 속도를 늦춘다.","농사·목축·에너지 사용·산업 같은 인간 활동으로 크게 줄었다."],"title":"열대 우림 기사(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#6','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'error','auto','네 장면을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"error","stem":"네 장면을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「①의 깎인 광산은 난민 문제를 보여 줘.」","correct":true,"mis_target":"SO6-2-u3-X15"},{"t":"태경 — 「②의 베어진 숲은 생태계 파괴를 보여 줘.」","mis":"SO6-2-u3-X15"},{"t":"하나 — 「④의 보트는 난민 문제를 보여 줘.」","mis":"SO6-2-u3-X15"}],"explanation":["광산은 자원을 캐는 곳이에요.","자원과 에너지 고갈이에요.","지아가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 구리 광산","② 나무가 베어져 손상된 열대 우림","③ 녹아 무너지고 있는 빙하","④ 바다 위 작은 보트에서 구조를 요청하는 사람들"],"title":"네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#7','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'mc','auto','사람들이 버린 비닐과 플라스틱 쓰레기로 바다 생물이 고통받는 일과 가장 관련 깊은 지구촌 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"사람들이 버린 비닐과 플라스틱 쓰레기로 바다 생물이 고통받는 일과 가장 관련 깊은 지구촌 문제는 어느 것인가요?","options":[{"t":"생태계 파괴","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"인구 밀도","mis":"SO6-2-u3-X15"},{"t":"인구 구조","mis":"SO6-2-u3-X15"}],"explanation":["바다 생물이 다쳐요.","살 곳이 더러워져요.","생태계 파괴예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#8','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',4,'mc','auto','지구촌을 위협하는 문제를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X15']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"mc","stem":"지구촌을 위협하는 문제를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"자원과 에너지 고갈, 생태계 파괴, 기후변화, 난민 문제가 있고, 한 나라의 문제가 다른 나라에 영향을 주므로 함께 힘써야 한다","correct":true},{"t":"지구촌 문제는 가난한 나라에만 생긴다","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제는 한 나라가 혼자 해결하면 된다","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제는 자연 현상이라 사람과 관계없다","mis":"SO6-2-u3-X15"}],"explanation":["네 가지 문제가 있어요.","서로 영향을 줘요.","함께 힘써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#9','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',4,'mc','auto','광산 개발로 깎인 산지 장면이 보여 주는 문제를 줄이려는 노력으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"mc","stem":"광산 개발로 깎인 산지 장면이 보여 주는 문제를 줄이려는 노력으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자원을 아껴 쓰고 재활용해 새로 캐내는 양을 줄인다","correct":true},{"t":"광산을 더 많이 개발한다","mis":"SO6-2-u3-X15"},{"t":"쓰고 남은 물건을 모두 버린다","mis":"SO6-2-u3-X15"},{"t":"난민을 받아들이지 않는다","mis":"SO6-2-u3-X15"}],"explanation":["자원이 고갈되고 있어요.","아껴 쓰고 재활용해요.","캐내는 양을 줄여요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 구리 광산","② 나무가 베어져 손상된 열대 우림","③ 녹아 무너지고 있는 빙하","④ 바다 위 작은 보트에서 구조를 요청하는 사람들"],"title":"네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L05_challenge#10','soc',6,2,'u3','L05','g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',4,'essay','teacher','네 장면 가운데 두 장면을 골라 각각 어떤 지구촌 문제인지와 그 원인을 쓰고, 이 문제가 한 나라만의 문제가 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"essay","stem":"네 장면 가운데 두 장면을 골라 각각 어떤 지구촌 문제인지와 그 원인을 쓰고, 이 문제가 한 나라만의 문제가 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: ② 베어진 열대 우림은 생태계 파괴 문제로, 농사·목축·산업 같은 인간의 활동이 원인이다. ③ 녹아 무너지는 빙하는 기후변화 문제로, 석유·석탄 같은 화석 연료를 지나치게 쓴 것이 원인이다. 열대 우림이 사라지면 탄소가 덜 흡수되어 지구 전체의 기후가 바뀌고, 지구촌은 서로 연결되어 있어 한 나라의 문제가 다른 나라에도 영향을 미친다.","scoring_points":["고른 장면의 지구촌 문제를 썼는가","각 문제의 원인을 썼는가","한 나라만의 문제가 아닌 까닭을 썼는가"]},"explanation":["장면과 문제를 짝지어요.","원인을 써요.","서로 이어져 있어요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 구리 광산","② 나무가 베어져 손상된 열대 우림","③ 녹아 무너지고 있는 빙하","④ 바다 위 작은 보트에서 구조를 요청하는 사람들"],"title":"네 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#1','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'mc','auto','편지를 보낸 아프리카 동쪽 나라의 친구가 겪고 있는 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"mc","stem":"편지를 보낸 아프리카 동쪽 나라의 친구가 겪고 있는 문제는 어느 것인가요?","options":[{"t":"아주 심한 가뭄","correct":true},{"t":"큰 홍수","mis":"SO6-2-u3-X15"},{"t":"폭설","mis":"SO6-2-u3-X15"},{"t":"지진","mis":"SO6-2-u3-X15"}],"explanation":["40년 만의 건조한 날씨예요.","물이 모자라요.","가뭄이에요."],"asset":{"type":"passage","lines":["우리 나라는 40년 만의 건조한 날씨로 아주 심한 가뭄을 겪고 있어.","쓸 물이 모자라 먼 곳까지 물을 길으러 가.","우리 나라는 탄소를 적게 내는데도 이런 일이 생겨.","지나친 탄소 배출로 지구에 기후변화가 나타나기 때문이래."],"title":"아프리카 동쪽 나라 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#2','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'mc','auto','지구촌 문제를 조사할 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"mc","stem":"지구촌 문제를 조사할 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"출처가 명확하고 믿을 만한 자료인지 확인한다","correct":true},{"t":"누가 썼는지 모르는 글도 그대로 믿는다","mis":"SO6-2-u3-X17"},{"t":"가장 재미있는 글만 고른다","mis":"SO6-2-u3-X17"},{"t":"자료 없이 생각만으로 쓴다","mis":"SO6-2-u3-X17"}],"explanation":["자료가 믿을 만해야 해요.","출처를 봐요.","확인하고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#3','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'sa','auto','세계지도에 붙이는 붙임쪽지에는 지역, 문제 상황, 그리고 무엇을 요약해서 쓰나요? (문제 □□)','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"sa","stem":"세계지도에 붙이는 붙임쪽지에는 지역, 문제 상황, 그리고 무엇을 요약해서 쓰나요? (문제 □□)","answer":["원인"],"explanation":["왜 생겼는지 써요.","지역과 상황도 써요.","문제 원인이에요."],"mis":"SO6-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#4','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'ox','auto','지구촌 문제를 조사할 때 누리집 통계, 책, 신문 기사, 다큐멘터리 영상을 활용할 수 있어요.',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"ox","stem":"지구촌 문제를 조사할 때 누리집 통계, 책, 신문 기사, 다큐멘터리 영상을 활용할 수 있어요.","answer":"O","reason_options":[{"t":"여러 종류의 믿을 만한 자료로 문제와 원인을 알아볼 수 있기 때문에","correct":true},{"t":"지구촌 문제는 조사할 수 없기 때문에","mis":"SO6-2-u3-X17"}],"mis":"SO6-2-u3-X17","explanation":["통계를 볼 수 있어요.","기사와 영상도 있어요.","여러 자료를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#5','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','편지에서 친구의 나라가 가뭄을 겪는 원인으로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"편지에서 친구의 나라가 가뭄을 겪는 원인으로 든 것은 어느 것인가요?","options":[{"t":"지나친 탄소 배출로 지구에 기후변화가 나타난 것","correct":true},{"t":"그 나라에 사람이 너무 많은 것","mis":"SO6-2-u3-X15"},{"t":"그 나라에 산이 많은 것","mis":"SO6-2-u3-X15"},{"t":"그 나라가 탄소를 가장 많이 낸 것","mis":"SO6-2-u3-X16"}],"explanation":["탄소 배출이 원인이에요.","기후변화가 나타났어요.","그래서 가뭄이 왔어요."],"asset":{"type":"passage","lines":["우리 나라는 40년 만의 건조한 날씨로 아주 심한 가뭄을 겪고 있어.","쓸 물이 모자라 먼 곳까지 물을 길으러 가.","우리 나라는 탄소를 적게 내는데도 이런 일이 생겨.","지나친 탄소 배출로 지구에 기후변화가 나타나기 때문이래."],"title":"아프리카 동쪽 나라 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#6','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','조사한 내용을 붙임쪽지에 정리해 세계지도에 붙이면 좋은 점은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X17']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"조사한 내용을 붙임쪽지에 정리해 세계지도에 붙이면 좋은 점은 어느 것인가요?","options":[{"t":"지구촌 곳곳에 어떤 문제가 나타나는지 한눈에 알 수 있다","correct":true},{"t":"문제가 저절로 해결된다","mis":"SO6-2-u3-X16"},{"t":"조사할 필요가 없어진다","mis":"SO6-2-u3-X17"},{"t":"지도가 더 예뻐진다","mis":"SO6-2-u3-X17"}],"explanation":["나라마다 쪽지를 붙여요.","세계지도에서 한눈에 봐요.","곳곳의 문제를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#7','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','세계지도에 붙인 붙임쪽지에서 「문제 원인」으로 적힌 것은 어느 것인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"세계지도에 붙인 붙임쪽지에서 「문제 원인」으로 적힌 것은 어느 것인가요?","options":[{"t":"탄소 배출과 온실 효과로 지구 온도가 오름","correct":true},{"t":"기록적인 폭염","mis":"SO6-2-u3-X17"},{"t":"바닷속 산호초가 모두 죽음","mis":"SO6-2-u3-X17"},{"t":"우리나라, 유럽, 미국 등","mis":"SO6-2-u3-X17"}],"explanation":["지역·상황·원인이 있어요.","왜 생겼는지가 원인이에요.","지구 온도가 올라서예요."],"asset":{"type":"passage","lines":["지역 — 우리나라, 유럽, 미국 등","문제 상황 — 기록적인 폭염, 바닷속 산호초가 모두 죽음","문제 원인 — 탄소 배출과 온실 효과로 지구 온도가 오름"],"title":"세계지도에 붙인 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#8','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','해수면이 높아지면서 투발루의 섬 두 개가 이미 물에 잠겼어요. 이 문제의 원인으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"해수면이 높아지면서 투발루의 섬 두 개가 이미 물에 잠겼어요. 이 문제의 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후변화로 지구 온도가 올라 해수면이 높아진 것","correct":true},{"t":"투발루의 인구가 너무 많아진 것","mis":"SO6-2-u3-X15"},{"t":"투발루 사람들이 광산을 개발한 것","mis":"SO6-2-u3-X15"},{"t":"투발루에 비가 오지 않은 것","mis":"SO6-2-u3-X15"}],"explanation":["바닷물이 높아졌어요.","지구가 더워졌어요.","기후변화가 원인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#9','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'ox','auto','친구의 나라는 탄소를 적게 내는데도 가뭄을 겪으므로, 우리가 내는 탄소가 다른 나라에 문제를 일으킬 수 있어요.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"ox","stem":"친구의 나라는 탄소를 적게 내는데도 가뭄을 겪으므로, 우리가 내는 탄소가 다른 나라에 문제를 일으킬 수 있어요.","answer":"O","reason_options":[{"t":"탄소가 일으키는 기후변화는 지구 전체에 영향을 주기 때문에","correct":true},{"t":"탄소는 낸 나라 안에서만 영향을 주기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["기후변화는 지구 전체예요.","우리 탄소도 영향을 줘요.","우리 모두의 문제예요."],"asset":{"type":"passage","lines":["우리 나라는 40년 만의 건조한 날씨로 아주 심한 가뭄을 겪고 있어.","쓸 물이 모자라 먼 곳까지 물을 길으러 가.","우리 나라는 탄소를 적게 내는데도 이런 일이 생겨.","지나친 탄소 배출로 지구에 기후변화가 나타나기 때문이래."],"title":"아프리카 동쪽 나라 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_basic#10','soc',6,2,'u3','L06','g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',3,'mc','auto','면 티셔츠 한 벌을 만드는 데 약 2,700 L의 물이 필요해요. 지구촌을 생각하는 옷 구매 습관으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"면 티셔츠 한 벌을 만드는 데 약 2,700 L의 물이 필요해요. 지구촌을 생각하는 옷 구매 습관으로 알맞은 것은 어느 것인가요?","options":[{"t":"필요한 옷만 사고 오래 입는다","correct":true},{"t":"싸면 필요 없어도 여러 벌 산다","mis":"SO6-2-u3-X21"},{"t":"한 번 입고 바로 버린다","mis":"SO6-2-u3-X21"},{"t":"유행이 바뀔 때마다 모두 새로 산다","mis":"SO6-2-u3-X21"}],"explanation":["옷에도 물이 많이 들어요.","버린 옷은 환경을 오염해요.","필요한 만큼만 사요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#1','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',2,'match','auto','지구촌 문제를 조사하는 차례를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"match","stem":"지구촌 문제를 조사하는 차례를 알맞게 이으세요.","pairs":[{"l":"첫째","r":"문제 생각하기"},{"l":"둘째","r":"조사 방법 정하기"},{"l":"셋째","r":"문제 상황과 원인 조사하기"},{"l":"넷째","r":"내용 정리하기"}],"mis":"SO6-2-u3-X17","explanation":["먼저 문제를 떠올려요.","방법을 정하고 조사해요.","마지막에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#2','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',2,'sa','auto','세계지도에 붙인 붙임쪽지에서 문제 상황은 기록적인 폭염과 무엇이 모두 죽은 일인가요? (바닷속 □□□)','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"sa","stem":"세계지도에 붙인 붙임쪽지에서 문제 상황은 기록적인 폭염과 무엇이 모두 죽은 일인가요? (바닷속 □□□)","answer":["산호초"],"explanation":["바닷속 생물이에요.","물이 따뜻해져 죽었어요.","산호초예요."],"asset":{"type":"passage","lines":["지역 — 우리나라, 유럽, 미국 등","문제 상황 — 기록적인 폭염, 바닷속 산호초가 모두 죽음","문제 원인 — 탄소 배출과 온실 효과로 지구 온도가 오름"],"title":"세계지도에 붙인 붙임쪽지"},"mis":"SO6-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#3','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','편지와 붙임쪽지를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X16']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"편지와 붙임쪽지를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"탄소 배출로 생긴 기후변화가 아프리카의 가뭄과 바다의 산호초 죽음처럼 지구 곳곳에 문제를 일으킨다","correct":true},{"t":"두 문제는 서로 원인이 전혀 다르다","mis":"SO6-2-u3-X15"},{"t":"가뭄은 아프리카만의 문제라 우리와 관계없다","mis":"SO6-2-u3-X16"},{"t":"산호초는 탄소와 관계없이 죽었다","mis":"SO6-2-u3-X15"}],"explanation":["두 곳 모두 기후변화예요.","원인은 탄소 배출이에요.","지구 곳곳에 나타나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#4','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','지구촌 문제를 조사할 때 붙임쪽지에 꼭 들어가야 할 내용을 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X17','SO6-2-u3-X23']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"지구촌 문제를 조사할 때 붙임쪽지에 꼭 들어가야 할 내용을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"지역 · 문제 상황 · 문제 원인","correct":true},{"t":"지역 · 내 기분 · 날씨","mis":"SO6-2-u3-X17"},{"t":"문제 상황 · 내 이름 · 쪽수","mis":"SO6-2-u3-X17"},{"t":"나라 이름 · 국기 · 수도","mis":"SO6-2-u3-X23"}],"explanation":["어디에서 생겼나요?","무슨 일이 생겼나요?","왜 생겼나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#5','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'ox','auto','출처를 알 수 없는 누리 소통망 글이라도 내용이 놀라우면 조사 자료로 그대로 써도 돼요.',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"ox","stem":"출처를 알 수 없는 누리 소통망 글이라도 내용이 놀라우면 조사 자료로 그대로 써도 돼요.","answer":"X","reason_options":[{"t":"출처가 명확하고 믿을 만한 자료인지 먼저 확인해야 하기 때문에","correct":true},{"t":"놀라운 내용일수록 언제나 사실이기 때문에","mis":"SO6-2-u3-X17"}],"mis":"SO6-2-u3-X17","explanation":["출처를 확인해요.","믿을 만한지 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#6','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'error','auto','지구촌 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"error","stem":"지구촌 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「투발루가 바다에 잠기는 건 그 나라 일이니 우리는 몰라도 돼.」","correct":true,"mis_target":"SO6-2-u3-X16"},{"t":"지훈 — 「기후변화는 지구 전체의 문제야.」","mis":"SO6-2-u3-X16"},{"t":"서윤 — 「내가 아끼는 전기도 탄소를 줄여.」","mis":"SO6-2-u3-X21"}],"explanation":["기후변화는 모두에게 영향을 줘요.","우리 탄소도 관계있어요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#7','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','지구촌 문제와 관련된 통계를 살펴보려고 해요. 가장 알맞은 자료는 어느 것인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"지구촌 문제와 관련된 통계를 살펴보려고 해요. 가장 알맞은 자료는 어느 것인가요?","options":[{"t":"관련 기관 누리집의 통계 자료","correct":true},{"t":"친구가 들려준 소문","mis":"SO6-2-u3-X17"},{"t":"출처가 없는 댓글","mis":"SO6-2-u3-X17"},{"t":"내가 상상한 숫자","mis":"SO6-2-u3-X17"}],"explanation":["통계는 수로 된 자료예요.","믿을 만한 기관에서 찾아요.","누리집 통계가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#8','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',4,'mc','auto','「지구촌에서 나타나는 문제는 우리 모두의 문제이다」를 뒷받침하는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X17']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"mc","stem":"「지구촌에서 나타나는 문제는 우리 모두의 문제이다」를 뒷받침하는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"탄소를 적게 내는 나라도 기후변화로 가뭄과 침수를 겪는다","correct":true},{"t":"지구촌 문제는 한 나라 안에서만 생긴다","mis":"SO6-2-u3-X16"},{"t":"우리나라는 지구촌 문제를 겪지 않는다","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제는 조사할 수 없다","mis":"SO6-2-u3-X17"}],"explanation":["원인과 피해 나라가 달라요.","탄소는 지구 전체에 영향을 줘요.","모두의 문제예요."],"asset":{"type":"passage","lines":["우리 나라는 40년 만의 건조한 날씨로 아주 심한 가뭄을 겪고 있어.","쓸 물이 모자라 먼 곳까지 물을 길으러 가.","우리 나라는 탄소를 적게 내는데도 이런 일이 생겨.","지나친 탄소 배출로 지구에 기후변화가 나타나기 때문이래."],"title":"아프리카 동쪽 나라 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#9','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C11',4,'mc','auto','옷 이야기를 읽고 「내 작은 행동이 지구 환경에 영향을 준다」고 생각한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"mc","stem":"옷 이야기를 읽고 「내 작은 행동이 지구 환경에 영향을 준다」고 생각한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옷 한 벌에 많은 물이 들고 버린 옷이 환경을 오염하므로, 내가 덜 사고 오래 입으면 그만큼 줄일 수 있기 때문에","correct":true},{"t":"옷은 지구 환경과 관계가 없기 때문에","mis":"SO6-2-u3-X16"},{"t":"옷을 많이 살수록 물이 아껴지기 때문에","mis":"SO6-2-u3-X21"},{"t":"나 하나 바꿔도 아무 소용이 없기 때문에","mis":"SO6-2-u3-X21"}],"explanation":["옷에 물이 많이 들어요.","버린 옷이 오염을 일으켜요.","내 습관이 바뀌면 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L06_challenge#10','soc',6,2,'u3','L06','g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',4,'essay','teacher','내가 조사하고 싶은 지구촌 문제를 하나 골라 붙임쪽지 내용(지역·문제 상황·문제 원인)을 쓰고, 조사할 때 쓸 자료와 주의할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"essay","stem":"내가 조사하고 싶은 지구촌 문제를 하나 골라 붙임쪽지 내용(지역·문제 상황·문제 원인)을 쓰고, 조사할 때 쓸 자료와 주의할 점을 쓰세요.","answer_guide":{"answer":"예: 지역 — 남태평양의 투발루. 문제 상황 — 해수면이 높아져 섬 두 개가 이미 물에 잠겼고 주민들이 다른 나라로 옮겨 가려 한다. 문제 원인 — 탄소 배출로 지구 온도가 올라 기후변화가 나타났다. 자료는 관련 기관 누리집의 통계와 신문 기사, 다큐멘터리 영상을 쓰고, 출처가 명확하고 믿을 만한 자료인지 확인하겠다.","scoring_points":["지역·문제 상황·문제 원인을 썼는가","알맞은 조사 자료를 썼는가","출처 확인 같은 주의할 점을 썼는가"]},"explanation":["세 칸을 채워요.","자료를 골라요.","출처를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#1','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',1,'mc','auto','지구촌의 지속가능한 미래는 어떻게 이루어지나요?',ARRAY['SO6-2-u3-X18','SO6-2-u3-X19']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"mc","stem":"지구촌의 지속가능한 미래는 어떻게 이루어지나요?","options":[{"t":"오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어진다","correct":true},{"t":"지금 세대가 자원을 마음껏 쓰면 이루어진다","mis":"SO6-2-u3-X18"},{"t":"한 나라만 노력하면 이루어진다","mis":"SO6-2-u3-X19"},{"t":"미래 세대가 알아서 해결하면 된다","mis":"SO6-2-u3-X18"}],"explanation":["지금의 모든 사람이 노력해요.","환경을 보존해요.","미래 세대에 물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#2','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',1,'mc','auto','지속가능한 미래를 위한 개인의 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"mc","stem":"지속가능한 미래를 위한 개인의 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰레기를 분리배출하고 재활용한다","correct":true},{"t":"기후변화 협약에 가입한다","mis":"SO6-2-u3-X19"},{"t":"친환경 소재 제품 기술을 개발한다","mis":"SO6-2-u3-X19"},{"t":"난민 보호 시설을 마련한다","mis":"SO6-2-u3-X19"}],"explanation":["생활 속 실천이에요.","내가 할 수 있어요.","분리배출과 재활용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#3','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',1,'sa','auto','개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체를 무엇이라고 하나요? (□□□ 기구)','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"sa","stem":"개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체를 무엇이라고 하나요? (□□□ 기구)","answer":["비정부"],"explanation":["나라가 만든 게 아니에요.","민간단체가 만들어요.","비정부 기구예요."],"mis":"SO6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#4','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',1,'ox','auto','녹색 제품은 생산할 때 자원이나 에너지를 적게 써 오염 물질 배출을 줄인 제품이에요.',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"ox","stem":"녹색 제품은 생산할 때 자원이나 에너지를 적게 써 오염 물질 배출을 줄인 제품이에요.","answer":"O","reason_options":[{"t":"그래서 녹색 제품을 소비하면 지구 환경을 지키는 데 도움이 되기 때문에","correct":true},{"t":"녹색 제품은 초록색으로 칠한 제품일 뿐이기 때문에","mis":"SO6-2-u3-X19"}],"mis":"SO6-2-u3-X19","explanation":["자원과 에너지를 적게 써요.","오염 물질을 줄여요.","녹색 제품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#5','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'match','auto','노력 카드를 보고 카드와 노력하는 주체를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"match","stem":"노력 카드를 보고 카드와 노력하는 주체를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"개인"},{"l":"㉯","r":"기업"},{"l":"㉰","r":"국가"},{"l":"㉱","r":"국제기구"}],"mis":"SO6-2-u3-X19","explanation":["㉮는 생활 속 실천이에요.","㉯는 제품, ㉰는 협약이에요.","㉱는 국제 연합 아동 기금이에요."],"asset":{"type":"passage","lines":["㉮ 녹색 제품을 사고 쓰레기를 분리배출한다.","㉯ 라벨을 없애고 뚜껑을 줄인 생수병을 만든다.","㉰ 기후변화 협약에 가입하고 탄소를 줄일 목표를 세운다.","㉱ 어려운 어린이에게 의료·식량·교육을 제공한다.","㉲ 고통받는 사람에게 차별 없이 의료를 제공하는 민간 단체이다."],"title":"노력 카드 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#6','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',2,'mc','auto','노력 카드 ㉲처럼 고통받는 사람에게 차별 없이 의료를 제공하는 비정부 기구는 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"mc","stem":"노력 카드 ㉲처럼 고통받는 사람에게 차별 없이 의료를 제공하는 비정부 기구는 어느 것인가요?","options":[{"t":"국경 없는 의사회","correct":true},{"t":"국제 연합","mis":"SO6-2-u3-X20"},{"t":"그린피스","mis":"SO6-2-u3-X20"},{"t":"세계 자연 기금","mis":"SO6-2-u3-X20"}],"explanation":["의사들의 단체예요.","차별 없이 치료해요.","국경 없는 의사회예요."],"asset":{"type":"passage","lines":["㉮ 녹색 제품을 사고 쓰레기를 분리배출한다.","㉯ 라벨을 없애고 뚜껑을 줄인 생수병을 만든다.","㉰ 기후변화 협약에 가입하고 탄소를 줄일 목표를 세운다.","㉱ 어려운 어린이에게 의료·식량·교육을 제공한다.","㉲ 고통받는 사람에게 차별 없이 의료를 제공하는 민간 단체이다."],"title":"노력 카드 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#7','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',2,'mc','auto','난민을 보호하고 생활에 필요한 물품·의료·교육을 제공하는 국제기구는 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"mc","stem":"난민을 보호하고 생활에 필요한 물품·의료·교육을 제공하는 국제기구는 어느 것인가요?","options":[{"t":"국제 연합 난민 기구","correct":true},{"t":"국제 연합 아동 기금","mis":"SO6-2-u3-X20"},{"t":"그린피스","mis":"SO6-2-u3-X20"},{"t":"세계 자연 기금","mis":"SO6-2-u3-X20"}],"explanation":["난민을 돕는 기구예요.","국제 연합 기구예요.","국제 연합 난민 기구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#8','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'mc','auto','라벨을 없애고 뚜껑 크기를 줄인 생수병을 만드는 것은 어느 주체의 노력인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"라벨을 없애고 뚜껑 크기를 줄인 생수병을 만드는 것은 어느 주체의 노력인가요?","options":[{"t":"기업","correct":true},{"t":"개인","mis":"SO6-2-u3-X19"},{"t":"국가","mis":"SO6-2-u3-X19"},{"t":"비정부 기구","mis":"SO6-2-u3-X20"}],"explanation":["제품을 만들어요.","자원을 적게 써요.","기업의 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#9','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'ox','auto','지구에 사는 다양한 동식물과 공존하려면 인간 위주로 생각하는 태도를 버려야 해요.',ARRAY['SO6-2-u3-X18']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"ox","stem":"지구에 사는 다양한 동식물과 공존하려면 인간 위주로 생각하는 태도를 버려야 해요.","answer":"O","reason_options":[{"t":"지구촌에 사는 모두를 생각해야 지속가능한 미래를 만들 수 있기 때문에","correct":true},{"t":"사람에게 편리하기만 하면 동식물은 생각하지 않아도 되기 때문에","mis":"SO6-2-u3-X18"}],"mis":"SO6-2-u3-X18","explanation":["서식지가 사라지고 있어요.","모두를 생각해야 해요.","함께 살아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_basic#10','soc',6,2,'u3','L07','g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',3,'mc','auto','노력 카드를 다섯 주체의 줄에 모았더니 다섯 줄이 모두 팽팽해졌을 때에야 지구가 올라갔어요. 이것이 뜻하는 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X21']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"노력 카드를 다섯 주체의 줄에 모았더니 다섯 줄이 모두 팽팽해졌을 때에야 지구가 올라갔어요. 이것이 뜻하는 것은 어느 것인가요?","options":[{"t":"지속가능한 미래는 한 주체가 아니라 여러 주체의 노력이 모두 모여야 이루어진다","correct":true},{"t":"개인 한 사람의 노력만 있으면 충분하다","mis":"SO6-2-u3-X19"},{"t":"국가만 노력하면 지구가 올라간다","mis":"SO6-2-u3-X19"},{"t":"노력은 아무 의미가 없다","mis":"SO6-2-u3-X21"}],"explanation":["모든 줄이 팽팽해야 해요.","한 줄로는 안 올라가요.","모두의 노력이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#1','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',2,'match','auto','단체와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"match","stem":"단체와 하는 일을 알맞게 이으세요.","pairs":[{"l":"국제 연합","r":"국제 평화와 안전을 위해 협력한다"},{"l":"국제 연합 아동 기금","r":"어려운 어린이에게 의료·식량·교육을 준다"},{"l":"세계 자연 기금","r":"생물 다양성을 보전한다"},{"l":"그린피스","r":"해양 생태계를 보호한다"}],"mis":"SO6-2-u3-X20","explanation":["국제 연합은 평화예요.","아동 기금은 어린이예요.","두 비정부 기구는 자연이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#2','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',2,'sa','auto','탄소 배출을 줄이려고 여러 나라가 가입하는 약속을 무엇이라고 하나요? (기후변화 □□)','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"sa","stem":"탄소 배출을 줄이려고 여러 나라가 가입하는 약속을 무엇이라고 하나요? (기후변화 □□)","answer":["협약"],"explanation":["나라들의 약속이에요.","국가가 가입해요.","기후변화 협약이에요."],"mis":"SO6-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#3','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'mc','auto','노력 카드 ㉰가 국가의 노력인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"노력 카드 ㉰가 국가의 노력인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라가 국제 협약에 가입하고 법·정책으로 목표를 세우는 일이기 때문에","correct":true},{"t":"사람 한 명이 집에서 하는 일이기 때문에","mis":"SO6-2-u3-X19"},{"t":"기업이 제품을 만드는 일이기 때문에","mis":"SO6-2-u3-X19"},{"t":"민간단체가 의료를 제공하는 일이기 때문에","mis":"SO6-2-u3-X20"}],"explanation":["협약은 나라가 가입해요.","목표도 나라가 세워요.","국가의 노력이에요."],"asset":{"type":"passage","lines":["㉮ 녹색 제품을 사고 쓰레기를 분리배출한다.","㉯ 라벨을 없애고 뚜껑을 줄인 생수병을 만든다.","㉰ 기후변화 협약에 가입하고 탄소를 줄일 목표를 세운다.","㉱ 어려운 어린이에게 의료·식량·교육을 제공한다.","㉲ 고통받는 사람에게 차별 없이 의료를 제공하는 민간 단체이다."],"title":"노력 카드 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#4','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',3,'mc','auto','국제기구와 비정부 기구를 가장 바르게 구분한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"mc","stem":"국제기구와 비정부 기구를 가장 바르게 구분한 것은 어느 것인가요?","options":[{"t":"국제 연합·국제 연합 아동 기금은 국제기구, 국경 없는 의사회·그린피스는 비정부 기구이다","correct":true},{"t":"국경 없는 의사회는 국제기구, 국제 연합은 비정부 기구이다","mis":"SO6-2-u3-X20"},{"t":"모든 단체는 국가가 만든 기구이다","mis":"SO6-2-u3-X20"},{"t":"그린피스와 국제 연합은 같은 종류의 기구이다","mis":"SO6-2-u3-X20"}],"explanation":["국제기구는 나라들이 만들어요.","비정부 기구는 민간이 만들어요.","둘을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#5','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'ox','auto','사람들이 친환경 소재 물품을 사면 기업의 제품 생산 방식이 바뀌기도 해요.',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"ox","stem":"사람들이 친환경 소재 물품을 사면 기업의 제품 생산 방식이 바뀌기도 해요.","answer":"O","reason_options":[{"t":"개인의 소비가 기업과 사회의 변화를 이끌 수 있기 때문에","correct":true},{"t":"개인의 소비는 기업과 아무 관계가 없기 때문에","mis":"SO6-2-u3-X21"}],"mis":"SO6-2-u3-X21","explanation":["찾는 사람이 늘어요.","기업이 만드는 방식을 바꿔요.","개인이 변화를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#6','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'error','auto','지속가능한 미래를 위한 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"error","stem":"지속가능한 미래를 위한 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「기후변화 협약에 가입하는 건 개인이 하는 노력이야.」","correct":true,"mis_target":"SO6-2-u3-X19"},{"t":"준우 — 「일회용품을 줄이는 건 개인의 노력이야.」","mis":"SO6-2-u3-X19"},{"t":"채원 — 「친환경 제품 기술 개발은 기업의 노력이야.」","mis":"SO6-2-u3-X19"}],"explanation":["협약 가입은 국가가 해요.","개인은 생활 속 실천을 해요.","하린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#7','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'mc','auto','동식물이 사라지는 공익 광고 영상을 보고 알 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X18','SO6-2-u3-X16']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"동식물이 사라지는 공익 광고 영상을 보고 알 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"무분별한 개발과 환경 오염으로 동식물의 서식지가 사라지기 때문에","correct":true},{"t":"동식물이 스스로 다른 행성으로 떠나기 때문에","mis":"SO6-2-u3-X18"},{"t":"사람이 동식물을 너무 많이 키우기 때문에","mis":"SO6-2-u3-X18"},{"t":"동식물이 사라지는 것은 사람과 관계없기 때문에","mis":"SO6-2-u3-X16"}],"explanation":["개발이 늘었어요.","환경이 오염됐어요.","살 곳이 사라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#8','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',4,'mc','auto','전쟁 때문에 고향을 떠난 어린이를 돕는 일과 가장 관련 깊은 단체를 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20','SO6-2-u3-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C10","difficulty":4,"kind":"mc","stem":"전쟁 때문에 고향을 떠난 어린이를 돕는 일과 가장 관련 깊은 단체를 바르게 묶은 것은 어느 것인가요?","options":[{"t":"국제 연합 난민 기구 · 국제 연합 아동 기금","correct":true},{"t":"그린피스 · 세계 자연 기금","mis":"SO6-2-u3-X20"},{"t":"기업 · 개인","mis":"SO6-2-u3-X19"},{"t":"국경 없는 의사회만","mis":"SO6-2-u3-X20"}],"explanation":["난민을 돕는 기구가 있어요.","어린이를 돕는 기구도 있어요.","두 국제기구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#9','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',4,'mc','auto','지속가능한 미래를 위한 노력을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X21','SO6-2-u3-X18']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C9","difficulty":4,"kind":"mc","stem":"지속가능한 미래를 위한 노력을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"개인·기업·국가·국제기구·비정부 기구가 저마다 할 수 있는 일을 하며 힘을 모은다","correct":true},{"t":"국가만 법을 만들면 모두 해결된다","mis":"SO6-2-u3-X19"},{"t":"개인은 할 수 있는 일이 없다","mis":"SO6-2-u3-X21"},{"t":"지금 세대가 편리하게 쓰고 나중에 생각한다","mis":"SO6-2-u3-X18"}],"explanation":["여러 주체가 있어요.","저마다 할 일이 있어요.","힘을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L07_challenge#10','soc',6,2,'u3','L07','g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',4,'essay','teacher','지속가능한 미래의 뜻을 쓰고, 개인·기업·국가의 노력을 각각 한 가지씩 쓴 뒤, 여러 주체의 노력이 함께 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C9","difficulty":4,"kind":"essay","stem":"지속가능한 미래의 뜻을 쓰고, 개인·기업·국가의 노력을 각각 한 가지씩 쓴 뒤, 여러 주체의 노력이 함께 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 지속가능한 미래는 오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어진다. 개인은 녹색 제품을 쓰고 분리배출을 하며, 기업은 자원을 적게 쓴 제품을 만들고, 국가는 기후변화 협약에 가입한다. 지구촌 문제는 크고 서로 이어져 있어 한 주체의 노력만으로는 해결할 수 없으므로 모두가 힘을 모아야 한다.","scoring_points":["지속가능한 미래의 뜻을 썼는가","개인·기업·국가의 노력을 하나씩 썼는가","함께 노력해야 하는 까닭을 썼는가"]},"explanation":["미래 세대에 물려줘요.","주체마다 할 일이 있어요.","함께해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#1','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'mc','auto','지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람을 무엇이라고 하나요?',ARRAY['SO6-2-u3-X20','SO6-2-u3-X15']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"mc","stem":"지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람을 무엇이라고 하나요?","options":[{"t":"세계시민","correct":true},{"t":"비정부 기구","mis":"SO6-2-u3-X20"},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"국제 연합","mis":"SO6-2-u3-X20"}],"explanation":["지구촌의 한 사람이에요.","책임 있게 행동해요.","세계시민이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#2','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'mc','auto','더하기(+) 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"mc","stem":"더하기(+) 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장바구니 사용하기","correct":true},{"t":"플라스틱 덜 사용하기","mis":"SO6-2-u3-X21"},{"t":"안 쓰는 전등 끄기","mis":"SO6-2-u3-X21"},{"t":"일회용 컵 줄이기","mis":"SO6-2-u3-X21"}],"explanation":["더 자주 해야 할 일이에요.","장바구니를 더 써요.","더하기 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#3','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'sa','auto','실천 인증 릴레이에서 인증 사진을 찍고 기록한 다음에는 누구에게 알리나요? (다음 차례 □□)','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"sa","stem":"실천 인증 릴레이에서 인증 사진을 찍고 기록한 다음에는 누구에게 알리나요? (다음 차례 □□)","answer":["친구"],"explanation":["바통을 넘겨요.","다음 차례예요.","다음 친구에게 알려요."],"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#4','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'ox','auto','세계시민은 지구촌 문제를 우리 모두의 문제라고 생각하고 해결하려고 노력해요.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"ox","stem":"세계시민은 지구촌 문제를 우리 모두의 문제라고 생각하고 해결하려고 노력해요.","answer":"O","reason_options":[{"t":"지구촌 문제가 서로 이어져 모두에게 영향을 주기 때문에","correct":true},{"t":"지구촌 문제는 먼 나라만의 일이기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["모두의 문제예요.","관심을 둬요.","해결하려 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#5','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','실천 인증 릴레이 차례에서 ②에 해당하는 일은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"실천 인증 릴레이 차례에서 ②에 해당하는 일은 어느 것인가요?","options":[{"t":"사진과 함께 실천한 내용을 구체적으로 기록한다","correct":true},{"t":"다음 차례 친구에게 알린다","mis":"SO6-2-u3-X21"},{"t":"실천하는 모습을 사진으로 찍는다","mis":"SO6-2-u3-X21"},{"t":"다른 모둠의 기록을 지운다","mis":"SO6-2-u3-X21"}],"explanation":["①은 사진이에요.","②는 기록이에요.","③은 알리기예요."],"asset":{"type":"passage","lines":["① 실천하는 모습을 인증 사진으로 찍는다.","② 사진과 함께 실천한 내용을 구체적으로 기록한다.","③ 다음 차례 친구에게 알린다.","④ 다음 친구도 ①~③처럼 이어 간다."],"title":"실천 인증 릴레이 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#6','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','빼기(−) 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"빼기(−) 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"플라스틱 덜 사용하기","correct":true},{"t":"시장바구니 사용하기","mis":"SO6-2-u3-X21"},{"t":"다회용품 사용하기","mis":"SO6-2-u3-X21"},{"t":"나무 심기","mis":"SO6-2-u3-X21"}],"explanation":["줄이거나 없애야 할 일이에요.","플라스틱을 덜 써요.","빼기 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#7','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','모둠에서 우리가 할 수 있는 일을 정할 때 생각할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"모둠에서 우리가 할 수 있는 일을 정할 때 생각할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"일상생활에서 실천할 수 있는지, 문제 해결에 효과가 있는지","correct":true},{"t":"가장 어렵고 비싼 일인지","mis":"SO6-2-u3-X21"},{"t":"한 번만 하면 끝나는 일인지","mis":"SO6-2-u3-X21"},{"t":"다른 사람에게만 시키는 일인지","mis":"SO6-2-u3-X21"}],"explanation":["실천할 수 있어야 해요.","효과도 있어야 해요.","두 가지를 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#8','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','모둠에서 토의할 주제를 정할 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"모둠에서 토의할 주제를 정할 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 관심 있는 주제가 다를 수 있음을 이해하고 의견을 존중한다","correct":true},{"t":"목소리가 큰 친구의 주제로 정한다","mis":"SO6-2-u3-X21"},{"t":"다른 친구의 의견은 듣지 않는다","mis":"SO6-2-u3-X21"},{"t":"주제를 정하지 않고 바로 실천한다","mis":"SO6-2-u3-X21"}],"explanation":["관심이 다를 수 있어요.","의견을 존중해요.","함께 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#9','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'ox','auto','내가 하는 작은 실천은 지구를 살리는 데 아무 도움이 되지 않아요.',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"ox","stem":"내가 하는 작은 실천은 지구를 살리는 데 아무 도움이 되지 않아요.","answer":"X","reason_options":[{"t":"작은 실천이 모이고 이어져 지구를 살리는 일이 되기 때문에","correct":true},{"t":"지구는 큰 나라만 살릴 수 있기 때문에","mis":"SO6-2-u3-X21"}],"mis":"SO6-2-u3-X21","explanation":["작은 실천도 모여요.","릴레이로 이어져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_basic#10','soc',6,2,'u3','L08','g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',3,'mc','auto','양치질할 때 물을 받아 쓰는 모습을 찍어 릴레이에 올리려고 해요. 가장 알맞은 계획은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"양치질할 때 물을 받아 쓰는 모습을 찍어 릴레이에 올리려고 해요. 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"3일 동안 집과 학교에서 양치할 때 물을 받아 쓰고, 그 모습을 찍어 구체적으로 기록한 뒤 다음 친구에게 알린다","correct":true},{"t":"한 번만 찍고 기록 없이 끝낸다","mis":"SO6-2-u3-X21"},{"t":"다른 사람이 한 사진을 내 것처럼 올린다","mis":"SO6-2-u3-X21"},{"t":"물을 틀어 놓은 채 사진만 찍는다","mis":"SO6-2-u3-X21"}],"explanation":["기간과 장소를 정해요.","구체적으로 기록해요.","다음 친구에게 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#1','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',2,'match','auto','실천과 노력의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"match","stem":"실천과 노력의 종류를 알맞게 이으세요.","pairs":[{"l":"다회용품 더 쓰기","r":"더 자주 할 더하기(+) 노력"},{"l":"안 쓰는 전등 끄기","r":"줄여야 할 빼기(−) 노력"},{"l":"인증 사진 찍기","r":"실천 인증 릴레이의 첫 단계"}],"mis":"SO6-2-u3-X21","explanation":["더 자주 할 일은 더하기예요.","줄일 일은 빼기예요.","릴레이는 사진부터 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#2','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',2,'sa','auto','자연에서 얻은 재료나 버려진 물건을 활용해 자연과 사람에게 해가 없는 제품을 디자인하는 사람을 무엇이라고 하나요? (□□ 제품 디자이너)','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"sa","stem":"자연에서 얻은 재료나 버려진 물건을 활용해 자연과 사람에게 해가 없는 제품을 디자인하는 사람을 무엇이라고 하나요? (□□ 제품 디자이너)","answer":["에코"],"explanation":["친환경 제품을 디자인해요.","버리는 과정까지 생각해요.","에코 제품 디자이너예요."],"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#3','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','실천 인증 릴레이에서 앞 친구가 알리기를 마치기 전에는 다음 친구가 시작할 수 없어요. 이것이 뜻하는 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"실천 인증 릴레이에서 앞 친구가 알리기를 마치기 전에는 다음 친구가 시작할 수 없어요. 이것이 뜻하는 것은 어느 것인가요?","options":[{"t":"한 사람의 실천이 다음 사람의 실천으로 이어져 함께 넓어진다","correct":true},{"t":"먼저 한 친구만 실천하면 된다","mis":"SO6-2-u3-X21"},{"t":"차례는 아무렇게나 바꿔도 된다","mis":"SO6-2-u3-X21"},{"t":"실천은 혼자만 하는 일이다","mis":"SO6-2-u3-X21"}],"explanation":["바통을 넘겨요.","실천이 이어져요.","함께 넓어져요."],"asset":{"type":"passage","lines":["① 실천하는 모습을 인증 사진으로 찍는다.","② 사진과 함께 실천한 내용을 구체적으로 기록한다.","③ 다음 차례 친구에게 알린다.","④ 다음 친구도 ①~③처럼 이어 간다."],"title":"실천 인증 릴레이 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#4','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','세계시민으로서 필요한 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"세계시민으로서 필요한 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내 행동에 책임감을 가지고 생활 속 작은 일부터 실천한다","correct":true},{"t":"지구촌 문제는 어른들이 해결할 일이라고 여긴다","mis":"SO6-2-u3-X16"},{"t":"먼 나라의 문제에는 관심을 두지 않는다","mis":"SO6-2-u3-X16"},{"t":"남의 실천만 평가하고 나는 하지 않는다","mis":"SO6-2-u3-X21"}],"explanation":["책임감을 가져요.","작은 일부터 해요.","세계시민의 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#5','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'ox','auto','개인의 실천뿐 아니라 학교나 학급 차원에서 함께 실천할 방법을 찾는 것도 좋아요.',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"ox","stem":"개인의 실천뿐 아니라 학교나 학급 차원에서 함께 실천할 방법을 찾는 것도 좋아요.","answer":"O","reason_options":[{"t":"여럿이 함께하면 실천이 더 넓게 퍼지고 효과가 커지기 때문에","correct":true},{"t":"실천은 반드시 혼자서만 해야 하기 때문에","mis":"SO6-2-u3-X21"}],"mis":"SO6-2-u3-X21","explanation":["혼자도 할 수 있어요.","학급이 함께하면 커져요.","여럿이 해도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#6','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'error','auto','실천 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"error","stem":"실천 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다온 — 「일주일 동안 지구를 한 바퀴 걸어서 돌며 탄소를 줄이자.」","correct":true,"mis_target":"SO6-2-u3-X21"},{"t":"수아 — 「학교에서 손 씻을 때 물을 잠그자.」","mis":"SO6-2-u3-X21"},{"t":"윤재 — 「급식은 먹을 만큼만 덜자.」","mis":"SO6-2-u3-X21"}],"explanation":["실천할 수 있어야 해요.","지구 한 바퀴는 불가능해요.","다온의 계획이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#7','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','빈 교실 전등 끄기와 먹을 만큼만 음식 덜기가 지구촌 문제 해결과 이어지는 까닭은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X16']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"빈 교실 전등 끄기와 먹을 만큼만 음식 덜기가 지구촌 문제 해결과 이어지는 까닭은 어느 것인가요?","options":[{"t":"에너지와 음식물 쓰레기를 줄여 탄소 배출과 환경 오염을 줄이기 때문에","correct":true},{"t":"전등을 끄면 지구가 어두워지기 때문에","mis":"SO6-2-u3-X21"},{"t":"음식을 남기면 지구가 깨끗해지기 때문에","mis":"SO6-2-u3-X21"},{"t":"두 일은 지구촌 문제와 관계없기 때문에","mis":"SO6-2-u3-X16"}],"explanation":["에너지를 아껴요.","쓰레기를 줄여요.","탄소가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#8','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',4,'mc','auto','「개인의 노력은 기업과 사회의 변화를 만들 수 있다」를 가장 잘 보여 주는 예는 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"mc","stem":"「개인의 노력은 기업과 사회의 변화를 만들 수 있다」를 가장 잘 보여 주는 예는 어느 것인가요?","options":[{"t":"사람들이 친환경 소재 물품을 고르자 기업이 제품 생산 방식을 바꾸었다","correct":true},{"t":"한 사람이 일회용품을 더 많이 썼다","mis":"SO6-2-u3-X21"},{"t":"기업이 개인과 상관없이 제품을 그대로 만들었다","mis":"SO6-2-u3-X19"},{"t":"국가가 협약에서 빠졌다","mis":"SO6-2-u3-X19"}],"explanation":["개인이 골라요.","기업이 바뀌어요.","사회가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#9','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',4,'mc','auto','지구촌 문제를 해결하려는 세계시민의 모습을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"mc","stem":"지구촌 문제를 해결하려는 세계시민의 모습을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"지구촌 문제에 관심을 두고 해결 방법을 고민하며, 친구들과 협력해 생활 속 실천을 이어 간다","correct":true},{"t":"지구촌 문제는 먼 나라 일이라 관심을 두지 않는다","mis":"SO6-2-u3-X16"},{"t":"남이 실천하는 것만 지켜본다","mis":"SO6-2-u3-X21"},{"t":"한 번 실천하고 나면 그만둔다","mis":"SO6-2-u3-X21"}],"explanation":["관심을 둬요.","방법을 고민해요.","함께 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L08_challenge#10','soc',6,2,'u3','L08','g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',4,'essay','teacher','세계시민의 뜻을 쓰고, 내가 실천할 더하기(+) 노력과 빼기(−) 노력을 하나씩 정해 실천 인증 릴레이 계획(기간·장소·기록 방법)을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"세계시민의 뜻을 쓰고, 내가 실천할 더하기(+) 노력과 빼기(−) 노력을 하나씩 정해 실천 인증 릴레이 계획(기간·장소·기록 방법)을 쓰세요.","answer_guide":{"answer":"예: 세계시민은 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람이다. 더하기 노력은 장바구니 들고 가기, 빼기 노력은 안 쓰는 전등 끄기로 정했다. 3일 동안 집과 학교에서 실천하고, 실천하는 모습을 사진으로 찍어 언제 어디서 무엇을 했는지 구체적으로 기록한 뒤 다음 차례 친구에게 알리겠다.","scoring_points":["세계시민의 뜻을 썼는가","더하기·빼기 노력을 알맞게 하나씩 정했는가","기간·장소·기록 방법을 담은 릴레이 계획을 썼는가"]},"explanation":["세계시민의 뜻을 써요.","더하기·빼기를 구분해요.","실천할 수 있게 계획해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#1','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'mc','auto','영상물이나 그림책을 만들려고 장면을 구성하며 이야기의 흐름을 작성한 것을 무엇이라고 하나요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"mc","stem":"영상물이나 그림책을 만들려고 장면을 구성하며 이야기의 흐름을 작성한 것을 무엇이라고 하나요?","options":[{"t":"스토리보드","correct":true},{"t":"인구 피라미드","mis":"SO6-2-u3-X22"},{"t":"붙임쪽지","mis":"SO6-2-u3-X22"},{"t":"실천 인증서","mis":"SO6-2-u3-X22"}],"explanation":["장면별로 구성해요.","줄거리와 그림이 들어가요.","스토리보드예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#2','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'mc','auto','스토리보드에 장면별로 들어가는 것을 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X22']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"mc","stem":"스토리보드에 장면별로 들어가는 것을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"줄거리와 스케치 형식의 그림","correct":true},{"t":"나라별 인구수 표","mis":"SO6-2-u3-X23"},{"t":"지도와 통계만","mis":"SO6-2-u3-X22"},{"t":"친구들의 이름","mis":"SO6-2-u3-X22"}],"explanation":["장면마다 그림이 있어요.","줄거리도 있어요.","스토리보드의 구성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#3','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'sa','auto','그림책 계획을 세울 때 정하는, 그림책을 읽을 사람을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"sa","stem":"그림책 계획을 세울 때 정하는, 그림책을 읽을 사람을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["독자"],"explanation":["읽을 사람이에요.","수준에 맞게 써요.","독자예요."],"mis":"SO6-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#4','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'ox','auto','그림책 계획을 세울 때는 독자를 정하고 그 수준에 맞는 내용을 구성해요.',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"ox","stem":"그림책 계획을 세울 때는 독자를 정하고 그 수준에 맞는 내용을 구성해요.","answer":"O","reason_options":[{"t":"읽는 사람이 이해할 수 있어야 그림책이 뜻을 전하기 때문에","correct":true},{"t":"독자는 그림책을 다 만든 뒤에 정하면 되기 때문에","mis":"SO6-2-u3-X22"}],"mis":"SO6-2-u3-X22","explanation":["독자를 먼저 정해요.","수준을 맞춰요.","그래야 잘 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#5','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','모둠 그림책 계획에서 독자가 8~9세 어린이일 때 글을 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"모둠 그림책 계획에서 독자가 8~9세 어린이일 때 글을 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"쉬운 낱말과 짧은 문장으로 쓴다","correct":true},{"t":"어려운 전문 용어를 많이 넣는다","mis":"SO6-2-u3-X22"},{"t":"통계 수치를 빠짐없이 넣는다","mis":"SO6-2-u3-X23"},{"t":"한 장면에 아주 긴 문장을 쓴다","mis":"SO6-2-u3-X22"}],"explanation":["어린 독자예요.","쉽게 써야 해요.","짧고 쉬운 문장이에요."],"asset":{"type":"passage","lines":["독자 — 8~9세 어린이","주제 — 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자","장면 1 — 발달한 도시에 사람들이 빼곡하게 사는 모습","장면 2 — 사람이 드문 사막과 얼음 땅","장면 3 — 베어진 숲에서 갈 곳을 잃은 동물","장면 4 — 장바구니를 들고 시장에 가는 아이"],"title":"모둠 그림책 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#6','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','모둠 그림책 계획에서 장면 1 다음에 장면 2가 이어지면 어떤 이야기 흐름이 되나요?',ARRAY['SO6-2-u3-X02','SO6-2-u3-X03','SO6-2-u3-X22']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"모둠 그림책 계획에서 장면 1 다음에 장면 2가 이어지면 어떤 이야기 흐름이 되나요?","options":[{"t":"어떤 지역은 인구가 많고 어떤 지역은 인구가 적다","correct":true},{"t":"모든 지역에 인구가 똑같다","mis":"SO6-2-u3-X02"},{"t":"인구가 많은 곳은 사막뿐이다","mis":"SO6-2-u3-X03"},{"t":"도시와 사막은 관계없는 이야기다","mis":"SO6-2-u3-X22"}],"explanation":["장면 1은 빼곡한 도시예요.","장면 2는 드문 사막과 얼음 땅이에요.","인구 분포를 견줘요."],"asset":{"type":"passage","lines":["독자 — 8~9세 어린이","주제 — 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자","장면 1 — 발달한 도시에 사람들이 빼곡하게 사는 모습","장면 2 — 사람이 드문 사막과 얼음 땅","장면 3 — 베어진 숲에서 갈 곳을 잃은 동물","장면 4 — 장바구니를 들고 시장에 가는 아이"],"title":"모둠 그림책 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#7','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','그림책에 단원에서 공부한 내용을 담을 때 알맞은 방법은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"그림책에 단원에서 공부한 내용을 담을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"세계 인구의 특징과 지속가능한 지구촌의 주제가 골고루 드러나게 구성한다","correct":true},{"t":"한 가지 주제만 아주 길게 쓴다","mis":"SO6-2-u3-X22"},{"t":"공부한 내용과 상관없는 이야기로 꾸민다","mis":"SO6-2-u3-X22"},{"t":"나라별 인구수를 모두 외워 적는다","mis":"SO6-2-u3-X23"}],"explanation":["단원 주제가 둘이에요.","골고루 드러나요.","이야기로 엮어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#8','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','그림책 발표회에서 다른 모둠의 발표를 들을 때 관심 있게 살펴볼 점은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"그림책 발표회에서 다른 모둠의 발표를 들을 때 관심 있게 살펴볼 점은 어느 것인가요?","options":[{"t":"내용과 수준이 적절한지, 계획대로 만들었는지","correct":true},{"t":"그림이 몇 장인지만 센다","mis":"SO6-2-u3-X22"},{"t":"글씨 크기만 본다","mis":"SO6-2-u3-X22"},{"t":"발표한 친구의 옷차림을 본다","mis":"SO6-2-u3-X22"}],"explanation":["내용을 봐요.","수준이 맞는지 봐요.","계획대로 했는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#9','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'ox','auto','스토리보드는 역할을 나누어 만들고, 만드는 중간에 단원 내용을 잘 담고 있는지 확인해요.',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"ox","stem":"스토리보드는 역할을 나누어 만들고, 만드는 중간에 단원 내용을 잘 담고 있는지 확인해요.","answer":"O","reason_options":[{"t":"함께 만들면서 처음 계획한 주제에서 벗어나지 않게 하기 때문에","correct":true},{"t":"스토리보드는 혼자서 한 번에 끝내야 하기 때문에","mis":"SO6-2-u3-X22"}],"mis":"SO6-2-u3-X22","explanation":["역할을 나눠요.","중간에 확인해요.","주제를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_basic#10','soc',6,2,'u3','L09','g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',3,'mc','auto','모둠 그림책 계획의 장면 3 다음에 이어질 장면으로 가장 자연스러운 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"모둠 그림책 계획의 장면 3 다음에 이어질 장면으로 가장 자연스러운 것은 어느 것인가요?","options":[{"t":"장면 4 — 장바구니를 들고 시장에 가는 아이","correct":true},{"t":"빼곡한 도시에 사는 사람들(장면 1)을 다시 넣는다","mis":"SO6-2-u3-X22"},{"t":"주제와 관계없는 우주 여행 장면","mis":"SO6-2-u3-X22"},{"t":"인구수 표만 크게 그린 장면","mis":"SO6-2-u3-X23"}],"explanation":["장면 3은 숲이 사라진 문제예요.","다음은 해결하는 실천이에요.","문제 → 실천으로 이어져요."],"asset":{"type":"passage","lines":["독자 — 8~9세 어린이","주제 — 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자","장면 1 — 발달한 도시에 사람들이 빼곡하게 사는 모습","장면 2 — 사람이 드문 사막과 얼음 땅","장면 3 — 베어진 숲에서 갈 곳을 잃은 동물","장면 4 — 장바구니를 들고 시장에 가는 아이"],"title":"모둠 그림책 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#1','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',2,'match','auto','스토리보드의 칸과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"match","stem":"스토리보드의 칸과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"그림 순서","r":"몇 번째 장면인지"},{"l":"그림","r":"장면을 나타낸 스케치"},{"l":"대사","r":"등장인물이 하는 말"}],"mis":"SO6-2-u3-X22","explanation":["순서를 적어요.","스케치를 그려요.","대사는 인물의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#2','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',2,'sa','auto','그림책 계획에서 「지속가능한 미래를 위해 생활 속 작은 일부터 실천하자」처럼 그림책이 전하려는 중심 생각을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"sa","stem":"그림책 계획에서 「지속가능한 미래를 위해 생활 속 작은 일부터 실천하자」처럼 그림책이 전하려는 중심 생각을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["주제"],"explanation":["전하려는 중심 생각이에요.","계획의 처음에 정해요.","주제예요."],"asset":{"type":"passage","lines":["독자 — 8~9세 어린이","주제 — 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자","장면 1 — 발달한 도시에 사람들이 빼곡하게 사는 모습","장면 2 — 사람이 드문 사막과 얼음 땅","장면 3 — 베어진 숲에서 갈 곳을 잃은 동물","장면 4 — 장바구니를 들고 시장에 가는 아이"],"title":"모둠 그림책 계획"},"mis":"SO6-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#3','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','모둠 그림책 계획의 네 장면이 단원 내용을 잘 담았다고 볼 수 있는 까닭은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"모둠 그림책 계획의 네 장면이 단원 내용을 잘 담았다고 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"인구 분포의 특징에서 지구촌 문제와 실천까지 단원의 두 주제를 이야기 흐름으로 이었기 때문에","correct":true},{"t":"장면이 네 개뿐이기 때문에","mis":"SO6-2-u3-X22"},{"t":"인구수 수치를 모두 적었기 때문에","mis":"SO6-2-u3-X23"},{"t":"단원과 상관없는 장면을 넣었기 때문에","mis":"SO6-2-u3-X22"}],"explanation":["1·2는 인구 분포예요.","3은 문제, 4는 실천이에요.","두 주제가 이어져요."],"asset":{"type":"passage","lines":["독자 — 8~9세 어린이","주제 — 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자","장면 1 — 발달한 도시에 사람들이 빼곡하게 사는 모습","장면 2 — 사람이 드문 사막과 얼음 땅","장면 3 — 베어진 숲에서 갈 곳을 잃은 동물","장면 4 — 장바구니를 들고 시장에 가는 아이"],"title":"모둠 그림책 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#4','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','그림책 장면에 넣을 글을 고를 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"그림책 장면에 넣을 글을 고를 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 장면의 그림과 이어지고 앞뒤 이야기 흐름에 맞는 글","correct":true},{"t":"그림과 상관없이 가장 멋있어 보이는 글","mis":"SO6-2-u3-X22"},{"t":"다른 장면에 넣을 글을 미리 넣은 것","mis":"SO6-2-u3-X22"},{"t":"독자가 이해하기 어려운 긴 글","mis":"SO6-2-u3-X22"}],"explanation":["그림과 글이 짝을 이뤄요.","흐름에 맞아야 해요.","독자 수준도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#5','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'ox','auto','그림책의 독자를 바꾸면 같은 주제라도 쓰는 낱말과 문장이 달라질 수 있어요.',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"ox","stem":"그림책의 독자를 바꾸면 같은 주제라도 쓰는 낱말과 문장이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"독자의 수준에 맞게 내용을 구성해야 하기 때문에","correct":true},{"t":"독자가 누구든 똑같이 써야 하기 때문에","mis":"SO6-2-u3-X22"}],"mis":"SO6-2-u3-X22","explanation":["독자 수준이 달라요.","낱말과 문장을 맞춰요.","그래서 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#6','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'error','auto','그림책 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"error","stem":"그림책 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「동생이 읽을 그림책이지만 어려운 낱말을 많이 써야 멋있어.」","correct":true,"mis_target":"SO6-2-u3-X22"},{"t":"세린 — 「장면 차례가 이야기 흐름에 맞는지 살펴보자.」","mis":"SO6-2-u3-X22"},{"t":"지안 — 「인구와 지구촌 주제가 골고루 들어가게 하자.」","mis":"SO6-2-u3-X22"}],"explanation":["독자 수준에 맞춰야 해요.","동생에게는 쉽게 써요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#7','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','그림책 발표회를 마친 뒤 느낀 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"그림책 발표회를 마친 뒤 느낀 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"스토리보드를 만들며 단원에서 공부한 내용을 정리할 수 있었다","correct":true},{"t":"다른 모둠의 그림책은 볼 필요가 없었다","mis":"SO6-2-u3-X22"},{"t":"그림만 예쁘면 내용은 상관없다고 느꼈다","mis":"SO6-2-u3-X22"},{"t":"공부한 내용과 관계없는 활동이었다","mis":"SO6-2-u3-X22"}],"explanation":["공부한 내용을 담았어요.","정리할 수 있었어요.","나눠 보며 배웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#8','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',4,'mc','auto','「세계 인구의 특징」과 「지속가능한 지구촌」을 모두 담은 그림책 줄거리로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"mc","stem":"「세계 인구의 특징」과 「지속가능한 지구촌」을 모두 담은 그림책 줄거리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 흩어져 사는 지구촌에서 사람과 동식물, 자연이 함께 행복하려면 생활 속 작은 실천으로 지속가능한 미래를 만들어야 한다","correct":true},{"t":"우리 반 친구들이 소풍을 다녀온 이야기","mis":"SO6-2-u3-X22"},{"t":"세계 여러 나라의 인구수를 순서대로 나열한 이야기","mis":"SO6-2-u3-X23"},{"t":"우주 탐험을 떠난 로봇 이야기","mis":"SO6-2-u3-X22"}],"explanation":["인구 분포가 담겨요.","지속가능한 미래가 담겨요.","두 주제가 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#9','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',4,'mc','auto','모둠 그림책 계획에 한 장면을 더한다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"mc","stem":"모둠 그림책 계획에 한 장면을 더한다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 나라 사람들이 함께 나무를 심으며 지구를 지키는 장면","correct":true},{"t":"주인공이 놀이공원에서 노는 장면","mis":"SO6-2-u3-X22"},{"t":"나라 이름을 모두 적은 장면","mis":"SO6-2-u3-X23"},{"t":"앞 장면을 그대로 다시 그린 장면","mis":"SO6-2-u3-X22"}],"explanation":["주제와 이어져야 해요.","실천이 넓어지는 장면이에요.","흐름이 자연스러워요."],"asset":{"type":"passage","lines":["독자 — 8~9세 어린이","주제 — 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자","장면 1 — 발달한 도시에 사람들이 빼곡하게 사는 모습","장면 2 — 사람이 드문 사막과 얼음 땅","장면 3 — 베어진 숲에서 갈 곳을 잃은 동물","장면 4 — 장바구니를 들고 시장에 가는 아이"],"title":"모둠 그림책 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_L09_challenge#10','soc',6,2,'u3','L09','g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',4,'essay','teacher','이 단원에서 공부한 내용으로 그림책을 만든다고 생각하고, 독자·주제·줄거리를 쓴 뒤 장면 세 개를 그림 설명과 글로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 내용으로 그림책을 만든다고 생각하고, 독자·주제·줄거리를 쓴 뒤 장면 세 개를 그림 설명과 글로 쓰세요.","answer_guide":{"answer":"예: 독자 — 1학년 동생. 주제 — 지구촌 사람들이 함께 지구를 지키자. 줄거리 — 지구촌 곳곳에는 사람이 많이 사는 곳과 적은 곳이 있지만 모두 같은 지구에 살고, 함께 작은 실천을 하면 지구를 지킬 수 있다. 장면 1 — 사람이 빼곡한 도시와 사람이 드문 얼음 땅(글: 사람이 많은 곳도 있고 적은 곳도 있어요). 장면 2 — 녹는 빙하 위의 북극곰(글: 지구가 더워지고 있어요). 장면 3 — 아이들이 전등을 끄고 장바구니를 드는 모습(글: 우리가 함께 지구를 지켜요).","scoring_points":["독자와 주제를 정했는가","단원 내용이 담긴 줄거리를 썼는가","흐름에 맞는 장면 세 개를 그림 설명과 글로 썼는가"]},"explanation":["독자와 주제를 정해요.","두 주제를 담아요.","흐름에 맞게 장면을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#1','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',1,'mc','auto','누리반 신문 ①에서 점이 빽빽한 곳은 어떤 곳인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"누리반 신문 ①에서 점이 빽빽한 곳은 어떤 곳인가요?","options":[{"t":"인구가 많이 분포하는 곳","correct":true},{"t":"인구가 적게 분포하는 곳","mis":"SO6-2-u3-X03"},{"t":"땅이 높은 곳","mis":"SO6-2-u3-X03"},{"t":"비가 많이 오는 곳","mis":"SO6-2-u3-X03"}],"explanation":["점은 인구를 나타내요.","빽빽하면 많아요.","인구가 많은 곳이에요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#2','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',1,'mc','auto','누리반 신문 ②에서 인구 밀도가 가장 높은 나라는 어디인가요?',ARRAY['SO6-2-u3-X10','SO6-2-u3-X09']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"누리반 신문 ②에서 인구 밀도가 가장 높은 나라는 어디인가요?","options":[{"t":"방글라데시","correct":true},{"t":"캐나다","mis":"SO6-2-u3-X10"},{"t":"우리나라","mis":"SO6-2-u3-X10"},{"t":"세 나라가 같다","mis":"SO6-2-u3-X09"}],"explanation":["수를 견줘요.","1,317이 가장 커요.","방글라데시예요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#3','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C5',1,'mc','auto','인구 피라미드의 맨 아래층은 어떤 연령층을 나타내나요?',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"mc","stem":"인구 피라미드의 맨 아래층은 어떤 연령층을 나타내나요?","options":[{"t":"유소년층","correct":true},{"t":"노년층","mis":"SO6-2-u3-X11"},{"t":"청장년층","mis":"SO6-2-u3-X11"},{"t":"모든 연령층","mis":"SO6-2-u3-X11"}],"explanation":["세로축은 나이예요.","아래가 어려요.","유소년층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#4','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C7',1,'mc','auto','누리반 신문 ⑤에서 다룬 지구촌 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"누리반 신문 ⑤에서 다룬 지구촌 문제는 어느 것인가요?","options":[{"t":"생태계 파괴","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"인구 밀도","mis":"SO6-2-u3-X15"},{"t":"인구 구조","mis":"SO6-2-u3-X15"}],"explanation":["숲이 줄었어요.","동식물이 살 곳을 잃어요.","생태계 파괴예요."],"asset":{"type":"passage","lines":["농사·목축·산업으로 열대 우림이 크게 줄었다.","동식물이 살 곳을 잃고 있다.","탄소를 흡수하던 숲이 줄어 지구 온난화가 빨라질 수 있다."],"title":"누리반 신문 ⑤ 사라지는 숲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#5','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C8',1,'mc','auto','누리반 신문 ④의 투발루에 일어난 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"mc","stem":"누리반 신문 ④의 투발루에 일어난 문제는 어느 것인가요?","options":[{"t":"해수면이 높아져 섬이 물에 잠겼다","correct":true},{"t":"가뭄으로 논밭이 말랐다","mis":"SO6-2-u3-X15"},{"t":"폭설로 길이 막혔다","mis":"SO6-2-u3-X15"},{"t":"사막이 넓어졌다","mis":"SO6-2-u3-X15"}],"explanation":["바닷물이 높아졌어요.","섬이 잠겼어요.","기후변화 때문이에요."],"asset":{"type":"passage","lines":["남태평양의 섬나라 투발루는 해수면이 높아져 섬 두 개가 물에 잠겼다.","주민들은 다른 나라로 옮겨 갈 계획을 세우고 있다.","기자 한마디 — 탄소를 거의 내지 않는 작은 나라가 가장 먼저 피해를 본다."],"title":"누리반 신문 ④ 섬나라 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#6','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C9',1,'mc','auto','누리반 신문 ⑦의 ㉠ 라벨 없는 생수병은 어느 주체의 노력인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"mc","stem":"누리반 신문 ⑦의 ㉠ 라벨 없는 생수병은 어느 주체의 노력인가요?","options":[{"t":"기업","correct":true},{"t":"개인","mis":"SO6-2-u3-X19"},{"t":"국가","mis":"SO6-2-u3-X19"},{"t":"국제기구","mis":"SO6-2-u3-X20"}],"explanation":["회사가 만들었어요.","제품이에요.","기업의 노력이에요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#7','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C10',1,'mc','auto','누리반 신문 ⑦의 ㉢ 국경 없는 의사회는 어떤 단체인가요?',ARRAY['SO6-2-u3-X20','SO6-2-u3-X19']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"mc","stem":"누리반 신문 ⑦의 ㉢ 국경 없는 의사회는 어떤 단체인가요?","options":[{"t":"비정부 기구","correct":true},{"t":"국제기구","mis":"SO6-2-u3-X20"},{"t":"기업","mis":"SO6-2-u3-X19"},{"t":"국가","mis":"SO6-2-u3-X19"}],"explanation":["민간단체예요.","차별 없이 치료해요.","비정부 기구예요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#8','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C11',1,'mc','auto','누리반 신문 ⑧에서 「안 쓰는 전등 끄기」는 어떤 노력인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"mc","stem":"누리반 신문 ⑧에서 「안 쓰는 전등 끄기」는 어떤 노력인가요?","options":[{"t":"빼기(−) 노력","correct":true},{"t":"더하기(+) 노력","mis":"SO6-2-u3-X21"},{"t":"국가의 노력","mis":"SO6-2-u3-X19"},{"t":"기업의 노력","mis":"SO6-2-u3-X19"}],"explanation":["줄이는 일이에요.","에너지를 덜 써요.","빼기 노력이에요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#9','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C1',2,'mc','auto','누리반 신문 ①에서 서부 유럽에 점이 빽빽한 까닭과 가장 관련 깊은 요인은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"mc","stem":"누리반 신문 ①에서 서부 유럽에 점이 빽빽한 까닭과 가장 관련 깊은 요인은 어느 것인가요?","options":[{"t":"산업·교통 같은 인문환경","correct":true},{"t":"매우 적은 강수량","mis":"SO6-2-u3-X03"},{"t":"매우 낮은 기온","mis":"SO6-2-u3-X03"},{"t":"우거진 열대 우림","mis":"SO6-2-u3-X03"}],"explanation":["산업이 발달했어요.","일자리와 교통이 있어요.","인문환경이에요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#10','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C3',2,'mc','auto','나라의 인구수를 바꾸는 요인으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"나라의 인구수를 바꾸는 요인으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"나라 이름을 바꾸는 일","correct":true},{"t":"출생","mis":"SO6-2-u3-X08"},{"t":"사망","mis":"SO6-2-u3-X08"},{"t":"인구의 이동","mis":"SO6-2-u3-X08"}],"explanation":["태어나고 사망해요.","오가고 환경이 바뀌어요.","이름은 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#11','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',2,'mc','auto','누리반 신문 ②에서 캐나다의 인구 밀도가 낮은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10','SO6-2-u3-X09']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"누리반 신문 ②에서 캐나다의 인구 밀도가 낮은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"냉대 기후가 넓어 농사지을 땅이 적기 때문에","correct":true},{"t":"넓은 평야에서 벼농사를 짓기 때문에","mis":"SO6-2-u3-X10"},{"t":"땅이 매우 좁기 때문에","mis":"SO6-2-u3-X09"},{"t":"인구가 매우 많기 때문에","mis":"SO6-2-u3-X09"}],"explanation":["캐나다는 추운 곳이 많아요.","농사지을 땅이 적어요.","밀도가 낮아요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#12','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C5',2,'mc','auto','누리반 신문 ③에서 누리국의 인구 구조로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"누리반 신문 ③에서 누리국의 인구 구조로 알맞은 것은 어느 것인가요?","options":[{"t":"노년층 비율이 높고 유소년층 비율이 낮다","correct":true},{"t":"유소년층 비율이 높고 노년층 비율이 낮다","mis":"SO6-2-u3-X12"},{"t":"세 연령층 비율이 같다","mis":"SO6-2-u3-X11"},{"t":"청장년층이 하나도 없다","mis":"SO6-2-u3-X11"}],"explanation":["위층이 넓어요.","평균 수명이 길어요.","노년층이 많아요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#13','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C6',2,'mc','auto','누리반 신문 ③의 가람국에 더 많이 필요할 시설은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"누리반 신문 ③의 가람국에 더 많이 필요할 시설은 어느 것인가요?","options":[{"t":"유치원과 학교","correct":true},{"t":"요양원","mis":"SO6-2-u3-X13"},{"t":"노인 복지 센터","mis":"SO6-2-u3-X13"},{"t":"경로당","mis":"SO6-2-u3-X13"}],"explanation":["어린이가 많아요.","배울 곳이 필요해요.","유치원과 학교예요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#14','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C7',2,'mc','auto','누리반 신문 ⑤에서 열대 우림이 줄어든 원인으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"누리반 신문 ⑤에서 열대 우림이 줄어든 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"농사·목축·산업 같은 인간 활동","correct":true},{"t":"지진","mis":"SO6-2-u3-X15"},{"t":"화산","mis":"SO6-2-u3-X15"},{"t":"운석","mis":"SO6-2-u3-X15"}],"explanation":["사람이 숲을 베었어요.","농사와 목축이에요.","인간 활동이 원인이에요."],"asset":{"type":"passage","lines":["농사·목축·산업으로 열대 우림이 크게 줄었다.","동식물이 살 곳을 잃고 있다.","탄소를 흡수하던 숲이 줄어 지구 온난화가 빨라질 수 있다."],"title":"누리반 신문 ⑤ 사라지는 숲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#15','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C9',2,'mc','auto','누리반 신문 ⑦의 ㉠~㉣을 통해 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"누리반 신문 ⑦의 ㉠~㉣을 통해 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기업·국가·비정부 기구·국제기구가 저마다 지구촌 문제 해결에 힘쓴다","correct":true},{"t":"국가만 지구촌 문제를 해결한다","mis":"SO6-2-u3-X19"},{"t":"기업은 지구촌 문제와 관계없다","mis":"SO6-2-u3-X19"},{"t":"국제기구와 비정부 기구는 같은 단체다","mis":"SO6-2-u3-X20"}],"explanation":["여러 주체가 나와요.","저마다 할 일을 해요.","함께 힘써요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#16','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C11',2,'mc','auto','누리반 신문 ⑧의 실천 릴레이에서 다음 친구에게 바통을 넘기기 전에 하는 일은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"누리반 신문 ⑧의 실천 릴레이에서 다음 친구에게 바통을 넘기기 전에 하는 일은 어느 것인가요?","options":[{"t":"실천하는 모습을 찍고 실천한 내용을 기록한다","correct":true},{"t":"실천하지 않고 바로 넘긴다","mis":"SO6-2-u3-X21"},{"t":"다른 친구의 사진을 대신 올린다","mis":"SO6-2-u3-X21"},{"t":"기록만 하고 실천은 하지 않는다","mis":"SO6-2-u3-X21"}],"explanation":["먼저 실천해요.","사진을 찍고 기록해요.","그다음 넘겨요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#17','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',3,'mc','auto','누리반 신문 ①에서 북반구와 남반구, 중위도와 고위도를 함께 생각할 때 가장 알맞은 설명은 어느 것인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X02']::text[],false,'{"seq":17,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"누리반 신문 ①에서 북반구와 남반구, 중위도와 고위도를 함께 생각할 때 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"세계 인구의 대부분은 육지가 많은 북반구의 온화한 중위도에 산다","correct":true},{"t":"세계 인구의 대부분은 남반구의 고위도에 산다","mis":"SO6-2-u3-X04"},{"t":"세계 인구는 반구와 위도에 상관없이 고르다","mis":"SO6-2-u3-X02"},{"t":"추운 고위도일수록 인구가 많다","mis":"SO6-2-u3-X04"}],"explanation":["점이 북반구에 몰려요.","중위도가 온화해요.","그곳에 많이 살아요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#18','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',3,'mc','auto','누리반 신문 ②의 세 나라를 보고 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X10']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"누리반 신문 ②의 세 나라를 보고 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"인구 밀도는 면적에 비해 인구수가 얼마나 많은지에 따라 다르고, 기후·지형 같은 환경의 영향을 받는다","correct":true},{"t":"땅이 넓을수록 인구 밀도가 높다","mis":"SO6-2-u3-X09"},{"t":"세 나라의 인구 밀도는 거의 같다","mis":"SO6-2-u3-X09"},{"t":"인구 밀도는 환경과 관계없다","mis":"SO6-2-u3-X10"}],"explanation":["면적에 비해 사람 수예요.","평야와 냉대 기후가 달라요.","환경이 영향을 줘요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#19','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C6',3,'mc','auto','누리반 신문 ③의 누리국에서 앞으로 생길 일로 가장 알맞게 예상한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13','SO6-2-u3-X12']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"누리반 신문 ③의 누리국에서 앞으로 생길 일로 가장 알맞게 예상한 것은 어느 것인가요?","options":[{"t":"일할 청장년층이 점점 줄고 노인을 돌볼 시설과 사람이 더 필요해진다","correct":true},{"t":"학교가 모자라 새 학교를 많이 지어야 한다","mis":"SO6-2-u3-X13"},{"t":"노년층이 곧 모두 사라진다","mis":"SO6-2-u3-X12"},{"t":"인구 구조는 앞으로 바뀌지 않는다","mis":"SO6-2-u3-X13"}],"explanation":["아기가 적게 태어나요.","노인이 많아져요.","돌봄이 더 필요해요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#20','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C8',3,'mc','auto','누리반 신문 ④와 ⑤를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"누리반 신문 ④와 ⑤를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"숲이 사라져 탄소 흡수가 줄면 기후변화가 커져 투발루 같은 먼 나라가 피해를 볼 수 있다","correct":true},{"t":"숲이 사라지는 일과 섬이 잠기는 일은 서로 관계없다","mis":"SO6-2-u3-X16"},{"t":"투발루가 숲을 베어서 섬이 잠겼다","mis":"SO6-2-u3-X15"},{"t":"숲이 줄면 해수면이 낮아진다","mis":"SO6-2-u3-X15"}],"explanation":["숲은 탄소를 흡수해요.","기후변화가 커져요.","먼 나라도 피해를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#21','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C9',3,'mc','auto','누리반 신문 ⑥의 「필요한 옷만 사고 오래 입자」는 어떤 노력과 이어지나요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"누리반 신문 ⑥의 「필요한 옷만 사고 오래 입자」는 어떤 노력과 이어지나요?","options":[{"t":"자원을 아끼고 쓰레기를 줄이는 개인의 노력","correct":true},{"t":"기후변화 협약에 가입하는 국가의 노력","mis":"SO6-2-u3-X19"},{"t":"친환경 소재를 개발하는 기업의 노력","mis":"SO6-2-u3-X19"},{"t":"난민을 돕는 국제기구의 노력","mis":"SO6-2-u3-X20"}],"explanation":["우리 반의 다짐이에요.","생활 속 실천이에요.","개인의 노력이에요."],"asset":{"type":"passage","lines":["면 티셔츠 한 벌에 물 약 2,700 L가 든다.","쉽게 사고 쉽게 버린 옷이 환경을 오염한다.","우리 반 다짐 — 필요한 옷만 사고 오래 입자."],"title":"누리반 신문 ⑥ 옷 한 벌의 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#22','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C11',3,'mc','auto','누리반 신문 ⑧의 실천 릴레이가 지구촌 문제 해결에 의미 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X16']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"누리반 신문 ⑧의 실천 릴레이가 지구촌 문제 해결에 의미 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 사람의 작은 실천이 다음 사람으로 이어져 함께하는 실천으로 넓어지기 때문에","correct":true},{"t":"한 사람만 실천하면 되기 때문에","mis":"SO6-2-u3-X21"},{"t":"사진을 찍는 것만으로 문제가 해결되기 때문에","mis":"SO6-2-u3-X21"},{"t":"지구촌 문제는 우리와 관계없기 때문에","mis":"SO6-2-u3-X16"}],"explanation":["바통이 이어져요.","실천이 넓어져요.","함께하는 힘이에요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#23','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',4,'mc','auto','「지구촌 사람들」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X02','SO6-2-u3-X23','SO6-2-u3-X06']::text[],false,'{"seq":23,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"mc","stem":"「지구촌 사람들」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"세계 인구는 환경에 따라 고르지 않게 분포하고 나라마다 인구수·밀도·구조가 다르며, 지구촌 문제는 모두의 문제라 여러 주체와 세계시민이 함께 해결한다","correct":true},{"t":"세계 인구는 고르게 퍼져 있고 지구촌 문제는 국가만 해결한다","mis":"SO6-2-u3-X02"},{"t":"인구 공부는 나라별 수치를 외우는 것이고 지구촌 문제는 먼 나라 일이다","mis":"SO6-2-u3-X23"},{"t":"땅이 넓은 나라일수록 인구가 많고 개인은 할 일이 없다","mis":"SO6-2-u3-X06"}],"explanation":["인구 분포와 특징이에요.","지구촌 문제와 노력이에요.","세계시민이 함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#24','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',4,'essay','teacher','누리반 신문 ①을 보고 세계의 인구 분포 특징을 쓰고, 인구가 많은 곳 한 곳과 적은 곳 한 곳을 골라 그 까닭을 자연환경이나 인문환경과 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"essay","stem":"누리반 신문 ①을 보고 세계의 인구 분포 특징을 쓰고, 인구가 많은 곳 한 곳과 적은 곳 한 곳을 골라 그 까닭을 자연환경이나 인문환경과 이어 쓰세요.","answer_guide":{"answer":"예: 세계의 인구는 고르게 분포하지 않고 북반구, 기후가 온화한 중위도, 평야와 해안, 일자리가 풍부한 곳에 많이 모여 산다. 서부 유럽은 산업이 발달해 일자리가 풍부하고 교통이 편리한 인문환경 덕분에 인구가 많다. 알래스카는 기온이 매우 낮아 생활하기 어려운 자연환경 때문에 인구가 적다.","scoring_points":["세계 인구 분포의 특징을 썼는가","인구가 많은 곳과 까닭을 썼는가","인구가 적은 곳과 까닭을 썼는가"]},"explanation":["고르지 않아요.","많은 곳의 까닭을 써요.","적은 곳의 까닭을 써요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_a#25','soc',6,2,'u3','','g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C7',4,'essay','teacher','누리반 신문 ⑤와 ⑥에 나온 지구촌 문제를 각각 쓰고, 두 문제를 줄이기 위해 내가 할 수 있는 일을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"essay","stem":"누리반 신문 ⑤와 ⑥에 나온 지구촌 문제를 각각 쓰고, 두 문제를 줄이기 위해 내가 할 수 있는 일을 하나씩 쓰세요.","answer_guide":{"answer":"예: ⑤는 농사·목축·산업으로 열대 우림이 줄어 동식물이 살 곳을 잃는 생태계 파괴 문제이고, 탄소 흡수가 줄어 기후변화도 커질 수 있다. ⑥은 옷을 만드는 데 많은 물이 들고 버린 옷이 환경을 오염하는 자원 낭비와 오염 문제이다. 나는 종이를 아껴 쓰고 재생 종이를 쓰며, 필요한 옷만 사서 오래 입고 작아진 옷은 물려주겠다.","scoring_points":["⑤의 지구촌 문제를 썼는가","⑥의 지구촌 문제를 썼는가","두 문제를 줄일 실천을 하나씩 썼는가"]},"explanation":["숲의 문제예요.","옷의 문제예요.","내가 할 일을 써요."],"asset":{"type":"passage","lines":["면 티셔츠 한 벌에 물 약 2,700 L가 든다.","쉽게 사고 쉽게 버린 옷이 환경을 오염한다.","우리 반 다짐 — 필요한 옷만 사고 오래 입자."],"title":"누리반 신문 ⑥ 옷 한 벌의 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#1','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C2',1,'mc','auto','누리반 신문 ①에서 점이 드문 곳은 어디인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"누리반 신문 ①에서 점이 드문 곳은 어디인가요?","options":[{"t":"사하라 사막","correct":true},{"t":"서부 유럽","mis":"SO6-2-u3-X03"},{"t":"동아시아","mis":"SO6-2-u3-X03"},{"t":"남부 아시아","mis":"SO6-2-u3-X03"}],"explanation":["사막은 물이 적어요.","사람이 살기 어려워요.","점이 드물어요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#2','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C4',1,'mc','auto','인구 밀도는 무엇을 나타내나요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X09','SO6-2-u3-X11']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"인구 밀도는 무엇을 나타내나요?","options":[{"t":"인구가 모여 있는 정도","correct":true},{"t":"인구가 늘어나는 비율","mis":"SO6-2-u3-X08"},{"t":"나라의 땅 넓이","mis":"SO6-2-u3-X09"},{"t":"나이별 인구의 짜임새","mis":"SO6-2-u3-X11"}],"explanation":["1 km² 안의 사람 수예요.","빽빽한 정도예요.","모여 있는 정도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#3','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',1,'mc','auto','누리반 신문 ③에서 아래층이 넓은 피라미드를 가진 나라는 어디인가요?',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"mc","stem":"누리반 신문 ③에서 아래층이 넓은 피라미드를 가진 나라는 어디인가요?","options":[{"t":"가람국","correct":true},{"t":"누리국","mis":"SO6-2-u3-X11"},{"t":"두 나라 모두","mis":"SO6-2-u3-X11"},{"t":"어느 나라도 아니다","mis":"SO6-2-u3-X11"}],"explanation":["아래층이 넓어요.","아기가 많이 태어나요.","가람국이에요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#4','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C7',1,'mc','auto','전쟁·재난으로 살던 곳을 떠나는 사람이 늘어나는 지구촌 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"전쟁·재난으로 살던 곳을 떠나는 사람이 늘어나는 지구촌 문제는 어느 것인가요?","options":[{"t":"난민 문제","correct":true},{"t":"자원 고갈 문제","mis":"SO6-2-u3-X15"},{"t":"생태계 파괴 문제","mis":"SO6-2-u3-X15"},{"t":"인구 밀도 문제","mis":"SO6-2-u3-X15"}],"explanation":["살던 곳을 떠나요.","전쟁 때문이에요.","난민 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#5','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C8',1,'mc','auto','지구촌 문제를 조사한 붙임쪽지에 들어갈 내용으로 알맞게 묶인 것은 어느 것인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"mc","stem":"지구촌 문제를 조사한 붙임쪽지에 들어갈 내용으로 알맞게 묶인 것은 어느 것인가요?","options":[{"t":"지역 · 문제 상황 · 문제 원인","correct":true},{"t":"지역 · 국기 · 수도","mis":"SO6-2-u3-X23"},{"t":"내 이름 · 날짜 · 날씨","mis":"SO6-2-u3-X17"},{"t":"인구수 · 면적 · 밀도","mis":"SO6-2-u3-X17"}],"explanation":["어디에서예요.","무슨 일이예요.","왜예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#6','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C9',1,'mc','auto','누리반 신문 ⑦의 ㉡ 탄소를 줄일 목표를 세계에 약속한 것은 어느 주체의 노력인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"mc","stem":"누리반 신문 ⑦의 ㉡ 탄소를 줄일 목표를 세계에 약속한 것은 어느 주체의 노력인가요?","options":[{"t":"국가","correct":true},{"t":"개인","mis":"SO6-2-u3-X19"},{"t":"기업","mis":"SO6-2-u3-X19"},{"t":"비정부 기구","mis":"SO6-2-u3-X20"}],"explanation":["우리나라가 약속했어요.","나라의 일이에요.","국가의 노력이에요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#7','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C10',1,'mc','auto','누리반 신문 ⑦의 ㉣ 국제 연합 아동 기금은 어떤 단체인가요?',ARRAY['SO6-2-u3-X20','SO6-2-u3-X19']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"mc","stem":"누리반 신문 ⑦의 ㉣ 국제 연합 아동 기금은 어떤 단체인가요?","options":[{"t":"국제기구","correct":true},{"t":"비정부 기구","mis":"SO6-2-u3-X20"},{"t":"기업","mis":"SO6-2-u3-X19"},{"t":"개인","mis":"SO6-2-u3-X19"}],"explanation":["국제 연합의 기구예요.","어린이를 도와요.","국제기구예요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#8','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C11',1,'mc','auto','지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람은 누구인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X21','SO6-2-u3-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"mc","stem":"지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람은 누구인가요?","options":[{"t":"세계시민","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"예보 분석관","mis":"SO6-2-u3-X21"},{"t":"비정부 기구","mis":"SO6-2-u3-X20"}],"explanation":["지구촌의 한 사람이에요.","책임 있게 행동해요.","세계시민이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#9','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C1',2,'mc','auto','인구 분포에 영향을 주는 인문환경 요인끼리 묶인 것은 어느 것인가요?',ARRAY['SO6-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"mc","stem":"인구 분포에 영향을 주는 인문환경 요인끼리 묶인 것은 어느 것인가요?","options":[{"t":"산업·교통·문화","correct":true},{"t":"기온·강수량·지형","mis":"SO6-2-u3-X01"},{"t":"지형·산업·기온","mis":"SO6-2-u3-X01"},{"t":"강수량·교통·지형","mis":"SO6-2-u3-X01"}],"explanation":["사람이 만든 환경이에요.","산업·교통·문화예요.","인문환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#10','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C3',2,'mc','auto','누리반 신문 ④의 투발루 주민들이 다른 나라로 옮겨 가면 투발루의 인구수는 어떻게 될까요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"누리반 신문 ④의 투발루 주민들이 다른 나라로 옮겨 가면 투발루의 인구수는 어떻게 될까요?","options":[{"t":"줄어든다","correct":true},{"t":"늘어난다","mis":"SO6-2-u3-X08"},{"t":"그대로이다","mis":"SO6-2-u3-X08"},{"t":"면적이 늘어난다","mis":"SO6-2-u3-X06"}],"explanation":["사람이 떠나요.","인구의 이동이에요.","인구수가 줄어요."],"asset":{"type":"passage","lines":["남태평양의 섬나라 투발루는 해수면이 높아져 섬 두 개가 물에 잠겼다.","주민들은 다른 나라로 옮겨 갈 계획을 세우고 있다.","기자 한마디 — 탄소를 거의 내지 않는 작은 나라가 가장 먼저 피해를 본다."],"title":"누리반 신문 ④ 섬나라 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#11','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C4',2,'mc','auto','누리반 신문 ②로 알 수 있는 우리나라 인구 밀도의 특징은 어느 것인가요?',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"누리반 신문 ②로 알 수 있는 우리나라 인구 밀도의 특징은 어느 것인가요?","options":[{"t":"캐나다보다 훨씬 높고 매우 높은 편이다","correct":true},{"t":"캐나다보다 낮다","mis":"SO6-2-u3-X10"},{"t":"세 나라 가운데 가장 낮다","mis":"SO6-2-u3-X10"},{"t":"방글라데시보다 높다","mis":"SO6-2-u3-X10"}],"explanation":["우리나라는 약 515명이에요.","캐나다는 약 4명이에요.","매우 높은 편이에요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#12','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',2,'mc','auto','출생률과 사망률이 높고 평균 수명이 짧은 나라의 인구 피라미드는 어떤 모양인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"출생률과 사망률이 높고 평균 수명이 짧은 나라의 인구 피라미드는 어떤 모양인가요?","options":[{"t":"아래층이 넓고 위로 갈수록 좁다","correct":true},{"t":"아래층이 좁고 위층이 넓다","mis":"SO6-2-u3-X12"},{"t":"모든 층의 폭이 같다","mis":"SO6-2-u3-X11"},{"t":"가운데만 텅 비어 있다","mis":"SO6-2-u3-X11"}],"explanation":["아기가 많이 태어나요.","오래 살지 못해요.","아래가 넓어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#13','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C6',2,'mc','auto','누리반 신문 ③의 누리국에 더 많이 필요할 시설은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"누리반 신문 ③의 누리국에 더 많이 필요할 시설은 어느 것인가요?","options":[{"t":"요양원과 노인 복지 센터","correct":true},{"t":"유치원","mis":"SO6-2-u3-X13"},{"t":"초등학교","mis":"SO6-2-u3-X13"},{"t":"어린이 놀이터","mis":"SO6-2-u3-X13"}],"explanation":["노인이 많아요.","돌봄 시설이 필요해요.","요양원·복지 센터예요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#14','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C7',2,'mc','auto','누리반 친구들이 정리한 지구촌 시대의 모습 가운데 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"누리반 친구들이 정리한 지구촌 시대의 모습 가운데 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 나라의 문제가 다른 나라에 영향을 미칠 수 있다","correct":true},{"t":"먼 곳 소식을 빨리 들을 수 있다","mis":"SO6-2-u3-X14"},{"t":"여러 나라 문화를 즐길 수 있다","mis":"SO6-2-u3-X14"},{"t":"다양한 정보를 얻을 수 있다","mis":"SO6-2-u3-X14"}],"explanation":["좋은 점과 문제점을 가려요.","문제가 퍼질 수 있어요.","문제점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#15','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C10',2,'mc','auto','국제기구와 비정부 기구를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"mc","stem":"국제기구와 비정부 기구를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"국제기구 — 국제 연합 / 비정부 기구 — 세계 자연 기금","correct":true},{"t":"국제기구 — 그린피스 / 비정부 기구 — 국제 연합","mis":"SO6-2-u3-X20"},{"t":"국제기구 — 국경 없는 의사회 / 비정부 기구 — 국제 연합 아동 기금","mis":"SO6-2-u3-X20"},{"t":"둘 다 국제기구 — 그린피스와 세계 자연 기금","mis":"SO6-2-u3-X20"}],"explanation":["국제 연합은 나라들의 기구예요.","세계 자연 기금은 민간이에요.","구분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#16','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C12',2,'mc','auto','누리반 신문 ⑧처럼 1학년 동생들에게 읽어 줄 그림책을 만들 때 알맞은 방법은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"누리반 신문 ⑧처럼 1학년 동생들에게 읽어 줄 그림책을 만들 때 알맞은 방법은 어느 것인가요?","options":[{"t":"쉬운 낱말과 짧은 문장으로 이야기 흐름이 잘 드러나게 쓴다","correct":true},{"t":"어려운 낱말을 많이 넣어 멋있게 쓴다","mis":"SO6-2-u3-X22"},{"t":"통계 수치를 빠짐없이 적는다","mis":"SO6-2-u3-X23"},{"t":"장면 차례를 아무렇게나 놓는다","mis":"SO6-2-u3-X22"}],"explanation":["독자는 1학년이에요.","쉽게 써요.","흐름도 살려요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#17','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C1',3,'mc','auto','누리반 신문 ①에서 점이 드문 세 곳의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":17,"concept":"SO6-2-u3-C1","difficulty":3,"kind":"mc","stem":"누리반 신문 ①에서 점이 드문 세 곳의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연환경이 사람이 생활하기에 불리하다","correct":true},{"t":"산업이 매우 발달했다","mis":"SO6-2-u3-X03"},{"t":"교통이 매우 편리하다","mis":"SO6-2-u3-X03"},{"t":"기후가 온화한 평야다","mis":"SO6-2-u3-X03"}],"explanation":["사막은 물이 적어요.","알래스카는 추워요.","열대 우림은 우거져 있어요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#18','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C3',3,'mc','auto','인구가 매우 많은 인도와 면적이 넓은 캐나다를 견줄 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X23','SO6-2-u3-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"인구가 매우 많은 인도와 면적이 넓은 캐나다를 견줄 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"면적이 넓다고 인구수가 많은 것이 아니라 자연환경과 인문환경이 인구수에 영향을 준다","correct":true},{"t":"면적이 넓은 나라는 언제나 인구수가 가장 많다","mis":"SO6-2-u3-X06"},{"t":"인구수는 나라 이름으로 정해진다","mis":"SO6-2-u3-X23"},{"t":"두 나라의 인구수는 같다","mis":"SO6-2-u3-X07"}],"explanation":["넓이와 인구수는 달라요.","환경을 봐요.","여러 요인이 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#19','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',3,'mc','auto','누리반 신문 ③의 두 나라 인구 피라미드 모양이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X11']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"mc","stem":"누리반 신문 ③의 두 나라 인구 피라미드 모양이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 나라의 출생률과 평균 수명이 다르기 때문에","correct":true},{"t":"두 나라의 면적이 다르기 때문에","mis":"SO6-2-u3-X09"},{"t":"두 나라의 국기가 다르기 때문에","mis":"SO6-2-u3-X11"},{"t":"두 나라의 수도가 다르기 때문에","mis":"SO6-2-u3-X11"}],"explanation":["가람국은 많이 태어나요.","누리국은 오래 살아요.","그래서 모양이 달라요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#20','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C8',3,'mc','auto','누리반 신문 ④의 내용을 붙임쪽지에 정리할 때 「문제 원인」 칸에 쓸 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"누리반 신문 ④의 내용을 붙임쪽지에 정리할 때 「문제 원인」 칸에 쓸 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"탄소 배출로 지구 온도가 올라 해수면이 높아짐","correct":true},{"t":"남태평양의 섬나라 투발루","mis":"SO6-2-u3-X17"},{"t":"섬 두 개가 물에 잠김","mis":"SO6-2-u3-X17"},{"t":"주민들이 이주를 계획함","mis":"SO6-2-u3-X17"}],"explanation":["지역과 상황은 따로 써요.","원인은 왜 생겼는지예요.","해수면 상승의 까닭이에요."],"asset":{"type":"passage","lines":["남태평양의 섬나라 투발루는 해수면이 높아져 섬 두 개가 물에 잠겼다.","주민들은 다른 나라로 옮겨 갈 계획을 세우고 있다.","기자 한마디 — 탄소를 거의 내지 않는 작은 나라가 가장 먼저 피해를 본다."],"title":"누리반 신문 ④ 섬나라 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#21','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C10',3,'mc','auto','전쟁 지역에서 다친 사람과 굶주린 어린이를 함께 도우려면 어떤 단체들이 힘을 모을 수 있을까요?',ARRAY['SO6-2-u3-X20','SO6-2-u3-X19']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"mc","stem":"전쟁 지역에서 다친 사람과 굶주린 어린이를 함께 도우려면 어떤 단체들이 힘을 모을 수 있을까요?","options":[{"t":"국경 없는 의사회와 국제 연합 아동 기금","correct":true},{"t":"그린피스와 세계 자연 기금","mis":"SO6-2-u3-X20"},{"t":"기업과 개인만","mis":"SO6-2-u3-X19"},{"t":"국제 연합 난민 기구만","mis":"SO6-2-u3-X20"}],"explanation":["의료가 필요해요.","어린이 지원도 필요해요.","두 단체가 맞아요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#22','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C12',3,'mc','auto','누리반 신문 ①~⑧로 그림책을 만든다면 장면 차례로 가장 자연스러운 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"누리반 신문 ①~⑧로 그림책을 만든다면 장면 차례로 가장 자연스러운 것은 어느 것인가요?","options":[{"t":"사람이 모여 사는 곳과 드문 곳 → 숲이 사라지고 섬이 잠기는 문제 → 여러 주체의 노력 → 우리 반의 실천","correct":true},{"t":"우리 반의 실천 → 인구 지도 → 섬이 잠김 → 노력 모음","mis":"SO6-2-u3-X22"},{"t":"노력 모음 → 노력 모음 → 노력 모음 → 노력 모음","mis":"SO6-2-u3-X22"},{"t":"인구수 표 → 면적 표 → 밀도 표 → 끝","mis":"SO6-2-u3-X23"}],"explanation":["인구에서 시작해요.","문제와 노력을 이어요.","실천으로 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#23','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',4,'mc','auto','누리반 신문 ②와 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X11','SO6-2-u3-X12','SO6-2-u3-X09']::text[],false,'{"seq":23,"concept":"SO6-2-u3-C5","difficulty":4,"kind":"mc","stem":"누리반 신문 ②와 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라마다 환경과 출생률·평균 수명이 달라 인구 밀도와 인구 구조가 다르게 나타난다","correct":true},{"t":"모든 나라의 인구 밀도와 인구 구조는 같다","mis":"SO6-2-u3-X11"},{"t":"인구 밀도가 높은 나라는 모두 노년층이 많다","mis":"SO6-2-u3-X12"},{"t":"인구 구조는 면적으로만 정해진다","mis":"SO6-2-u3-X09"}],"explanation":["밀도는 환경이 영향을 줘요.","구조는 출생률·수명이 영향을 줘요.","나라마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#24','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C4',4,'essay','teacher','누리반 신문 ②를 보고 세 나라의 인구 밀도를 견주어 쓰고, 「땅이 넓다고 사람이 많이 사는 것은 아니다」라는 말이 맞는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"essay","stem":"누리반 신문 ②를 보고 세 나라의 인구 밀도를 견주어 쓰고, 「땅이 넓다고 사람이 많이 사는 것은 아니다」라는 말이 맞는 까닭을 쓰세요.","answer_guide":{"answer":"예: 방글라데시는 약 1,317명/km²로 가장 높고, 우리나라는 약 515명/km²로 높은 편이며, 캐나다는 약 4명/km²로 매우 낮다. 캐나다는 땅이 넓지만 냉대 기후가 넓게 나타나 농사지을 땅이 적어 사람이 적게 산다. 그래서 땅이 넓다고 사람이 많이 사는 것이 아니라 기후와 지형 같은 환경이 인구에 영향을 준다.","scoring_points":["세 나라의 인구 밀도를 견주었는가","캐나다의 예로 까닭을 썼는가","환경이 영향을 준다는 점을 썼는가"]},"explanation":["세 수를 견줘요.","캐나다가 예예요.","환경을 이어 써요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_b#25','soc',6,2,'u3','','g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C9',4,'essay','teacher','누리반 신문 ⑦의 ㉠~㉣이 각각 어느 주체의 노력인지 쓰고, 여러 주체의 노력이 함께 필요한 까닭을 지속가능한 미래의 뜻과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u3-C9","difficulty":4,"kind":"essay","stem":"누리반 신문 ⑦의 ㉠~㉣이 각각 어느 주체의 노력인지 쓰고, 여러 주체의 노력이 함께 필요한 까닭을 지속가능한 미래의 뜻과 이어 쓰세요.","answer_guide":{"answer":"예: ㉠은 기업, ㉡은 국가, ㉢은 비정부 기구, ㉣은 국제기구의 노력이다. 지속가능한 미래는 오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어지는데, 지구촌 문제는 크고 서로 이어져 있어 한 주체만으로는 해결할 수 없으므로 여러 주체가 힘을 모아야 한다.","scoring_points":["네 노력의 주체를 바르게 썼는가","지속가능한 미래의 뜻을 썼는가","함께 노력해야 하는 까닭을 썼는가"]},"explanation":["주체를 가려요.","미래 세대에 물려줘요.","모두 힘을 모아요."],"asset":{"type":"passage","lines":["㉠ 한 회사가 라벨 없는 생수병을 내놓았다.","㉡ 우리나라가 탄소를 줄일 목표를 세계에 약속했다.","㉢ 국경 없는 의사회가 전쟁 지역 사람들을 치료했다.","㉣ 국제 연합 아동 기금이 어린이에게 식량과 교육을 보냈다."],"title":"누리반 신문 ⑦ 노력 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#1','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C2',1,'sa','auto','누리반 신문 ①에서 대부분의 점이 몰려 있는 반구는 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"sa","stem":"누리반 신문 ①에서 대부분의 점이 몰려 있는 반구는 어디인가요? 세 글자로 쓰세요.","answer":["북반구"],"explanation":["적도 위쪽이에요.","육지가 많아요.","북반구예요."],"asset":{"type":"passage","lines":["우리 반이 세계의 인구 분포 지도를 살펴보았다.","점이 빽빽한 곳 — 동아시아와 남부 아시아, 서부 유럽","점이 드문 곳 — 사하라 사막, 알래스카, 열대 우림","대부분의 점은 적도 위쪽 북반구에 몰려 있었다."],"title":"누리반 신문 ① 인구 지도 특집"},"mis":"SO6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#2','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C4',1,'sa','auto','1 km²처럼 일정한 면적 안에 사는 인구수를 무엇이라고 하나요? (인구 □□)','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"sa","stem":"1 km²처럼 일정한 면적 안에 사는 인구수를 무엇이라고 하나요? (인구 □□)","answer":["밀도"],"explanation":["빽빽한 정도예요.","면적과 인구수를 봐요.","인구 밀도예요."],"mis":"SO6-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#3','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C5',1,'sa','auto','15~64세 인구를 무엇이라고 하나요? (□□□층)','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"sa","stem":"15~64세 인구를 무엇이라고 하나요? (□□□층)","answer":["청장년"],"explanation":["일하는 나이예요.","가운데 층이에요.","청장년층이에요."],"mis":"SO6-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#4','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C7',1,'sa','auto','교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습을 세 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"sa","stem":"교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습을 세 글자로 무엇이라고 하나요?","answer":["지구촌"],"explanation":["하나의 마을 같아요.","가까워졌어요.","지구촌이에요."],"mis":"SO6-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#5','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C8',1,'sa','auto','지구촌 문제를 조사할 때 자료가 어디에서 나왔는지 확인하는 것을 무엇이라고 하나요? (□□ 확인)','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"sa","stem":"지구촌 문제를 조사할 때 자료가 어디에서 나왔는지 확인하는 것을 무엇이라고 하나요? (□□ 확인)","answer":["출처"],"explanation":["자료가 나온 곳이에요.","믿을 만한지 봐요.","출처 확인이에요."],"mis":"SO6-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#6','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',1,'sa','auto','생산할 때 자원과 에너지를 적게 써 오염 물질을 줄인 제품을 무엇이라고 하나요? (□□ 제품)','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"sa","stem":"생산할 때 자원과 에너지를 적게 써 오염 물질을 줄인 제품을 무엇이라고 하나요? (□□ 제품)","answer":["녹색"],"explanation":["환경을 생각한 제품이에요.","오염을 줄여요.","녹색 제품이에요."],"mis":"SO6-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#7','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C10',1,'sa','auto','환경을 연구하고 해양 생태계를 보호하는 활동을 하는 비정부 기구를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"sa","stem":"환경을 연구하고 해양 생태계를 보호하는 활동을 하는 비정부 기구를 쓰세요.","answer":["그린피스"],"explanation":["환경 단체예요.","바다 생태계를 지켜요.","그린피스예요."],"mis":"SO6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#8','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',1,'sa','auto','누리반 신문 ⑧의 실천 릴레이에서 사진을 찍고 기록한 뒤 다음 친구에게 넘긴 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"sa","stem":"누리반 신문 ⑧의 실천 릴레이에서 사진을 찍고 기록한 뒤 다음 친구에게 넘긴 것은 무엇인가요? 두 글자로 쓰세요.","answer":["바통"],"explanation":["이어 달리기 같아요.","다음 친구에게 넘겨요.","바통이에요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"},"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#9','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C1',2,'ox','auto','옛날에는 기후가 온화하고 평야나 해안처럼 자연환경이 유리한 곳에 주로 모여 살았어요.',ARRAY['SO6-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"ox","stem":"옛날에는 기후가 온화하고 평야나 해안처럼 자연환경이 유리한 곳에 주로 모여 살았어요.","answer":"O","reason_options":[{"t":"농사짓고 생활하기 좋은 자연환경이 중요했기 때문에","correct":true},{"t":"옛날에도 일자리가 많은 공장 지대에만 모여 살았기 때문에","mis":"SO6-2-u3-X01"}],"mis":"SO6-2-u3-X01","explanation":["옛날엔 농사가 중요했어요.","자연환경을 봤어요.","평야·해안에 모였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#10','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C3',2,'ox','auto','대체로 오세아니아에 있는 나라들은 인구수가 많아요.',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"ox","stem":"대체로 오세아니아에 있는 나라들은 인구수가 많아요.","answer":"X","reason_options":[{"t":"대체로 아시아의 나라들이 인구수가 많고 오세아니아의 나라들은 적기 때문에","correct":true},{"t":"오세아니아는 세계에서 인구가 가장 많은 대륙이기 때문에","mis":"SO6-2-u3-X07"}],"mis":"SO6-2-u3-X07","explanation":["100명 마을에서 오세아니아는 1명이에요.","인구수가 적어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#11','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C4',2,'ox','auto','인구가 줄어드는 나라는 시간이 지나면 인구 밀도가 점차 낮아질 거예요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"ox","stem":"인구가 줄어드는 나라는 시간이 지나면 인구 밀도가 점차 낮아질 거예요.","answer":"O","reason_options":[{"t":"면적은 그대로인데 인구수가 줄기 때문에","correct":true},{"t":"인구가 줄면 면적도 함께 줄기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["면적은 그대로예요.","사람이 줄어요.","밀도가 낮아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#12','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C5',2,'ox','auto','1960년보다 2020년에 세계의 노년층 인구 비율이 늘었어요.',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"ox","stem":"1960년보다 2020년에 세계의 노년층 인구 비율이 늘었어요.","answer":"O","reason_options":[{"t":"평균 수명이 늘고 출생률이 낮아지며 노년층 비율이 늘었기 때문에","correct":true},{"t":"노년층은 해마다 줄어들기만 하기 때문에","mis":"SO6-2-u3-X12"}],"mis":"SO6-2-u3-X12","explanation":["노년층 비율이 늘었어요.","유소년층은 줄었어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#13','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C6',2,'ox','auto','인구 구조는 경제와 문화 같은 우리 생활과 밀접한 관계가 있어요.',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"ox","stem":"인구 구조는 경제와 문화 같은 우리 생활과 밀접한 관계가 있어요.","answer":"O","reason_options":[{"t":"많은 연령층에 따라 필요한 시설과 사는 물건이 달라지기 때문에","correct":true},{"t":"인구 구조는 생활과 아무 관계가 없기 때문에","mis":"SO6-2-u3-X13"}],"mis":"SO6-2-u3-X13","explanation":["필요한 시설이 달라요.","시장도 달라요.","생활과 관계있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#14','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C7',2,'ox','auto','누리반 신문 ⑤처럼 숲이 줄면 탄소 흡수가 줄어 지구 온난화가 빨라질 수 있어요.',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"ox","stem":"누리반 신문 ⑤처럼 숲이 줄면 탄소 흡수가 줄어 지구 온난화가 빨라질 수 있어요.","answer":"O","reason_options":[{"t":"열대 우림은 탄소를 많이 흡수해 온난화 속도를 늦추기 때문에","correct":true},{"t":"숲은 탄소와 아무 관계가 없기 때문에","mis":"SO6-2-u3-X15"}],"mis":"SO6-2-u3-X15","explanation":["숲이 탄소를 흡수해요.","숲이 줄면 흡수가 줄어요.","온난화가 빨라져요."],"asset":{"type":"passage","lines":["농사·목축·산업으로 열대 우림이 크게 줄었다.","동식물이 살 곳을 잃고 있다.","탄소를 흡수하던 숲이 줄어 지구 온난화가 빨라질 수 있다."],"title":"누리반 신문 ⑤ 사라지는 숲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#15','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',2,'ox','auto','개인은 녹색 제품을 쓰고 분리배출을 하며 지속가능한 미래를 위해 노력할 수 있어요.',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"ox","stem":"개인은 녹색 제품을 쓰고 분리배출을 하며 지속가능한 미래를 위해 노력할 수 있어요.","answer":"O","reason_options":[{"t":"개인도 생활 속에서 환경을 지키는 일을 할 수 있기 때문에","correct":true},{"t":"개인은 지구촌 문제와 관계없기 때문에","mis":"SO6-2-u3-X19"}],"mis":"SO6-2-u3-X19","explanation":["생활 속 실천이에요.","개인도 할 수 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#16','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',2,'ox','auto','실천 계획을 세울 때는 일상생활에서 실천할 수 있는지와 효과가 있는지를 함께 생각해요.',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"ox","stem":"실천 계획을 세울 때는 일상생활에서 실천할 수 있는지와 효과가 있는지를 함께 생각해요.","answer":"O","reason_options":[{"t":"실천할 수 없으면 이어 갈 수 없고 효과가 없으면 문제가 풀리지 않기 때문에","correct":true},{"t":"실천하기 어려울수록 좋은 계획이기 때문에","mis":"SO6-2-u3-X21"}],"mis":"SO6-2-u3-X21","explanation":["할 수 있어야 해요.","효과도 있어야 해요.","둘 다 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#17','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C2',3,'error','auto','세계의 인구 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":17,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"error","stem":"세계의 인구 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「유럽이 차지하는 비율이 줄었으니 유럽 인구수도 반드시 줄었어.」","correct":true,"mis_target":"SO6-2-u3-X05"},{"t":"지아 — 「세계 인구는 1950년보다 크게 늘었어.」","mis":"SO6-2-u3-X05"},{"t":"세윤 — 「아프리카가 차지하는 비율이 크게 늘었어.」","mis":"SO6-2-u3-X05"}],"explanation":["비율과 인구수는 달라요.","전체가 크게 늘었어요.","현우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#18','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C4',3,'error','auto','인구 밀도 자료를 보는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X10']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"error","stem":"인구 밀도 자료를 보는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「나라별 인구 밀도 숫자만 모두 외우면 돼.」","correct":true,"mis_target":"SO6-2-u3-X23"},{"t":"가람 — 「수치를 견주어 까닭을 찾아봐야 해.」","mis":"SO6-2-u3-X23"},{"t":"하온 — 「기후와 지형을 함께 생각해야 해.」","mis":"SO6-2-u3-X10"}],"explanation":["외우는 게 목표가 아니에요.","견주고 까닭을 찾아요.","은재가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#19','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C6',3,'error','auto','인구 구조와 경제 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"error","stem":"인구 구조와 경제 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「청장년층이 많은 나라는 물건을 사는 사람이 적어 기업이 관심 없어.」","correct":true,"mis_target":"SO6-2-u3-X13"},{"t":"민우 — 「인도네시아는 젊은 소비자가 많아 기업이 주목해.」","mis":"SO6-2-u3-X13"},{"t":"나연 — 「외국인 근로자가 많으면 청장년층이 많아져.」","mis":"SO6-2-u3-X13"}],"explanation":["청장년층은 소비가 활발해요.","기업이 주목해요.","규리가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#20','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C7',3,'error','auto','누리반 신문 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"error","stem":"누리반 신문 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「숲이 사라지는 건 그 나라 일이니 우리와는 관계없어.」","correct":true,"mis_target":"SO6-2-u3-X16"},{"t":"서아 — 「숲이 줄면 동식물이 살 곳을 잃어.」","mis":"SO6-2-u3-X15"},{"t":"윤우 — 「숲이 줄면 온난화가 빨라질 수 있어.」","mis":"SO6-2-u3-X15"}],"explanation":["숲은 지구 전체와 이어져요.","탄소 흡수가 줄어요.","도하가 잘못 말했어요."],"asset":{"type":"passage","lines":["농사·목축·산업으로 열대 우림이 크게 줄었다.","동식물이 살 곳을 잃고 있다.","탄소를 흡수하던 숲이 줄어 지구 온난화가 빨라질 수 있다."],"title":"누리반 신문 ⑤ 사라지는 숲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#21','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',3,'error','auto','지속가능한 미래를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X18','SO6-2-u3-X19']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"error","stem":"지속가능한 미래를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「지금 우리가 편하게 다 쓰고, 미래 세대는 알아서 하면 돼.」","correct":true,"mis_target":"SO6-2-u3-X18"},{"t":"수호 — 「미래 세대에 지구를 물려줘야 해.」","mis":"SO6-2-u3-X18"},{"t":"예진 — 「모든 주체가 함께 노력해야 해.」","mis":"SO6-2-u3-X19"}],"explanation":["미래 세대를 생각해요.","지금 보존해야 해요.","하람이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#22','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',3,'error','auto','세계시민의 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"error","stem":"세계시민의 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"주원 — 「먼 나라 문제는 내 일이 아니니 실천할 필요 없어.」","correct":true,"mis_target":"SO6-2-u3-X16"},{"t":"혜린 — 「작은 일부터 책임감 있게 실천하자.」","mis":"SO6-2-u3-X21"},{"t":"도경 — 「친구들과 함께 실천하면 더 넓게 퍼져.」","mis":"SO6-2-u3-X21"}],"explanation":["지구촌 문제는 모두의 문제예요.","세계시민은 관심을 둬요.","주원이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#23','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C8',4,'mc','auto','누리반 신문 ④·⑤·⑥을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":23,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"mc","stem":"누리반 신문 ④·⑤·⑥을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"숲의 훼손과 옷의 낭비 같은 일이 지구 전체의 환경에 이어져 먼 섬나라까지 피해를 주므로 내 생활부터 바꿔야 한다","correct":true},{"t":"세 기사는 서로 아무 관계가 없다","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제는 섬나라만 겪는다","mis":"SO6-2-u3-X16"},{"t":"옷을 많이 살수록 환경이 좋아진다","mis":"SO6-2-u3-X21"}],"explanation":["숲과 옷이 환경과 이어져요.","피해는 지구 곳곳에 와요.","내 생활부터 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#24','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C5',4,'essay','teacher','누리반 신문 ③을 보고 가람국과 누리국의 인구 구조를 출생률·평균 수명과 이어 견주어 쓰고, 두 나라에 각각 더 필요한 시설을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C5","difficulty":4,"kind":"essay","stem":"누리반 신문 ③을 보고 가람국과 누리국의 인구 구조를 출생률·평균 수명과 이어 견주어 쓰고, 두 나라에 각각 더 필요한 시설을 쓰세요.","answer_guide":{"answer":"예: 가람국은 아기가 많이 태어나고 평균 수명이 짧아 아래층이 넓은, 유소년층 비율이 높은 인구 구조이다. 누리국은 아기가 적게 태어나고 평균 수명이 길어 위층이 넓은, 노년층 비율이 높은 인구 구조이다. 가람국에는 유치원과 학교가, 누리국에는 요양원과 노인 복지 센터가 더 필요하다.","scoring_points":["가람국의 인구 구조와 까닭을 썼는가","누리국의 인구 구조와 까닭을 썼는가","두 나라에 필요한 시설을 썼는가"]},"explanation":["출생률과 수명을 봐요.","피라미드 모양을 견줘요.","필요한 시설을 이어요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_c#25','soc',6,2,'u3','','g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',4,'essay','teacher','누리반 신문 ⑧처럼 나만의 실천 인증 릴레이 계획을 세우세요. 세계시민의 뜻을 쓰고, 더하기(+) 노력과 빼기(−) 노력을 하나씩 정한 뒤 실천하고 기록하고 알리는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"누리반 신문 ⑧처럼 나만의 실천 인증 릴레이 계획을 세우세요. 세계시민의 뜻을 쓰고, 더하기(+) 노력과 빼기(−) 노력을 하나씩 정한 뒤 실천하고 기록하고 알리는 방법을 쓰세요.","answer_guide":{"answer":"예: 세계시민은 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람이다. 더하기 노력은 개인 물병 쓰기, 빼기 노력은 일회용 컵 줄이기로 정했다. 3일 동안 학교와 집에서 실천하며 개인 물병을 쓰는 모습을 사진으로 찍고, 언제 어디서 몇 번 했는지 기록해 다음 차례 친구에게 알리겠다.","scoring_points":["세계시민의 뜻을 썼는가","더하기·빼기 노력을 알맞게 정했는가","실천·기록·알리기 방법을 구체적으로 썼는가"]},"explanation":["세계시민의 뜻을 써요.","더하기·빼기를 구분해요.","릴레이로 이어요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#1','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C2',1,'ox','auto','세계의 인구는 특정한 지역에 모여 있어요.',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"ox","stem":"세계의 인구는 특정한 지역에 모여 있어요.","answer":"O","reason_options":[{"t":"생활하기 좋은 환경을 갖춘 곳에 사람이 모이기 때문에","correct":true},{"t":"모든 곳에 사람이 똑같이 살기 때문에","mis":"SO6-2-u3-X02"}],"mis":"SO6-2-u3-X02","explanation":["빽빽한 곳이 있어요.","드문 곳도 있어요.","모여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#2','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C4',1,'ox','auto','누리반 신문 ②의 「땅이 넓다고 사람이 많이 사는 것은 아니었다」는 말은 캐나다의 예와 맞아요.',ARRAY['SO6-2-u3-X06']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"ox","stem":"누리반 신문 ②의 「땅이 넓다고 사람이 많이 사는 것은 아니었다」는 말은 캐나다의 예와 맞아요.","answer":"O","reason_options":[{"t":"캐나다는 땅이 넓지만 냉대 기후가 넓어 인구 밀도가 매우 낮기 때문에","correct":true},{"t":"캐나다는 땅이 넓어 인구 밀도가 가장 높기 때문에","mis":"SO6-2-u3-X06"}],"mis":"SO6-2-u3-X06","explanation":["캐나다는 넓어요.","그런데 약 4명이에요.","말과 맞아요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#3','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C5',1,'ox','auto','인구 피라미드의 가로축은 남자와 여자의 인구 비율을 나타내요.',ARRAY['SO6-2-u3-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"ox","stem":"인구 피라미드의 가로축은 남자와 여자의 인구 비율을 나타내요.","answer":"O","reason_options":[{"t":"왼쪽은 남자, 오른쪽은 여자 비율로 나누어 그리기 때문에","correct":true},{"t":"가로축은 나라의 면적을 나타내기 때문에","mis":"SO6-2-u3-X11"}],"mis":"SO6-2-u3-X11","explanation":["가로는 남녀예요.","세로는 나이예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#4','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C7',1,'ox','auto','자원과 에너지 고갈, 생태계 파괴, 기후변화, 난민은 모두 지구촌을 위협하는 문제예요.',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"ox","stem":"자원과 에너지 고갈, 생태계 파괴, 기후변화, 난민은 모두 지구촌을 위협하는 문제예요.","answer":"O","reason_options":[{"t":"지구촌 곳곳에서 나타나 사람들의 삶을 위협하기 때문에","correct":true},{"t":"이 문제들은 지구촌과 관계없는 일이기 때문에","mis":"SO6-2-u3-X15"}],"mis":"SO6-2-u3-X15","explanation":["네 문제가 있어요.","곳곳에서 나타나요.","모두 위협이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#5','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C8',1,'ox','auto','누리반 신문 ④의 기자 한마디처럼 탄소를 거의 내지 않는 나라도 기후변화의 피해를 입어요.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"ox","stem":"누리반 신문 ④의 기자 한마디처럼 탄소를 거의 내지 않는 나라도 기후변화의 피해를 입어요.","answer":"O","reason_options":[{"t":"기후변화는 지구 전체에 영향을 주기 때문에","correct":true},{"t":"탄소를 낸 나라만 피해를 입기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["투발루는 탄소를 거의 안 내요.","그런데 피해를 입어요.","모두의 문제예요."],"asset":{"type":"passage","lines":["남태평양의 섬나라 투발루는 해수면이 높아져 섬 두 개가 물에 잠겼다.","주민들은 다른 나라로 옮겨 갈 계획을 세우고 있다.","기자 한마디 — 탄소를 거의 내지 않는 작은 나라가 가장 먼저 피해를 본다."],"title":"누리반 신문 ④ 섬나라 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#6','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C9',1,'ox','auto','지속가능한 미래는 미래 세대에 지구 환경을 물려주려는 노력 속에서 이루어져요.',ARRAY['SO6-2-u3-X18']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"ox","stem":"지속가능한 미래는 미래 세대에 지구 환경을 물려주려는 노력 속에서 이루어져요.","answer":"O","reason_options":[{"t":"지금 세대가 환경을 개선하고 보존해야 미래 세대도 살 수 있기 때문에","correct":true},{"t":"지금 세대만 편리하면 되기 때문에","mis":"SO6-2-u3-X18"}],"mis":"SO6-2-u3-X18","explanation":["미래 세대를 생각해요.","환경을 보존해요.","물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#7','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C10',1,'ox','auto','국제 연합 난민 기구는 난민을 보호하고 필요한 물품과 의료를 제공해요.',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"ox","stem":"국제 연합 난민 기구는 난민을 보호하고 필요한 물품과 의료를 제공해요.","answer":"O","reason_options":[{"t":"난민을 돕기 위해 국제 연합이 만든 기구이기 때문에","correct":true},{"t":"난민을 다른 나라로 쫓아내는 기구이기 때문에","mis":"SO6-2-u3-X20"}],"mis":"SO6-2-u3-X20","explanation":["난민을 돕는 기구예요.","물품과 의료를 줘요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#8','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',1,'ox','auto','장바구니 들고 가기는 더 자주 해야 할 더하기(+) 노력이에요.',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"ox","stem":"장바구니 들고 가기는 더 자주 해야 할 더하기(+) 노력이에요.","answer":"O","reason_options":[{"t":"일회용 봉투 대신 쓰는 일을 더 늘려야 하기 때문에","correct":true},{"t":"장바구니는 쓰지 않을수록 좋기 때문에","mis":"SO6-2-u3-X21"}],"mis":"SO6-2-u3-X21","explanation":["더 자주 해요.","봉투를 대신해요.","더하기 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#9','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C1',2,'error','auto','인구 분포의 요인을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"error","stem":"인구 분포의 요인을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「교통과 산업은 자연이 만든 환경이야.」","correct":true,"mis_target":"SO6-2-u3-X01"},{"t":"예나 — 「기온과 지형은 자연환경이야.」","mis":"SO6-2-u3-X01"},{"t":"도윤 — 「오늘날엔 일자리가 많은 곳에 사람이 모여.」","mis":"SO6-2-u3-X01"}],"explanation":["교통과 산업은 사람이 만들어요.","인문환경이에요.","하준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#10','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C3',2,'error','auto','누리반 친구들이 세계 여러 나라의 인구수를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X07','SO6-2-u3-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"error","stem":"누리반 친구들이 세계 여러 나라의 인구수를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서연 — 「리비아는 국토가 넓어서 인구가 아주 많아.」","correct":true,"mis_target":"SO6-2-u3-X06"},{"t":"준호 — 「인도는 세계에서 인구가 가장 많아.」","mis":"SO6-2-u3-X07"},{"t":"채아 — 「아프리카는 인구 성장률이 높아.」","mis":"SO6-2-u3-X08"}],"explanation":["리비아는 대부분 사막이에요.","면적에 비해 인구가 적어요.","서연이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#11','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C4',2,'error','auto','누리반 신문 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X10']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"error","stem":"누리반 신문 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가윤 — 「방글라데시는 땅이 넓어서 인구 밀도가 높아.」","correct":true,"mis_target":"SO6-2-u3-X09"},{"t":"민재 — 「방글라데시는 평야와 벼농사 덕에 사람이 많이 살아.」","mis":"SO6-2-u3-X10"},{"t":"수빈 — 「캐나다는 추워서 인구 밀도가 낮아.」","mis":"SO6-2-u3-X10"}],"explanation":["밀도는 넓이로만 정해지지 않아요.","면적에 비해 사람이 많아서예요.","가윤이 잘못 말했어요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km² · 넓은 평야와 벼농사","캐나다 — 약 4명/km² · 넓은 냉대 기후","우리나라 — 약 515명/km²","기자 한마디 — 땅이 넓다고 사람이 많이 사는 것은 아니었다."],"title":"누리반 신문 ② 인구 밀도 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#12','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C5',2,'error','auto','누리반 신문 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"error","stem":"누리반 신문 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「누리국은 아기가 많이 태어나서 아래층이 좁아.」","correct":true,"mis_target":"SO6-2-u3-X12"},{"t":"시후 — 「가람국은 유소년층이 많아.」","mis":"SO6-2-u3-X12"},{"t":"하늘 — 「누리국은 노년층이 많아.」","mis":"SO6-2-u3-X12"}],"explanation":["누리국은 아기가 적게 태어나요.","그래서 아래층이 좁아요.","로아의 까닭이 틀렸어요."],"asset":{"type":"passage","lines":["가람국 피라미드 — 아래층이 넓고 위로 갈수록 좁다.","가람국 — 아기가 많이 태어나고 평균 수명이 짧다.","누리국 피라미드 — 아래층이 좁고 위층이 넓다.","누리국 — 아기가 적게 태어나고 평균 수명이 길다."],"title":"누리반 신문 ③ 두 나라 인구 피라미드(가상)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#13','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C6',2,'error','auto','누리반 신문 ③을 읽고 인구 구조에 맞는 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"error","stem":"누리반 신문 ③을 읽고 인구 구조에 맞는 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「노년층이 많은 나라엔 유치원을 가장 많이 지어야 해.」","correct":true,"mis_target":"SO6-2-u3-X13"},{"t":"지민 — 「청장년층이 많은 나라엔 젊은 소비자가 많아.」","mis":"SO6-2-u3-X13"},{"t":"나은 — 「유소년층이 많은 나라엔 학교가 필요해.」","mis":"SO6-2-u3-X13"}],"explanation":["노인이 많으면 노인 시설이 필요해요.","유치원은 어린이 시설이에요.","예준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#14','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C7',2,'error','auto','지구촌 문제의 원인을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"error","stem":"지구촌 문제의 원인을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「난민 문제는 화석 연료를 많이 써서 생기는 거야.」","correct":true,"mis_target":"SO6-2-u3-X15"},{"t":"서진 — 「기후변화는 화석 연료와 관계있어.」","mis":"SO6-2-u3-X15"},{"t":"주안 — 「난민은 전쟁 때문에 생기기도 해.」","mis":"SO6-2-u3-X15"}],"explanation":["난민은 전쟁·재난 때문이에요.","화석 연료는 기후변화예요.","태린이 바꿔 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#15','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C10',2,'error','auto','단체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"error","stem":"단체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「국경 없는 의사회는 나라들이 모여 만든 국제기구야.」","correct":true,"mis_target":"SO6-2-u3-X20"},{"t":"유나 — 「국제 연합 아동 기금은 어린이를 돕는 국제기구야.」","mis":"SO6-2-u3-X20"},{"t":"건우 — 「그린피스는 바다 생태계를 지키는 비정부 기구야.」","mis":"SO6-2-u3-X20"}],"explanation":["국경 없는 의사회는 민간단체예요.","비정부 기구예요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#16','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C12',2,'error','auto','그림책 스토리보드를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"error","stem":"그림책 스토리보드를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다빈 — 「장면마다 그림과 상관없는 멋진 글을 넣으면 돼.」","correct":true,"mis_target":"SO6-2-u3-X22"},{"t":"지후 — 「그림 순서가 이야기 흐름에 맞아야 해.」","mis":"SO6-2-u3-X22"},{"t":"소율 — 「독자 수준에 맞게 써야 해.」","mis":"SO6-2-u3-X22"}],"explanation":["그림과 글이 짝을 이뤄요.","흐름에 맞아야 해요.","다빈이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#17','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C1',3,'ox','auto','동아시아와 남부 아시아에 사람이 많은 것은 온화한 기후의 평야에서 농업이 발달한 자연환경의 영향이 커요.',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":17,"concept":"SO6-2-u3-C1","difficulty":3,"kind":"ox","stem":"동아시아와 남부 아시아에 사람이 많은 것은 온화한 기후의 평야에서 농업이 발달한 자연환경의 영향이 커요.","answer":"O","reason_options":[{"t":"기후와 지형이 농사짓기에 알맞아 사람이 모였기 때문에","correct":true},{"t":"그 지역은 사막이라 사람이 모였기 때문에","mis":"SO6-2-u3-X03"}],"mis":"SO6-2-u3-X03","explanation":["온화한 기후예요.","평야에서 농사를 지어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#18','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C3',3,'ox','auto','아프리카 나라들의 높은 인구 성장률이 계속되면 그 나라들의 인구 밀도도 점차 높아질 거예요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"ox","stem":"아프리카 나라들의 높은 인구 성장률이 계속되면 그 나라들의 인구 밀도도 점차 높아질 거예요.","answer":"O","reason_options":[{"t":"면적은 그대로인데 인구수가 계속 늘어나기 때문에","correct":true},{"t":"인구가 늘면 인구 밀도는 낮아지기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["인구가 늘어요.","면적은 그대로예요.","밀도가 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#19','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C5',3,'ox','auto','인구 구조를 살펴보면 그 나라의 미래 인구 변화를 예상할 수 있어요.',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"ox","stem":"인구 구조를 살펴보면 그 나라의 미래 인구 변화를 예상할 수 있어요.","answer":"O","reason_options":[{"t":"지금의 연령층이 나이를 먹으며 앞으로의 인구 모습을 만들기 때문에","correct":true},{"t":"인구 구조는 지금만 보여 주고 미래와는 관계없기 때문에","mis":"SO6-2-u3-X13"}],"mis":"SO6-2-u3-X13","explanation":["지금 어린이가 자라요.","지금 어른이 노인이 돼요.","미래를 예상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#20','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C8',3,'ox','auto','지구촌 문제를 조사한 붙임쪽지를 세계지도에 모으면 지구촌 곳곳의 문제를 한눈에 볼 수 있어요.',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"ox","stem":"지구촌 문제를 조사한 붙임쪽지를 세계지도에 모으면 지구촌 곳곳의 문제를 한눈에 볼 수 있어요.","answer":"O","reason_options":[{"t":"나라마다 문제 상황과 원인을 지도 위에서 견줄 수 있기 때문에","correct":true},{"t":"지도에 붙이면 문제가 저절로 해결되기 때문에","mis":"SO6-2-u3-X17"}],"mis":"SO6-2-u3-X17","explanation":["나라마다 붙여요.","한눈에 봐요.","견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#21','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C9',3,'ox','auto','노력 카드를 다섯 주체의 줄에 모았을 때 모든 줄이 팽팽해져야 지구가 올라간 것은 모두의 노력이 모여야 한다는 뜻이에요.',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"ox","stem":"노력 카드를 다섯 주체의 줄에 모았을 때 모든 줄이 팽팽해져야 지구가 올라간 것은 모두의 노력이 모여야 한다는 뜻이에요.","answer":"O","reason_options":[{"t":"한 주체만으로는 지구촌 문제를 해결할 수 없기 때문에","correct":true},{"t":"한 주체만 노력해도 충분하기 때문에","mis":"SO6-2-u3-X19"}],"mis":"SO6-2-u3-X19","explanation":["모든 줄이 필요해요.","한 줄로는 안 돼요.","모두가 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#22','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C12',3,'ox','auto','그림책 발표회에서는 다른 모둠의 그림책 내용과 수준이 적절한지 살펴보며 들어요.',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"ox","stem":"그림책 발표회에서는 다른 모둠의 그림책 내용과 수준이 적절한지 살펴보며 들어요.","answer":"O","reason_options":[{"t":"독자에게 알맞게 단원 내용을 전했는지 함께 살피는 자리이기 때문에","correct":true},{"t":"발표회에서는 그림 장수만 세면 되기 때문에","mis":"SO6-2-u3-X22"}],"mis":"SO6-2-u3-X22","explanation":["내용을 살펴요.","수준을 살펴요.","서로 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#23','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',4,'mc','auto','누리반 신문 ⑦과 ⑧을 함께 볼 때 우리 반의 실천이 지니는 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X19']::text[],false,'{"seq":23,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"mc","stem":"누리반 신문 ⑦과 ⑧을 함께 볼 때 우리 반의 실천이 지니는 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기업·국가·국제기구·비정부 기구의 노력에 개인의 실천이 더해져야 지속가능한 미래를 만들 수 있다","correct":true},{"t":"큰 단체가 있으니 개인의 실천은 필요 없다","mis":"SO6-2-u3-X21"},{"t":"우리 반의 실천만 있으면 다른 노력은 필요 없다","mis":"SO6-2-u3-X19"},{"t":"실천은 사진만 찍으면 끝난다","mis":"SO6-2-u3-X21"}],"explanation":["여러 주체가 노력해요.","개인도 한 주체예요.","모두 더해져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#24','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C8',4,'essay','teacher','누리반 신문 ④를 붙임쪽지(지역·문제 상황·문제 원인)로 정리하고, 이 문제가 우리와도 관계있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"essay","stem":"누리반 신문 ④를 붙임쪽지(지역·문제 상황·문제 원인)로 정리하고, 이 문제가 우리와도 관계있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 지역 — 남태평양의 섬나라 투발루. 문제 상황 — 해수면이 높아져 섬 두 개가 물에 잠겼고 주민들이 다른 나라로 옮겨 갈 계획을 세운다. 문제 원인 — 탄소 배출로 지구 온도가 올라 해수면이 높아졌다. 탄소는 어느 나라에서 나오든 지구 전체의 기후를 바꾸므로 우리가 내는 탄소도 투발루에 피해를 줄 수 있어 우리와 관계있다.","scoring_points":["지역·문제 상황·문제 원인을 썼는가","원인을 기후변화와 이어 썼는가","우리와 관계있는 까닭을 썼는가"]},"explanation":["세 칸을 채워요.","기후변화가 원인이에요.","우리 탄소도 영향을 줘요."],"asset":{"type":"passage","lines":["남태평양의 섬나라 투발루는 해수면이 높아져 섬 두 개가 물에 잠겼다.","주민들은 다른 나라로 옮겨 갈 계획을 세우고 있다.","기자 한마디 — 탄소를 거의 내지 않는 작은 나라가 가장 먼저 피해를 본다."],"title":"누리반 신문 ④ 섬나라 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u3_review_d#25','soc',6,2,'u3','','g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C12',4,'essay','teacher','누리반 신문 ⑧처럼 1학년 동생들에게 읽어 줄 그림책을 만든다고 생각하고, 주제와 줄거리를 쓴 뒤 누리반 신문 내용을 바탕으로 장면 세 개를 그림 설명과 글로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"essay","stem":"누리반 신문 ⑧처럼 1학년 동생들에게 읽어 줄 그림책을 만든다고 생각하고, 주제와 줄거리를 쓴 뒤 누리반 신문 내용을 바탕으로 장면 세 개를 그림 설명과 글로 쓰세요.","answer_guide":{"answer":"예: 주제 — 지구촌 사람들이 함께 지구를 지켜요. 줄거리 — 사람이 많이 사는 곳도 적게 사는 곳도 모두 한 지구에 살고, 숲이 사라지고 섬이 잠기는 문제를 우리가 함께 실천해 막을 수 있다. 장면 1 — 빼곡한 도시와 눈 덮인 땅(글: 사람이 많은 곳도 적은 곳도 있어요). 장면 2 — 베어진 숲과 물에 잠기는 작은 섬(글: 지구가 아파요). 장면 3 — 아이들이 장바구니를 들고 전등을 끄는 모습(글: 우리가 함께 지켜요).","scoring_points":["독자에 맞는 주제와 줄거리를 썼는가","단원 내용이 담긴 장면 세 개를 썼는가","쉬운 글로 흐름에 맞게 썼는가"]},"explanation":["독자는 1학년이에요.","단원 내용을 담아요.","쉽게, 흐름 있게 써요."],"asset":{"type":"passage","lines":["우리 반 실천 릴레이 — 더하기는 장바구니, 빼기는 안 쓰는 전등 끄기","사진을 찍어 기록하고 다음 친구에게 바통을 넘겼다.","1학년 동생들에게 읽어 줄 그림책 스토리보드도 만들기로 했다."],"title":"누리반 신문 ⑧ 우리 반 실천"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
